-- Perfect Video modules 1-3 v4.2: expanded administrator-review drafts only.
-- Adds a field diagnostic and a second auto-graded scenario to each v4.1 draft.
DO $pv_v42_seed$
DECLARE
 specs jsonb := $pv_v42_payload$[{"module_id":"s02-m01","lesson_id":"pv01-01","title":"Избери реален проект и запиши началната точка","objective":"да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш","hook":"Преди да мислиш за камерата, трябва да знаеш какво ще промениш с това видео.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Преди да мислиш за камерата, трябва да знаеш какво ще промениш с това видео.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Започни от една проверима промяна за зрителя, не от красив кадър или любима тема. Избери резултат, който може да се види в поведението: човекът разбира офертата, знае как да започне или прави конкретна следваща стъпка.\n\nПреди да предложиш кадър, отдели какво си видял, какво мислиш, че означава и какво можеш честно да обещаеш. Източникът и периодът пазят сигнала от догадката."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Запиши отправното състояние с числител, знаменател и период. „Имахме 12 запитвания“ е непълно без да знаеш за колко посещения, от кой канал и за какво време. Отбележи и какво не знаеш; не запълвай празнината с предположение. Едно видео може да помогне, но рядко е единствената причина за промяна.\n\nГраница на правилото: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери изпълним проект с достъп до реален зрител и разрешение за снимане.\n2. Назови едно затруднение, което вече си наблюдавал; отдели цитат или действие от собственото си тълкуване.\n3. Запиши изходната метрика, източника и периода; ако липсват, отбележи ги като неизвестни.\n4. Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш.\n\nСтоп-сигнал: „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите. Без изходни данни няма сравнение, а без проследяване не знаеш откъде е дошло новото запитване. Ако това се случи, приложи корекцията преди да продължиш: Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Ателие „Ръце в глина“ получава 31 посещения на страницата за въвеждащия курс за две седмици и 4 записвания. Собственичката смята, че хората се отказват заради цената, но три разговора показват друго: новаците не знаят дали трябва да носят материали и се притесняват, че „нямат усет“. Началният факт е 4 от 31, а причината още е хипотеза. Първото видео може да показва как започва занятието; не може само по себе си да докаже защо са се записали.\n\nРешение в този случай:\nПостави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа.\n\nГраница на извода:\nАко проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите. Без изходни данни няма сравнение, а без проследяване не знаеш откъде е дошло новото запитване."},"after":{"label":"По-доброто решение","text":"Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа.\n\nПреди да продължиш: Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Сравни едни и същи точки преди и след публикуването: един канал, еднакъв период и еднакво събитие за успех. Ако кампания, сезон или цена са се променили между двете измервания, запиши го отделно. Кликът след видеото не доказва, че видеото е причинило покупката; доказва само, че човекът е преминал нататък.\n\nКритерий за приемане: Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш.\n\nКогато пробата се провали:\nСимптом: „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите.\nКорекция: Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Избери реален проект и запиши началната точка“?","options":[{"id":"a","label":"Започни от една проверима промяна за зрителя, не от красив кадър или любима тема."},{"id":"b","label":"„Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Започни от една проверима промяна за зрителя, не от красив кадър или любима тема. Избери резултат, който може да се види в поведението: човекът разбира офертата, знае как да започне или прави конкретна следваща стъпка. Слабият ход е: „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите. Без изходни данни няма сравнение, а без проследяване не знаеш откъде е дошло новото запитване. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Ателие „Ръце в глина“ получава 31 посещения на страницата за въвеждащия курс за две седмици и 4 записвания. Собственичката смята, че хората се отказват заради цената, но три разговора показват друго: новаците не знаят дали трябва да носят материали и се притесняват, че „нямат усет“. Началният факт е 4 от 31, а причината още е хипотеза. Първото видео може да показва как започва занятието; не може само по себе си да докаже защо са се записали.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал."},{"id":"b","label":"„Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа. Грешният път — „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху… — оставя риска нерешен. Провери и границата: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Избери реален проект и запиши началната точка“?","options":[{"id":"a","label":"Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията."},{"id":"b","label":"„Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Започни от една проверима промяна за зрителя, не от красив кадър или любима тема. Избери резултат, който може да се види в поведението: човекът разбира офертата, знае как да започне или прави конкретна следваща стъпка.","Първо: Избери изпълним проект с достъп до реален зрител и разрешение за снимане. После: Назови едно затруднение, което вече си наблюдавал; отдели цитат или действие от собственото си тълкуване.","Следи за грешния ход: „Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху…"],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.","items":[{"id":"s2","text":"Назови едно затруднение, което вече си наблюдавал; отдели цитат или действие от собственото си тълкуване."},{"id":"s3","text":"Запиши изходната метрика, източника и периода; ако липсват, отбележи ги като неизвестни."},{"id":"s4","text":"Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш."},{"id":"s1","text":"Избери изпълним проект с достъп до реален зрител и разрешение за снимане."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа. Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Ателие „Ръце в глина“ получава 31 посещения на страницата за въвеждащия курс за две седмици и 4 записвания.\n\nПроменено условие: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал."},{"id":"b","label":"„Ще направим вирусно видео за глина и ще удвоим продажбите.“ Това събира три недоказани обещания: популярност, причина за отказ и ефект върху продажбите."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Постави ограничена цел: „Видеото ще обясни какво получава начинаещият и ще насочи към графика.“ Запази броя посещения и записвания за един и същ период и канал. След публикация отбелязвай отделно гледанията, посещенията на графика и записванията; не приписвай всяка промяна само на клипа. Границата тук е: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.\n\nРаботна карта за наблюдението: точни думи/действие; източник и дата; канал и период; брой случаи; извод; неизвестно; следващият тест. Така отделяш факт от тълкуване и можеш да проследиш защо темата е избрана.\n\nКарта за работа — Избери реален проект и запиши началната точка\n1. Избери изпълним проект с достъп до реален зрител и разрешение за снимане.\n2. Назови едно затруднение, което вече си наблюдавал; отдели цитат или действие от собственото си тълкуване.\n3. Запиши изходната метрика, източника и периода; ако липсват, отбележи ги като неизвестни.\n4. Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-02","title":"Определи за кого е видеото и кога ще го гледа","objective":"да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане","hook":"„Всички“ не е аудитория, към която можеш да напишеш ясна сцена.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Всички“ не е аудитория, към която можеш да напишеш ясна сцена.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Описвай аудиторията през ситуацията и задачата ѝ. Възраст, професия и град могат да помогнат за контекст, но сами не казват какъв въпрос има човекът, какво го спира и кога видеото ще му е удобно."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Мисли за „работата“, която зрителят иска да свърши: какво се случва точно преди нуждата, как изглежда добър резултат и каква е пречката. Добави средата на гледане: телефон или компютър, звук включен или не, няколко секунди или спокойно време. Не превръщай един интервюиран човек в описание на цял пазар.\n\nГраница на правилото: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери конкретен момент, в който зрителят среща проблема.\n2. Назови неговата задача с глагол: избере, сравни, разбере, провери или направи.\n3. Отбележи предишния опит, главната пречка и какво би било достатъчно полезно.\n4. Съобрази формат и звук с мястото, където човекът вероятно гледа.\n\nСтоп-сигнал: „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение. Възрастта не доказва навик за гледане и бързината може да направи процеса по-труден за разбиране. Ако това се случи, приложи корекцията преди да продължиш: Опиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За курса по керамика „начинаещи на 20–35 години“ е твърде общо. Полезният профил е: човек, който иска да дойде на първо занимание с приятел, не е работил с глина и проверява програмата от телефона вечер. Иска да разбере дали материалите са включени и дали ще си тръгне с готов предмет. Това определя кои кадри и отговори са нужни.\n\nРешение в този случай:\nОпиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи.\n\nГраница на извода:\nНе използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение. Възрастта не доказва навик за гледане и бързината може да направи процеса по-труден за разбиране."},"after":{"label":"По-доброто решение","text":"Опиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи.\n\nПреди да продължиш: Съобрази формат и звук с мястото, където човекът вероятно гледа."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Профилът е полезен само ако диктува избор на сцена или канал. Запиши ситуацията, момента на гледане, устройството, наличния звук и пречката за действие. Не прави предположение за навици по възраст или професия. Провери профила с човек, който наскоро е направил същия избор; ако реалният пример му противоречи, коригирай профила.\n\nКритерий за приемане: Съобрази формат и звук с мястото, където човекът вероятно гледа.\n\nКогато пробата се провали:\nСимптом: „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение.\nКорекция: Опиши един водещ сегмент и отдели вторичните.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Определи за кого е видеото и кога ще го гледа“?","options":[{"id":"a","label":"„Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение."},{"id":"b","label":"Описвай аудиторията през ситуацията и задачата ѝ."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Описвай аудиторията през ситуацията и задачата ѝ. Възраст, професия и град могат да помогнат за контекст, но сами не казват какъв въпрос има човекът, какво го спира и кога видеото ще му е удобно. Слабият ход е: „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение. Възрастта не доказва навик за гледане и бързината може да направи процеса по-труден за разбиране. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За курса по керамика „начинаещи на 20–35 години“ е твърде общо. Полезният профил е: човек, който иска да дойде на първо занимание с приятел, не е работил с глина и проверява програмата от телефона вечер. Иска да разбере дали материалите са включени и дали ще си тръгне с готов предмет. Това определя кои кадри и отговори са нужни.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"„Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Опиши един водещ сегмент и отдели вторичните."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Опиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи. Грешният път — „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение. — оставя риска нерешен. Провери и границата: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Определи за кого е видеото и кога ще го гледа“?","options":[{"id":"a","label":"„Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не използвай измислена „персона“ като заместител на интервю."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Описвай аудиторията през ситуацията и задачата ѝ. Възраст, професия и град могат да помогнат за контекст, но сами не казват какъв въпрос има човекът, какво го спира и кога видеото ще му е удобно.","Първо: Избери конкретен момент, в който зрителят среща проблема. После: Назови неговата задача с глагол: избере, сравни, разбере, провери или направи.","Следи за грешния ход: „Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.","items":[{"id":"s1","text":"Избери конкретен момент, в който зрителят среща проблема."},{"id":"s3","text":"Отбележи предишния опит, главната пречка и какво би било достатъчно полезно."},{"id":"s4","text":"Съобрази формат и звук с мястото, където човекът вероятно гледа."},{"id":"s2","text":"Назови неговата задача с глагол: избере, сравни, разбере, провери или направи."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Опиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи. Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За курса по керамика „начинаещи на 20–35 години“ е твърде общо.\n\nПроменено условие: Не използвай измислена „персона“ като заместител на интервю.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Опиши един водещ сегмент и отдели вторичните."},{"id":"a","label":"„Говори на всички млади хора и използвай бърз монтаж, защото те не задържат внимание.“ Това е стереотип, а не наблюдение."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Опиши един водещ сегмент и отдели вторичните. Покажи в първите секунди входа, масата и ръцете на човек без опит; добави надпис за включените материали, ако данните са потвърдени. Ако звукът може да е изключен, смисълът трябва да се следи и с четими надписи. Границата тук е: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.\n\nКарта за работа — Определи за кого е видеото и кога ще го гледа\n1. Избери конкретен момент, в който зрителят среща проблема.\n2. Назови неговата задача с глагол: избере, сравни, разбере, провери или направи.\n3. Отбележи предишния опит, главната пречка и какво би било достатъчно полезно.\n4. Съобрази формат и звук с мястото, където човекът вероятно гледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-03","title":"Проучи как хората решават проблема си сега","objective":"да събереш наблюдения от реални ситуации, преди да избираш тема и послание","hook":"Ако изследваш само собствените си идеи, рискуваш да решиш проблем, който хората нямат.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да събереш наблюдения от реални ситуации, преди да избираш тема и послание. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако изследваш само собствените си идеи, рискуваш да решиш проблем, който хората нямат.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Събирай сигнали от това, което хората правят, търсят и питат, преди да решиш какво трябва да каже видеото. Един лайк показва реакция, но не непременно нужда, намерение за покупка или разбиране.\n\nМини-протокол: пази точните думи или действието, датата и канала. Не повишавай увереността на извода, ако новите сигнали не го потвърждават."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Подреждай доказателствата по близост до реалното поведение: наблюдавано действие и скорошен конкретен случай обикновено са по-полезни от общо обещание „бих купил“. Сравни разговори, повтарящи се въпроси, търсения и собствени данни. Записвай дата, източник и контекст; не брои копирани коментари като независими сигнали.\n\nГраница на правилото: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Събери реални въпроси от поне два различни източника.\n2. Запиши точните думи и датата; махни имена и лични детайли.\n3. Групирай повтарящите се затруднения, без да добавяш мотив, който не си чул.\n4. Отдели доказаното, вероятното и неизвестното; избери тема само след това.\n\nСтоп-сигнал: Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията. Или смесваш 18 гледания със 18 души, въпреки че платформата отчита повторни гледания и различни формати по свой начин. Ако това се случи, приложи корекцията преди да продължиш: Направи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За ателието идват 18 въпроса за следващата група: 7 питат дали материалите са включени, 5 — дали курсът е подходящ без опит, 3 — кога се изпраща готовият предмет, а останалите са различни. Това не доказва как мислят всички потенциални клиенти, но подсказва коя неяснота се повтаря в наличните запитвания. Кадър от процеса и потвърдена информация за материалите могат да отговорят директно.\n\nРешение в този случай:\nНаправи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея.\n\nГраница на извода:\nМалката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията. Или смесваш 18 гледания със 18 души, въпреки че платформата отчита повторни гледания и различни формати по свой начин."},"after":{"label":"По-доброто решение","text":"Направи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея.\n\nПреди да продължиш: Отдели доказаното, вероятното и неизвестното; избери тема само след това."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Подреждай сигналите по близост до действие: реално поведение, скорошен конкретен случай, повтарящ се въпрос, собствен показател, после общо мнение. Премахни дублираните коментари и отбележи къде са събрани. Изводът „в тази извадка най-често питат за…“ е защитим; „всички искат…“ не е, освен ако данните действително го показват.\n\nКритерий за приемане: Отдели доказаното, вероятното и неизвестното; избери тема само след това.\n\nКогато пробата се провали:\nСимптом: Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията.\nКорекция: Направи проста таблица със сигнал, източник, дата, брой и увереност.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Проучи как хората решават проблема си сега“?","options":[{"id":"a","label":"Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Събирай сигнали от това, което хората правят, търсят и питат, преди да решиш какво трябва да каже видеото."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Събирай сигнали от това, което хората правят, търсят и питат, преди да решиш какво трябва да каже видеото. Един лайк показва реакция, но не непременно нужда, намерение за покупка или разбиране. Слабият ход е: Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията. Или смесваш 18 гледания със 18 души, въпреки че платформата отчита повторни гледания и различни формати по свой начин. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За ателието идват 18 въпроса за следващата група: 7 питат дали материалите са включени, 5 — дали курсът е подходящ без опит, 3 — кога се изпраща готовият предмет, а останалите са различни. Това не доказва как мислят всички потенциални клиенти, но подсказва коя неяснота се повтаря в наличните запитвания. Кадър от процеса и потвърдена информация за материалите могат да отговорят директно.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията."},{"id":"b","label":"Направи проста таблица със сигнал, източник, дата, брой и увереност."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея. Грешният път — Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията. — оставя риска нерешен. Провери и границата: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Проучи как хората решават проблема си сега“?","options":[{"id":"a","label":"Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията."},{"id":"b","label":"Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Събирай сигнали от това, което хората правят, търсят и питат, преди да решиш какво трябва да каже видеото. Един лайк показва реакция, но не непременно нужда, намерение за покупка или разбиране.","Първо: Събери реални въпроси от поне два различни източника. После: Запиши точните думи и датата; махни имена и лични детайли.","Следи за грешния ход: Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.","items":[{"id":"s2","text":"Запиши точните думи и датата; махни имена и лични детайли."},{"id":"s1","text":"Събери реални въпроси от поне два различни източника."},{"id":"s4","text":"Отдели доказаното, вероятното и неизвестното; избери тема само след това."},{"id":"s3","text":"Групирай повтарящите се затруднения, без да добавяш мотив, който не си чул."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея. Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За ателието идват 18 въпроса за следващата група: 7 питат дали материалите са включени, 5 — дали курсът е подходящ без опит, 3 — кога се изпраща готовият предмет, а останалите са различни.\n\nПроменено условие: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Избираш тема от най-гласовития коментар и заключаваш, че това е проблемът на аудиторията."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Направи проста таблица със сигнал, източник, дата, брой и увереност."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи проста таблица със сигнал, източник, дата, брой и увереност. Сравни поне два източника и формулирай извод като „в тази извадка най-често се пита за…“, а не „всички искат…“. Следващият разговор трябва да проверява неяснотата, а не да продава готовата идея. Границата тук е: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.\n\nКогато два сигнала си противоречат, провери дали са от еднакъв период, канал и етап на решение. Запази и двете наблюдения; не избирай само това, което подкрепя първоначалната идея.\n\nКарта за работа — Проучи как хората решават проблема си сега\n1. Събери реални въпроси от поне два различни източника.\n2. Запиши точните думи и датата; махни имена и лични детайли.\n3. Групирай повтарящите се затруднения, без да добавяш мотив, който не си чул.\n4. Отдели доказаното, вероятното и неизвестното; избери тема само след това.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-04","title":"Задавай въпроси, които не подсказват отговора","objective":"да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение","hook":"„Това полезно ли би ти било?“ почти винаги води до учтиво, но безполезно „да“.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Това полезно ли би ти било?“ почти винаги води до учтиво, но безполезно „да“.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Питай за последното реално поведение, а не за одобрение на бъдеща идея. Неутралният разговор помага на човека да си спомни стъпките, а на теб — да видиш къде точно се появява затруднението."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Полезният въпрос е кратък, отворен и за един конкретен случай: „Разкажи ми за последния път…“. После изчакай и попитай „Какво стана след това?“ или „Какво беше най-трудно?“. Избягвай въпрос с готов отговор, двойно питане и защита на своята концепция. Мълчанието често дава по-точни данни от подсказването.\n\nГраница на правилото: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта;… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Започни с контекст и попитай най-скорошния случай.\n2. Нека човекът опише действията си; не прекъсвай, за да обясняваш продукта.\n3. Задай едно уточнение за момента на колебание или решение.\n4. Провери разбирането с неутрално обобщение и отбележи точните думи.\n\nСтоп-сигнал: „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя част е важна. Ако това се случи, приложи корекцията преди да продължиш: Използвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Вместо „Ще ти е по-лесно, ако във видеото покажем готовата чаша, нали?“ попитай посетител на курса: „Спомняш ли си как избра първото занимание, на което се записа? Какво провери преди да решиш?“ Ако каже „дали ще се справя“, попитай какво го накара да мисли така. Не предлагай успокоение до края на разговора.\n\nРешение в този случай:\nИзползвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник.\n\nГраница на извода:\nРазговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя част е важна."},"after":{"label":"По-доброто решение","text":"Използвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник.\n\nПреди да продължиш: Провери разбирането с неутрално обобщение и отбележи точните думи."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Започни с „Разкажи ми за последния път, когато…“. После попитай какво стана преди, какво направи човекът и как разбра, че е успял. Не предлагай отговори от типа „Страхуваше ли се от цената?“. Записвай дословно, отдели наблюдаваното от твоето тълкуване и не записвай чувствителна информация без нужда и съгласие.\n\nКритерий за приемане: Провери разбирането с неутрално обобщение и отбележи точните думи.\n\nКогато пробата се провали:\nСимптом: „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя част е важна.\nКорекция: Използвай последния завършен случай, не „какво би направил“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Задавай въпроси, които не подсказват отговора“?","options":[{"id":"a","label":"„Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя…"},{"id":"b","label":"Питай за последното реално поведение, а не за одобрение на бъдеща идея."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Питай за последното реално поведение, а не за одобрение на бъдеща идея. Неутралният разговор помага на човека да си спомни стъпките, а на теб — да видиш къде точно се появява затруднението. Слабият ход е: „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя част е важна. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Вместо „Ще ти е по-лесно, ако във видеото покажем готовата чаша, нали?“ попитай посетител на курса: „Спомняш ли си как избра първото занимание, на което се записа? Какво провери преди да решиш?“ Ако каже „дали ще се справя“, попитай какво го накара да мисли така. Не предлагай успокоение до края на разговора.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използвай последния завършен случай, не „какво би направил“."},{"id":"b","label":"„Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя…"},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник. Грешният път — „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да… — оставя риска нерешен. Провери и границата: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Задавай въпроси, които не подсказват отговора“?","options":[{"id":"a","label":"Разговорите са качествен сигнал, не анкета с представителна извадка."},{"id":"b","label":"„Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя…"},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Питай за последното реално поведение, а не за одобрение на бъдеща идея. Неутралният разговор помага на човека да си спомни стъпките, а на теб — да видиш къде точно се появява затруднението.","Първо: Започни с контекст и попитай най-скорошния случай. После: Нека човекът опише действията си; не прекъсвай, за да обясняваш продукта.","Следи за грешния ход: „Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да…"],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.","items":[{"id":"s3","text":"Задай едно уточнение за момента на колебание или решение."},{"id":"s2","text":"Нека човекът опише действията си; не прекъсвай, за да обясняваш продукта."},{"id":"s1","text":"Започни с контекст и попитай най-скорошния случай."},{"id":"s4","text":"Провери разбирането с неутрално обобщение и отбележи точните думи."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник. Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Вместо „Ще ти е по-лесно, ако във видеото покажем готовата чаша, нали?“ попитай посетител на курса: „Спомняш ли си как избра първото занимание, на което се записа?\n\nПроменено условие: Разговорите са качествен сигнал, не анкета с представителна извадка.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използвай последния завършен случай, не „какво би направил“."},{"id":"b","label":"„Харесваш ли нашата идея за видео с майсторски кадри и специална оферта?“ Въпросът иска учтиво одобрение и смесва образ, цена и оферта; няма да разбереш коя част е важна."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай последния завършен случай, не „какво би направил“. Записвай думите без редакция, отделяй наблюдението от интерпретацията и проверявай едно твърдение с друг човек или друг източник. Границата тук е: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.\n\nКарта за работа — Задавай въпроси, които не подсказват отговора\n1. Започни с контекст и попитай най-скорошния случай.\n2. Нека човекът опише действията си; не прекъсвай, за да обясняваш продукта.\n3. Задай едно уточнение за момента на колебание или решение.\n4. Провери разбирането с неутрално обобщение и отбележи точните думи.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-05","title":"Раздели тема, проблем и полезен извод","objective":"да превърнеш широка тема в конкретен проблем и извод за зрителя","hook":"„Фитнес“, „маркетинг“ и „видео“ са категории, не още идеи за конкретен епизод.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш широка тема в конкретен проблем и извод за зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Фитнес“, „маркетинг“ и „видео“ са категории, не още идеи за конкретен епизод.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Разделяй темата, конкретния проблем и полезния извод. Темата назовава област; проблемът описва момент, в който нещо не работи; изводът показва какво трябва да разбере зрителят, за да продължи."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Полезната формулировка свързва ситуация и причина, но не представя причината като факт без доказателства. „Осветление“ е тема. „Лицето става тъмно, когато снимаш срещу прозорец“ е наблюдаван проблем. „Премести човека към прозореца и заключи експозицията“ е решение, което може да се демонстрира и провери.\n\nГраница на правилото: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши темата с едно съществително.\n2. Добави ситуация и наблюдавано затруднение с глагол.\n3. Посочи какво знаеш и кое е само предполагаема причина.\n4. Формулирай един извод, който можеш да покажеш, а не само да заявиш.\n\nСтоп-сигнал: „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно. Ако това се случи, приложи корекцията преди да продължиш: Пиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Тема: керамика. Проблем: новият участник не знае колко силно да натисне глината и се страхува, че ще я повреди. Извод: за първата форма е достатъчно равномерно притискане с длан; инструкторът показва натиска и коригира ръката. Това дава сцена — близък план на дланта, после резултата — вместо обща реклама на ателието.\n\nРешение в този случай:\nПиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода.\n\nГраница на извода:\nНе прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."},"after":{"label":"По-доброто решение","text":"Пиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода.\n\nПреди да продължиш: Формулирай един извод, който можеш да покажеш, а не само да заявиш."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Ползвай три реда в работния бриф: тема — областта; проблем — конкретният момент, в който нещо спира; извод — какво трябва да разбере човекът. Ако изводът може да се приложи към всяка аудитория и всеки бизнес, стесни го. Ако липсва наблюдение, запиши го като хипотеза, не като готова истина за сценария.\n\nКритерий за приемане: Формулирай един извод, който можеш да покажеш, а не само да заявиш.\n\nКогато пробата се провали:\nСимптом: „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно.\nКорекция: Пиши проблема като действие или въпрос, който можеш да наблюдаваш.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Раздели тема, проблем и полезен извод“?","options":[{"id":"a","label":"„Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Разделяй темата, конкретния проблем и полезния извод."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Разделяй темата, конкретния проблем и полезния извод. Темата назовава област; проблемът описва момент, в който нещо не работи; изводът показва какво трябва да разбере зрителят, за да продължи. Слабият ход е: „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Тема: керамика. Проблем: новият участник не знае колко силно да натисне глината и се страхува, че ще я повреди. Извод: за първата форма е достатъчно равномерно притискане с длан; инструкторът показва натиска и коригира ръката. Това дава сцена — близък план на дланта, после резултата — вместо обща реклама на ателието.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"„Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Пиши проблема като действие или въпрос, който можеш да наблюдаваш."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Пиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода. Грешният път — „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно. — оставя риска нерешен. Провери и границата: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Раздели тема, проблем и полезен извод“?","options":[{"id":"a","label":"„Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не прескачай от една история към универсален съвет."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Разделяй темата, конкретния проблем и полезния извод. Темата назовава област; проблемът описва момент, в който нещо не работи; изводът показва какво трябва да разбере зрителят, за да продължи.","Първо: Запиши темата с едно съществително. После: Добави ситуация и наблюдавано затруднение с глагол.","Следи за грешния ход: „Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.","items":[{"id":"s3","text":"Посочи какво знаеш и кое е само предполагаема причина."},{"id":"s4","text":"Формулирай един извод, който можеш да покажеш, а не само да заявиш."},{"id":"s2","text":"Добави ситуация и наблюдавано затруднение с глагол."},{"id":"s1","text":"Запиши темата с едно съществително."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Пиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода. Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Тема: керамика.\n\nПроменено условие: Не прескачай от една история към универсален съвет.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Пиши проблема като действие или въпрос, който можеш да наблюдаваш."},{"id":"a","label":"„Хората нямат креативност, затова не се записват.“ Това приписва вътрешна причина без доказателство и не сочи какво може да направи видеото полезно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Пиши проблема като действие или въпрос, който можеш да наблюдаваш. След това провери дали един демонстриран извод отговаря на него и дали има експерт, който да потвърди метода. Границата тук е: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.\n\nКарта за работа — Раздели тема, проблем и полезен извод\n1. Запиши темата с едно съществително.\n2. Добави ситуация и наблюдавано затруднение с глагол.\n3. Посочи какво знаеш и кое е само предполагаема причина.\n4. Формулирай един извод, който можеш да покажеш, а не само да заявиш.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-06","title":"Постави цел за зрителя, не за суетна метрика","objective":"да избереш едно желано действие или разбиране и показател, който го приближава","hook":"Гледанията сами по себе си не показват дали видеото е било полезно или е довело до правилното действие.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш едно желано действие или разбиране и показател, който го приближава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Гледанията сами по себе си не показват дали видеото е било полезно или е довело до правилното действие.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Поставяй цел за промяна при зрителя и избирай показател, който действително я отразява. Гледанията описват достигане, а не автоматично разбиране, доверие или записване."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Свържи показател с етапа: показвания → започнати гледания → задържане до демонстрацията → посещение на графика → записване. Задай знаменател и период, иначе процентите не сравними. Една основна метрика дава посока; диагностичните метрики помагат да разбереш къде губиш хора, но не доказват сами причината.\n\nГраница на правилото: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови едно действие или разбиране, което видеото цели да промени.\n2. Избери най-близкия наблюдаем показател и дефинирай знаменателя.\n3. Запиши изходния период и източника на данните.\n4. Преди публикация реши какъв сигнал ще наложи нова версия.\n\nСтоп-сигнал: Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване. Това може да насърчи развлекателен кадър, който няма връзка с услугата. Ако това се случи, приложи корекцията преди да продължиш: Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Ателието иска запълнена съботна група. „Повече гледания“ не показва дали хората разбраха, че материалите са включени. Проследи завършените посещения към страницата с графика и записванията, като отделиш източника на трафика. Ако видеото задържа зрители, но графикът остава празен, провери следващата стъпка и наличността, преди да сменяш началния кадър.\n\nРешение в този случай:\nЗапиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия.\n\nГраница на извода:\nПри малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване. Това може да насърчи развлекателен кадър, който няма връзка с услугата."},"after":{"label":"По-доброто решение","text":"Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия.\n\nПреди да продължиш: Преди публикация реши какъв сигнал ще наложи нова версия."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Раздели показателите на достигане, внимание, разбиране и действие. Гледанията отговарят на въпроса колко пъти е започнал клипът; не доказват, че човекът е разбрал предложението. Избери един основен показател, свързан с целта, и един предпазен показател, за да не подобриш едното за сметка на подвеждащото съдържание.\n\nКритерий за приемане: Преди публикация реши какъв сигнал ще наложи нова версия.\n\nКогато пробата се провали:\nСимптом: Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване.\nКорекция: Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Постави цел за зрителя, не за суетна метрика“?","options":[{"id":"a","label":"Поставяй цел за промяна при зрителя и избирай показател, който действително я отразява."},{"id":"b","label":"Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Поставяй цел за промяна при зрителя и избирай показател, който действително я отразява. Гледанията описват достигане, а не автоматично разбиране, доверие или записване. Слабият ход е: Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване. Това може да насърчи развлекателен кадър, който няма връзка с услугата. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Ателието иска запълнена съботна група. „Повече гледания“ не показва дали хората разбраха, че материалите са включени. Проследи завършените посещения към страницата с графика и записванията, като отделиш източника на трафика. Ако видеото задържа зрители, но графикът остава празен, провери следващата стъпка и наличността, преди да сменяш началния кадър.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване."},{"id":"b","label":"Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия. Грешният път — Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване. — оставя риска нерешен. Провери и границата: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Постави цел за зрителя, не за суетна метрика“?","options":[{"id":"a","label":"Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване."},{"id":"b","label":"При малък обем една-две конверсии променят процента рязко."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Поставяй цел за промяна при зрителя и избирай показател, който действително я отразява. Гледанията описват достигане, а не автоматично разбиране, доверие или записване.","Първо: Назови едно действие или разбиране, което видеото цели да промени. После: Избери най-близкия наблюдаем показател и дефинирай знаменателя.","Следи за грешния ход: Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.","items":[{"id":"s1","text":"Назови едно действие или разбиране, което видеото цели да промени."},{"id":"s4","text":"Преди публикация реши какъв сигнал ще наложи нова версия."},{"id":"s3","text":"Запиши изходния период и източника на данните."},{"id":"s2","text":"Избери най-близкия наблюдаем показател и дефинирай знаменателя."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия. При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Ателието иска запълнена съботна група.\n\nПроменено условие: При малък обем една-две конверсии променят процента рязко.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Избираш харесвания като единствен успех за видео, чиято задача е да доведе до записване."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Запиши метриката като формула и източник, например „записвания от линка / посещения на страницата за курса за 14 дни“. Гледай първо дали сигналът е надежден, после сравнявай периоди със сходни условия. Границата тук е: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.\n\nКарта за работа — Постави цел за зрителя, не за суетна метрика\n1. Назови едно действие или разбиране, което видеото цели да промени.\n2. Избери най-близкия наблюдаем показател и дефинирай знаменателя.\n3. Запиши изходния период и източника на данните.\n4. Преди публикация реши какъв сигнал ще наложи нова версия.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-07","title":"Свържи целта с едно следващо действие","objective":"да избираш действие, което съответства на готовността и нуждата на зрителя","hook":"Не всяко видео трябва да продава; не всяко „последвай ме“ е полезна следваща стъпка.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш действие, което съответства на готовността и нуждата на зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Не всяко видео трябва да продава; не всяко „последвай ме“ е полезна следваща стъпка.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Дай зрителя една следваща стъпка, съобразена с това колко вече знае и колко е готов да реши. Призивът трябва да продължава ползата на видеото, а не да прекъсва с несвързана продажба."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Първо определи намерението: научи, сравни, провери условията или запиши час. По-малката стъпка е подходяща, когато има нерешен въпрос; директната регистрация е уместна, ако цената, датата, включеното и условията са ясни. Един клип с пет равностойни бутона размива посоката.\n\nГраница на правилото: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи на кой етап е зрителят след видеото.\n2. Избери едно действие, което отговаря на липсващата му информация.\n3. Напиши точен призив и посочи къде се изпълнява.\n4. Провери, че връзката, датата и наличността са актуални.\n\nСтоп-сигнал: В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“. Зрителят не разбира кое е важно, а призив за действие се превръща в списък с желания на автора. Ако това се случи, приложи корекцията преди да продължиш: Използвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Видеото показва първите три стъпки на грънчарското колело. Новият зрител още не знае кога има свободно място и какво включва цената. Призив „Виж програмата и свободните дати“ е по-полезен от „Купи сега“, ако страницата ясно отговаря на тези въпроси.\n\nРешение в този случай:\nИзползвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш.\n\nГраница на извода:\nНе казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“. Зрителят не разбира кое е важно, а призив за действие се превръща в списък с желания на автора."},"after":{"label":"По-доброто решение","text":"Използвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш.\n\nПреди да продължиш: Провери, че връзката, датата и наличността са актуални."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Свържи призива с конкретната следваща стъпка в пътя на зрителя: отвори графика, сравни вариантите или запази указанията. Провери къде води връзката и дали човекът вижда точно обещаната информация. Ако страницата иска неочаквана регистрация или показва друга оферта, проблемът не е в силата на призива, а в прекъснатия път.\n\nКритерий за приемане: Провери, че връзката, датата и наличността са актуални.\n\nКогато пробата се провали:\nСимптом: В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“.\nКорекция: Използвай глагол и конкретен обект: „Виж датите за начинаещи“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Свържи целта с едно следващо действие“?","options":[{"id":"a","label":"В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“."},{"id":"b","label":"Дай зрителя една следваща стъпка, съобразена с това колко вече знае и колко е готов да реши."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Дай зрителя една следваща стъпка, съобразена с това колко вече знае и колко е готов да реши. Призивът трябва да продължава ползата на видеото, а не да прекъсва с несвързана продажба. Слабият ход е: В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“. Зрителят не разбира кое е важно, а призив за действие се превръща в списък с желания на автора. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Видеото показва първите три стъпки на грънчарското колело. Новият зрител още не знае кога има свободно място и какво включва цената. Призив „Виж програмата и свободните дати“ е по-полезен от „Купи сега“, ако страницата ясно отговаря на тези въпроси.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използвай глагол и конкретен обект: „Виж датите за начинаещи“."},{"id":"b","label":"В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш. Грешният път — В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“. — оставя риска нерешен. Провери и границата: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Свържи целта с едно следващо действие“?","options":[{"id":"a","label":"Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено."},{"id":"b","label":"В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Дай зрителя една следваща стъпка, съобразена с това колко вече знае и колко е готов да реши. Призивът трябва да продължава ползата на видеото, а не да прекъсва с несвързана продажба.","Първо: Определи на кой етап е зрителят след видеото. После: Избери едно действие, което отговаря на липсващата му информация.","Следи за грешния ход: В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.","items":[{"id":"s2","text":"Избери едно действие, което отговаря на липсващата му информация."},{"id":"s4","text":"Провери, че връзката, датата и наличността са актуални."},{"id":"s1","text":"Определи на кой етап е зрителят след видеото."},{"id":"s3","text":"Напиши точен призив и посочи къде се изпълнява."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш. Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Видеото показва първите три стъпки на грънчарското колело.\n\nПроменено условие: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използвай глагол и конкретен обект: „Виж датите за начинаещи“."},{"id":"b","label":"В края добавяш „харесай, коментирай, сподели, последвай, купи и запази“."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай глагол и конкретен обект: „Виж датите за начинаещи“. Постави го близо до момента, когато нужната информация вече е показана, и измервай клика или завършеното действие, което обещаваш. Границата тук е: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.\n\nКарта за работа — Свържи целта с едно следващо действие\n1. Определи на кой етап е зрителят след видеото.\n2. Избери едно действие, което отговаря на липсващата му информация.\n3. Напиши точен призив и посочи къде се изпълнява.\n4. Провери, че връзката, датата и наличността са актуални.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-08","title":"Формулирай обещание, което можеш да изпълниш","objective":"да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш","hook":"Силно обещание привлича внимание само ако самото видео го изпълнява.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Силно обещание привлича внимание само ако самото видео го изпълнява.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Формулирай ползата така, че видеото да може да я изпълни в показаното време и с наличните доказателства. Добрата заявка обещава полезен резултат; не гарантира чуждо поведение или бизнес резултат."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Провери обхвата на обещанието: кой е зрителят, какво ще разбере или направи, при какви условия и за колко време. „Ще се научиш да снимаш професионално“ е прекалено широко за 30 секунди. „Ще видиш как да заключиш баланса на бялото преди втори дубъл“ е тясно и демонстрируемо.\n\nГраница на правилото: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Напиши обещанието с конкретен глагол и резултат.\n2. Сравни всяка част с кадър, тест, източник или реална демонстрация.\n3. Отбележи условията и изключенията, които променят резултата.\n4. Премахни гаранции за приходи, популярност и чужд избор.\n\nСтоп-сигнал: „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира. Ако това се случи, приложи корекцията преди да продължиш: Свържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"„Започни с грънчарско колело още днес без никаква подготовка“ звучи лесно, но може да пропусне възрастово ограничение, резервация или дрехи за работа. По-точно: „В 45 секунди ще видиш как започва първият урок и какво предоставя ателието“ — ако кадрите и потвърдените условия го показват.\n\nРешение в този случай:\nСвържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно.\n\nГраница на извода:\nРекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."},"after":{"label":"По-доброто решение","text":"Свържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно.\n\nПреди да продължиш: Премахни гаранции за приходи, популярност и чужд избор."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Преди одобрение маркирай обещанията като контролируеми и неконтролируеми. Можеш да обещаеш какво ще покаже урокът; не можеш да гарантираш, че всеки ще постигне еднакъв резултат или ще купи. Добави необходимото условие до твърдението, а не в дребен текст след призива. Премахни цифра, за която няма проследим източник.\n\nКритерий за приемане: Премахни гаранции за приходи, популярност и чужд избор.\n\nКогато пробата се провали:\nСимптом: „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира.\nКорекция: Свържи всяко обещание с доказателство в монтажния план.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Формулирай обещание, което можеш да изпълниш“?","options":[{"id":"a","label":"„Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."},{"id":"b","label":"Формулирай ползата така, че видеото да може да я изпълни в показаното време и с наличните доказателства."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Формулирай ползата така, че видеото да може да я изпълни в показаното време и с наличните доказателства. Добрата заявка обещава полезен резултат; не гарантира чуждо поведение или бизнес резултат. Слабият ход е: „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: „Започни с грънчарско колело още днес без никаква подготовка“ звучи лесно, но може да пропусне възрастово ограничение, резервация или дрехи за работа. По-точно: „В 45 секунди ще видиш как започва първият урок и какво предоставя ателието“ — ако кадрите и потвърдените условия го показват.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"„Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Свържи всяко обещание с доказателство в монтажния план."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Свържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно. Грешният път — „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира. — оставя риска нерешен. Провери и границата: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Формулирай обещание, което можеш да изпълниш“?","options":[{"id":"a","label":"„Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Формулирай ползата така, че видеото да може да я изпълни в показаното време и с наличните доказателства. Добрата заявка обещава полезен резултат; не гарантира чуждо поведение или бизнес резултат.","Първо: Напиши обещанието с конкретен глагол и резултат. После: Сравни всяка част с кадър, тест, източник или реална демонстрация.","Следи за грешния ход: „Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.","items":[{"id":"s1","text":"Напиши обещанието с конкретен глагол и резултат."},{"id":"s3","text":"Отбележи условията и изключенията, които променят резултата."},{"id":"s2","text":"Сравни всяка част с кадър, тест, източник или реална демонстрация."},{"id":"s4","text":"Премахни гаранции за приходи, популярност и чужд избор."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Свържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно. Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: „Започни с грънчарско колело още днес без никаква подготовка“ звучи лесно, но може да пропусне възрастово ограничение, резервация или дрехи за работа.\n\nПроменено условие: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Свържи всяко обещание с доказателство в монтажния план."},{"id":"a","label":"„Всеки ще направи красива чаша за два часа.“ Резултатът зависи от навика, формата и сушенето; обещанието поставя очакване, което екипът не контролира."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Свържи всяко обещание с доказателство в монтажния план. Ако има условие, кажи го на екрана или в описанието. Ако доказателство липсва, стесни формулировката, вместо да добавяш уверено прилагателно. Границата тук е: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.\n\nКарта за работа — Формулирай обещание, което можеш да изпълниш\n1. Напиши обещанието с конкретен глагол и резултат.\n2. Сравни всяка част с кадър, тест, източник или реална демонстрация.\n3. Отбележи условията и изключенията, които променят резултата.\n4. Премахни гаранции за приходи, популярност и чужд избор.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-09","title":"Провери какво доказваш и с чие разрешение","objective":"да избираш доказателство, което е относимо, вярно и използвано с разрешение","hook":"Историята на клиент може да е силна, но не е твой материал без съгласие.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш доказателство, което е относимо, вярно и използвано с разрешение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Историята на клиент може да е силна, но не е твой материал без съгласие.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай доказателство, което е относимо към твърдението, вярно в контекст и показано с разрешение. Красив кадър не е автоматично доказателство за качество, а клиентски цитат не е валиден без точни думи и съгласие."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Направи мини-регистър за всяко силно твърдение: точен текст, първоизточник, дата, период, ограничения и кой го е одобрил. За резултат преди/след сравни сходни условия. За цитат запази контекст и смисъл. За чужда музика, снимка и лице провери правата и срока на използване.\n\nГраница на правилото: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Маркирай изреченията, които твърдят факт, резултат или сравнение.\n2. Прикачи първоизточник и провери дата, единици и ограничения.\n3. Получи разрешение за цитат, образ, музика и лични данни.\n4. Покажи доказателството до твърдението и пази контекста.\n\nСтоп-сигнал: Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно. Липсата на оплакване не е разрешение за публикация. Ако това се случи, приложи корекцията преди да продължиш: Свържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Керамистът твърди „всеки курсист изработва предмета си“. Проверка показва, че предметът трябва да съхне и да мине изпичане след курса; не се отнася вкъщи същия ден. Кадърът с готова чаша е от предишна група. Точният текст трябва да уточни кога се получава изделието, а участниците в кадъра да са дали съгласие.\n\nРешение в този случай:\nСвържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички.\n\nГраница на извода:\nНе показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно. Липсата на оплакване не е разрешение за публикация."},"after":{"label":"По-доброто решение","text":"Свържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички.\n\nПреди да продължиш: Покажи доказателството до твърдението и пази контекста."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Направи таблица с твърдение, доказателство, срок на валидност, разрешение и одобряващ. Цитатът трябва да остане точен; монтажът не бива да променя смисъла му. Снимка на клиент, екран с лични данни или чужда музика не стават свободни за реклама само защото са били публикувани в мрежа.\n\nКритерий за приемане: Покажи доказателството до твърдението и пази контекста.\n\nКогато пробата се провали:\nСимптом: Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно.\nКорекция: Свържи всяко твърдение с кадър/документ/източник и запази разрешението.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Провери какво доказваш и с чие разрешение“?","options":[{"id":"a","label":"Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Използвай доказателство, което е относимо към твърдението, вярно в контекст и показано с разрешение."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Използвай доказателство, което е относимо към твърдението, вярно в контекст и показано с разрешение. Красив кадър не е автоматично доказателство за качество, а клиентски цитат не е валиден без точни думи и съгласие. Слабият ход е: Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно. Липсата на оплакване не е разрешение за публикация. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Керамистът твърди „всеки курсист изработва предмета си“. Проверка показва, че предметът трябва да съхне и да мине изпичане след курса; не се отнася вкъщи същия ден. Кадърът с готова чаша е от предишна група. Точният текст трябва да уточни кога се получава изделието, а участниците в кадъра да са дали съгласие.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно."},{"id":"b","label":"Свържи всяко твърдение с кадър/документ/източник и запази разрешението."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Свържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички. Грешният път — Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно. — оставя риска нерешен. Провери и границата: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Провери какво доказваш и с чие разрешение“?","options":[{"id":"a","label":"Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно."},{"id":"b","label":"Не показвай екрани с имена, телефони, адреси и лични съобщения."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай доказателство, което е относимо към твърдението, вярно в контекст и показано с разрешение. Красив кадър не е автоматично доказателство за качество, а клиентски цитат не е валиден без точни думи и съгласие.","Първо: Маркирай изреченията, които твърдят факт, резултат или сравнение. После: Прикачи първоизточник и провери дата, единици и ограничения.","Следи за грешния ход: Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.","items":[{"id":"s2","text":"Прикачи първоизточник и провери дата, единици и ограничения."},{"id":"s4","text":"Покажи доказателството до твърдението и пази контекста."},{"id":"s3","text":"Получи разрешение за цитат, образ, музика и лични данни."},{"id":"s1","text":"Маркирай изреченията, които твърдят факт, резултат или сравнение."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Свържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички. Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Керамистът твърди „всеки курсист изработва предмета си“.\n\nПроменено условие: Не показвай екрани с имена, телефони, адреси и лични съобщения.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използваш снимка от Instagram като „отзив“ или изрязваш половин изречение така, че обещанието изглежда по-силно."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Свържи всяко твърдение с кадър/документ/източник и запази разрешението."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Свържи всяко твърдение с кадър/документ/източник и запази разрешението. Ако доказателството показва само един пример, говори за този пример, а не за резултат на всички. Границата тук е: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.\n\nКарта за работа — Провери какво доказваш и с чие разрешение\n1. Маркирай изреченията, които твърдят факт, резултат или сравнение.\n2. Прикачи първоизточник и провери дата, единици и ограничения.\n3. Получи разрешение за цитат, образ, музика и лични данни.\n4. Покажи доказателството до твърдението и пази контекста.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-10","title":"Изгради теми, към които можеш да се връщаш","objective":"да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза","hook":"Календарът се изпразва, когато всяка публикация трябва да бъде напълно нова идея.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Календарът се изпразва, когато всяка публикация трябва да бъде напълно нова идея.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Изгради няколко устойчиви тематични линии от повтарящите се въпроси, доказуемата ти експертиза и съдържание, което можеш редовно да произведеш."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Тема става стълб, когато можеш да я разгърнеш в различни формати: обяснение, демонстрация, грешка, сравнение, история и отговор на възражение. Не прави каталог от услуги с ново заглавие във всеки клип. Тематичната карта трябва да помага на зрителя да продължи, а на екипа — да планира без да измисля повод от нулата.\n\nГраница на правилото: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Събери повтарящите се проблеми от разговори и обслужване.\n2. Свържи всеки проблем с умение или доказателство, което имаш.\n3. Групирай в малък брой разбираеми линии и дай на всяка различна роля.\n4. Провери дали можеш да произведеш примери и кадри устойчиво.\n\nСтоп-сигнал: Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“. Това не изгражда полезна поредица и бързо изчерпва темите. Ако това се случи, приложи корекцията преди да продължиш: За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За „Ръце в глина“ възможни линии са: първо занимание, грижа за изделието, инструменти и процес, истории на курсисти. Всяка има отделен доказателствен източник; „истории на курсисти“ изисква съгласие, а „грижа“ изисква метод, потвърден от керамиста. Така календарът не разчита само на промоции.\n\nРешение в този случай:\nЗа всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията.\n\nГраница на извода:\nНе следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“. Това не изгражда полезна поредица и бързо изчерпва темите."},"after":{"label":"По-доброто решение","text":"За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията.\n\nПреди да продължиш: Провери дали можеш да произведеш примери и кадри устойчиво."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Тема за поредица трябва да издържа на повече от един клип. Провери дали има различни въпроси, примери и кадри, а не едно твърдение, преразказано пет пъти. Планирай капацитета: кой снима, кой проверява фактите и колко често може да се поддържа качеството. По-добре по-малка устойчива рубрика, отколкото график, който екипът не може да изпълни.\n\nКритерий за приемане: Провери дали можеш да произведеш примери и кадри устойчиво.\n\nКогато пробата се провали:\nСимптом: Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“.\nКорекция: За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Изгради теми, към които можеш да се връщаш“?","options":[{"id":"a","label":"Изгради няколко устойчиви тематични линии от повтарящите се въпроси, доказуемата ти експертиза и съдържание, което можеш редовно да произведеш."},{"id":"b","label":"Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Изгради няколко устойчиви тематични линии от повтарящите се въпроси, доказуемата ти експертиза и съдържание, което можеш редовно да произведеш. Слабият ход е: Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“. Това не изгражда полезна поредица и бързо изчерпва темите. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За „Ръце в глина“ възможни линии са: първо занимание, грижа за изделието, инструменти и процес, истории на курсисти. Всяка има отделен доказателствен източник; „истории на курсисти“ изисква съгласие, а „грижа“ изисква метод, потвърден от керамиста. Така календарът не разчита само на промоции.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора."},{"id":"b","label":"Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията. Грешният път — Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“. — оставя риска нерешен. Провери и границата: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Изгради теми, към които можеш да се връщаш“?","options":[{"id":"a","label":"Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили."},{"id":"b","label":"Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Изгради няколко устойчиви тематични линии от повтарящите се въпроси, доказуемата ти експертиза и съдържание, което можеш редовно да произведеш.","Първо: Събери повтарящите се проблеми от разговори и обслужване. После: Свържи всеки проблем с умение или доказателство, което имаш.","Следи за грешния ход: Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.","items":[{"id":"s2","text":"Свържи всеки проблем с умение или доказателство, което имаш."},{"id":"s3","text":"Групирай в малък брой разбираеми линии и дай на всяка различна роля."},{"id":"s4","text":"Провери дали можеш да произведеш примери и кадри устойчиво."},{"id":"s1","text":"Събери повтарящите се проблеми от разговори и обслужване."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията. Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За „Ръце в глина“ възможни линии са: първо занимание, грижа за изделието, инструменти и процес, истории на курсисти.\n\nПроменено условие: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора."},{"id":"b","label":"Обявяваш шест стълба, които са само шест услуги, и всяка публикация казва „запиши се“."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: За всяка линия запиши: чий проблем решава, какъв формат го показва, какъв ресурс трябва и коя следваща тема продължава разговора. Остави място за нови сигнали от аудиторията. Границата тук е: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.\n\nКарта за работа — Изгради теми, към които можеш да се връщаш\n1. Събери повтарящите се проблеми от разговори и обслужване.\n2. Свържи всеки проблем с умение или доказателство, което имаш.\n3. Групирай в малък брой разбираеми линии и дай на всяка различна роля.\n4. Провери дали можеш да произведеш примери и кадри устойчиво.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-11","title":"Генерирай идеи от въпросите, не от празен лист","objective":"да превръщаш реален въпрос в няколко различни, приложими видео идеи","hook":"Когато търсиш само „гениална идея“, пропускаш малките задачи, за които хората вече търсят помощ.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превръщаш реален въпрос в няколко различни, приложими видео идеи. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Когато търсиш само „гениална идея“, пропускаш малките задачи, за които хората вече търсят помощ.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Генерирай идеи от реални въпроси и ситуации. Една формулировка може да роди различни полезни видеа — демонстрация, обяснение, сравнение или кратък отговор — без да сменяш нуждата на зрителя."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Запазвай първо точния въпрос, после преформулирай като задача за видео. Използвай глагол и наблюдаем материал: „покажи“, „сравни“, „провери“. Оригиналността може да дойде от пример, гледна точка и доказателство, а не от измислен тренд. Изключи идеи, чиито факти, права или кадри не можеш да осигуриш.\n\nГраница на правилото: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши конкретния въпрос с думите на човека.\n2. Създай поне три форми: демонстрация, обяснение и сравнение.\n3. За всяка избери кадър или факт, който ще носи стойността.\n4. Провери дали идеята се побира в цел, време, права и наличен ресурс.\n\nСтоп-сигнал: Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него. Няма връзка с доказуем проблем и клипът трудно се продължава. Ако това се случи, приложи корекцията преди да продължиш: Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Въпрос: „Как ще знам, че глината е готова за следващата стъпка?“ Вариант 1 — близък план на допира и формата; вариант 2 — учителят показва две състояния; вариант 3 — грешка и поправка. Не избирай клип „10 тайни“, ако майсторът не може да потвърди тайните или да ги покаже.\n\nРешение в този случай:\nПоддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза.\n\nГраница на извода:\nИдея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него. Няма връзка с доказуем проблем и клипът трудно се продължава."},"after":{"label":"По-доброто решение","text":"Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза.\n\nПреди да продължиш: Провери дали идеята се побира в цел, време, права и наличен ресурс."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Преведи всеки реален въпрос в поне два възможни формата: демонстрация и кратко обяснение, сравнение и често задаван въпрос. Не сменяй нуждата на зрителя само за да повториш популярен формат. Запиши каква информация ще се види във всеки вариант и избери този, който можеш да докажеш с достъпните кадри.\n\nКритерий за приемане: Провери дали идеята се побира в цел, време, права и наличен ресурс.\n\nКогато пробата се провали:\nСимптом: Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него.\nКорекция: Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Генерирай идеи от въпросите, не от празен лист“?","options":[{"id":"a","label":"Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Генерирай идеи от реални въпроси и ситуации."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Генерирай идеи от реални въпроси и ситуации. Една формулировка може да роди различни полезни видеа — демонстрация, обяснение, сравнение или кратък отговор — без да сменяш нуждата на зрителя. Слабият ход е: Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него. Няма връзка с доказуем проблем и клипът трудно се продължава. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Въпрос: „Как ще знам, че глината е готова за следващата стъпка?“ Вариант 1 — близък план на допира и формата; вариант 2 — учителят показва две състояния; вариант 3 — грешка и поправка. Не избирай клип „10 тайни“, ако майсторът не може да потвърди тайните или да ги покаже.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него."},{"id":"b","label":"Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза. Грешният път — Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него. — оставя риска нерешен. Провери и границата: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Генерирай идеи от въпросите, не от празен лист“?","options":[{"id":"a","label":"Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него."},{"id":"b","label":"Идея от коментар не означава автоматично право да включиш потребителя в клипа."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Генерирай идеи от реални въпроси и ситуации. Една формулировка може да роди различни полезни видеа — демонстрация, обяснение, сравнение или кратък отговор — без да сменяш нуждата на зрителя.","Първо: Запиши конкретния въпрос с думите на човека. После: Създай поне три форми: демонстрация, обяснение и сравнение.","Следи за грешния ход: Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.","items":[{"id":"s1","text":"Запиши конкретния въпрос с думите на човека."},{"id":"s3","text":"За всяка избери кадър или факт, който ще носи стойността."},{"id":"s4","text":"Провери дали идеята се побира в цел, време, права и наличен ресурс."},{"id":"s2","text":"Създай поне три форми: демонстрация, обяснение и сравнение."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза. Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Въпрос: „Как ще знам, че глината е готова за следващата стъпка?“ Вариант 1 — близък план на допира и формата; вариант 2 — учителят показва две състояния; вариант 3 — грешка и поправка.\n\nПроменено условие: Идея от коментар не означава автоматично право да включиш потребителя в клипа.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка."},{"id":"a","label":"Отваряш празен лист и избираш най-трендовия звук, после насила търсиш продукт в него."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Поддържай списък със сигнал, идея, доказателство, ресурс и следваща стъпка. Отбелязвай версията на идеята, за да не заснемете два пъти една и съща теза. Границата тук е: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.\n\nКарта за работа — Генерирай идеи от въпросите, не от празен лист\n1. Запиши конкретния въпрос с думите на човека.\n2. Създай поне три форми: демонстрация, обяснение и сравнение.\n3. За всяка избери кадър или факт, който ще носи стойността.\n4. Провери дали идеята се побира в цел, време, права и наличен ресурс.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-12","title":"Избери идея с ясни критерии","objective":"да сравниш идеи по полезност, доказуемост и възможност за производство","hook":"Най-забавната идея не винаги е най-подходящата за целта или бюджета.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш идеи по полезност, доказуемост и възможност за производство. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Най-забавната идея не винаги е най-подходящата за целта или бюджета.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избирай идея по ясни критерии, вместо по вкус или броя емоджита в чата. Полезност, доказуемост, достижимост и цена на производството трябва да се разглеждат заедно."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Направи малка оценка от 1 до 3, но не третирай сбора като научно предсказание. Висок интерес няма да спаси невярно твърдение. Дай „доказателството“ и „правата“ право на стоп: ако една от тях е нула, първо реши проблема или смени идеята. При равенство предпочети вариант, който оставя повече възможности за следващ епизод.\n\nГраница на правилото: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи нуждата и зрителя, за които идеята е предназначена.\n2. Провери доказателства, разрешения и налични материали.\n3. Оцени очакваната полезност, производствената цена и мястото на разпространение.\n4. Избери победителя и запиши защо е по-добър от следващия вариант.\n\nСтоп-сигнал: Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка. Десетичната точност не прави субективния приоритет обективен. Ако това се случи, приложи корекцията преди да продължиш: Използвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Екипът сравнява „история на основателката“ и „какво става на първия урок“. Първата има добър емоционален потенциал, но изисква допълнителен снимачен ден. Втората отговаря на повтарящия се въпрос, може да се заснеме в редовно занятие и има съгласие от инструктора. Изборът не гарантира гледания; той е най-силен по цел, доказателство и ресурс.\n\nРешение в този случай:\nИзползвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи.\n\nГраница на извода:\nПри регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка. Десетичната точност не прави субективния приоритет обективен."},"after":{"label":"По-доброто решение","text":"Използвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи.\n\nПреди да продължиш: Избери победителя и запиши защо е по-добър от следващия вариант."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Оцени идеите по еднаква скала: полезност, доказуемост, достъп до кадри, цена и риск. Отдели тежестта на критериите от оценката на самата идея; иначе харесванията ще изкривят резултата. Ако идеята е ефектна, но няма доказателство или разрешение, не компенсирай проблема с висок бал за популярност.\n\nКритерий за приемане: Избери победителя и запиши защо е по-добър от следващия вариант.\n\nКогато пробата се провали:\nСимптом: Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка.\nКорекция: Използвай матрицата за разговор, после назови ключовото допускане.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Избери идея с ясни критерии“?","options":[{"id":"a","label":"Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка."},{"id":"b","label":"Избирай идея по ясни критерии, вместо по вкус или броя емоджита в чата."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Избирай идея по ясни критерии, вместо по вкус или броя емоджита в чата. Полезност, доказуемост, достижимост и цена на производството трябва да се разглеждат заедно. Слабият ход е: Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка. Десетичната точност не прави субективния приоритет обективен. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Екипът сравнява „история на основателката“ и „какво става на първия урок“. Първата има добър емоционален потенциал, но изисква допълнителен снимачен ден. Втората отговаря на повтарящия се въпрос, може да се заснеме в редовно занятие и има съгласие от инструктора. Изборът не гарантира гледания; той е най-силен по цел, доказателство и ресурс.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Използвай матрицата за разговор, после назови ключовото допускане."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи. Грешният път — Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка. — оставя риска нерешен. Провери и границата: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Избери идея с ясни критерии“?","options":[{"id":"a","label":"Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избирай идея по ясни критерии, вместо по вкус или броя емоджита в чата. Полезност, доказуемост, достижимост и цена на производството трябва да се разглеждат заедно.","Първо: Определи нуждата и зрителя, за които идеята е предназначена. После: Провери доказателства, разрешения и налични материали.","Следи за грешния ход: Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.","items":[{"id":"s2","text":"Провери доказателства, разрешения и налични материали."},{"id":"s1","text":"Определи нуждата и зрителя, за които идеята е предназначена."},{"id":"s4","text":"Избери победителя и запиши защо е по-добър от следващия вариант."},{"id":"s3","text":"Оцени очакваната полезност, производствената цена и мястото на разпространение."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи. При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Екипът сравнява „история на основателката“ и „какво става на първия урок“.\n\nПроменено условие: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Избираш идеята с най-висок сбор, макар едно число да идва от непотвърдена оценка."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Използвай матрицата за разговор, после назови ключовото допускане."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай матрицата за разговор, после назови ключовото допускане. Преди снимане провери, че решаващият факт и достъпът са налице; ако липсват, смени идеята или отложи. Границата тук е: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nКарта за работа — Избери идея с ясни критерии\n1. Определи нуждата и зрителя, за които идеята е предназначена.\n2. Провери доказателства, разрешения и налични материали.\n3. Оцени очакваната полезност, производствената цена и мястото на разпространение.\n4. Избери победителя и запиши защо е по-добър от следващия вариант.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-13","title":"Начертай пътя на зрителя до видеото","objective":"да опишеш какво знае и какво още му трябва преди следващата стъпка","hook":"Видео може да е ясно само за хора, които вече познават продукта.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш какво знае и какво още му трябва преди следващата стъпка. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Видео може да е ясно само за хора, които вече познават продукта.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Планирай поредицата през това, което зрителят знае сега и коя информация му липсва за следващата стъпка. Различните етапи имат различни въпроси и не искат един и същ призив."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"В началото помагаш човекът да разпознае проблема; при сравнение му даваш критерии и ограничения; преди решение показваш условия, цена и какво следва; след покупка помагаш да започне добре. Това не е твърда фуния и един зрител може да прескача между етапите. Не крий важни условия до последния клип.\n\nГраница на правилото: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови какво знае зрителят преди видеото.\n2. Изброй един въпрос или риск, който още не е покрит.\n3. Избери съдържание, което затваря тази липса без да преувеличава.\n4. Свържи края с подходяща следваща страница, урок или демонстрация.\n\nСтоп-сигнал: Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува. Ако това се случи, приложи корекцията преди да продължиш: Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Човек, който за пръв път вижда работилницата, трябва да разбере как протича заниманието. Човек, който вече сравнява ателиета, се интересува от дата, продължителност, включени материали и отмяна. „Запиши се“ може да е подходящо за втория; за първия по-полезно е да покаже графика и условията.\n\nРешение в този случай:\nСвържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки.\n\nГраница на извода:\nНе използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."},"after":{"label":"По-доброто решение","text":"Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки.\n\nПреди да продължиш: Свържи края с подходяща следваща страница, урок или демонстрация."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Пътят на зрителя рядко е права линия. Хората могат да дойдат през препоръка, да проверят отзив и да се върнат по-късно. Картографирай въпроса във всяка точка и кой материал отговаря на него. Не слагай един и същи призив навсякъде: новият зрител може да има нужда от обяснение, а готовият — от актуална информация за записване.\n\nКритерий за приемане: Свържи края с подходяща следваща страница, урок или демонстрация.\n\nКогато пробата се провали:\nСимптом: Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува.\nКорекция: Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Начертай пътя на зрителя до видеото“?","options":[{"id":"a","label":"Планирай поредицата през това, което зрителят знае сега и коя информация му липсва за следващата стъпка."},{"id":"b","label":"Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Планирай поредицата през това, което зрителят знае сега и коя информация му липсва за следващата стъпка. Различните етапи имат различни въпроси и не искат един и същ призив. Слабият ход е: Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Човек, който за пръв път вижда работилницата, трябва да разбере как протича заниманието. Човек, който вече сравнява ателиета, се интересува от дата, продължителност, включени материали и отмяна. „Запиши се“ може да е подходящо за втория; за първия по-полезно е да покаже графика и условията.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка."},{"id":"b","label":"Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки. Грешният път — Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува. — оставя риска нерешен. Провери и границата: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Начертай пътя на зрителя до видеото“?","options":[{"id":"a","label":"Не използвай скрити условия като механизъм за конверсия."},{"id":"b","label":"Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Планирай поредицата през това, което зрителят знае сега и коя информация му липсва за следващата стъпка. Различните етапи имат различни въпроси и не искат един и същ призив.","Първо: Назови какво знае зрителят преди видеото. После: Изброй един въпрос или риск, който още не е покрит.","Следи за грешния ход: Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.","items":[{"id":"s3","text":"Избери съдържание, което затваря тази липса без да преувеличава."},{"id":"s2","text":"Изброй един въпрос или риск, който още не е покрит."},{"id":"s1","text":"Назови какво знае зрителят преди видеото."},{"id":"s4","text":"Свържи края с подходяща следваща страница, урок или демонстрация."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки. Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Човек, който за пръв път вижда работилницата, трябва да разбере как протича заниманието.\n\nПроменено условие: Не използвай скрити условия като механизъм за конверсия.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка."},{"id":"b","label":"Всяко видео завършва с еднакво „купи курса“, независимо дали зрителят току-що е разбрал, че такъв курс съществува."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Свържи клиповете чрез следващото логично знание: въведение → демонстрация → условия → подготовка. Дай ясна връзка и не обещавай, че редът ще бъде гледан от всеки. Границата тук е: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.\n\nКарта за работа — Начертай пътя на зрителя до видеото\n1. Назови какво знае зрителят преди видеото.\n2. Изброй един въпрос или риск, който още не е покрит.\n3. Избери съдържание, което затваря тази липса без да преувеличава.\n4. Свържи края с подходяща следваща страница, урок или демонстрация.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-14","title":"Избери формат според задачата и мястото на гледане","objective":"да съобразиш формат, продължителност и начин на гледане с идеята","hook":"Един и същ кадър не е автоматично подходящ за всяка платформа и екран.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съобразиш формат, продължителност и начин на гледане с идеята. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един и същ кадър не е автоматично подходящ за всяка платформа и екран.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избирай формат, продължителност и начин на гледане според задачата. Вертикалното видео не е автоматично най-добро, а краткото не е полезно, ако изрязва решаващия контекст."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Сравни две оси: каква информация трябва да се види и в каква среда ще се консумира. Близък план помага на демонстрация; широк кадър показва пространство; надпис носи име или стъпка; глас може да обясни причина. Провери субтитри, контраст, темпо и дали смисълът остава без звук.\n\nГраница на правилото: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери една задача на видеото: да покаже, обясни, сравни или разкаже.\n2. Напиши кои елементи трябва да се виждат или чуват, за да я изпълнят.\n3. Избери ориентация, кадриране и продължителност според канала и материала.\n4. Провери читаемост на телефон, без звук и при реалната скорост на гледане.\n\nСтоп-сигнал: Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет. Зрителят вижда резултат, но не може да повтори действието. Ако това се случи, приложи корекцията преди да продължиш: Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За клип за грънчарското колело вертикалният кадър добре показва ръце и форма, но може да скрие инструктора и реакцията на участника. Широкият кадър обяснява стаята; близкият — натиска. Късите надписи назовават стъпките. Монтажът трябва да остави достатъчно време да се види движението.\n\nРешение в този случай:\nСнимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст.\n\nГраница на извода:\nТочните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет. Зрителят вижда резултат, но не може да повтори действието."},"after":{"label":"По-доброто решение","text":"Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст.\n\nПреди да продължиш: Провери читаемост на телефон, без звук и при реалната скорост на гледане."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Избери формат след като знаеш къде и как човекът гледа. Вертикалното кадриране може да помогне на телефон, но да отреже ръцете или продукта; хоризонталното може да покаже контекст, но да остави твърде дребен детайл. Провери надписи, контраст, звук и кадриране на целевия екран преди да решиш кое е „най-добро“.\n\nКритерий за приемане: Провери читаемост на телефон, без звук и при реалната скорост на гледане.\n\nКогато пробата се провали:\nСимптом: Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет.\nКорекция: Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Избери формат според задачата и мястото на гледане“?","options":[{"id":"a","label":"Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Избирай формат, продължителност и начин на гледане според задачата."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Избирай формат, продължителност и начин на гледане според задачата. Вертикалното видео не е автоматично най-добро, а краткото не е полезно, ако изрязва решаващия контекст. Слабият ход е: Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет. Зрителят вижда резултат, но не може да повтори действието. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За клип за грънчарското колело вертикалният кадър добре показва ръце и форма, но може да скрие инструктора и реакцията на участника. Широкият кадър обяснява стаята; близкият — натиска. Късите надписи назовават стъпките. Монтажът трябва да остави достатъчно време да се види движението.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст. Грешният път — Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет. — оставя риска нерешен. Провери и границата: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Избери формат според задачата и мястото на гледане“?","options":[{"id":"a","label":"Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избирай формат, продължителност и начин на гледане според задачата. Вертикалното видео не е автоматично най-добро, а краткото не е полезно, ако изрязва решаващия контекст.","Първо: Избери една задача на видеото: да покаже, обясни, сравни или разкаже. После: Напиши кои елементи трябва да се виждат или чуват, за да я изпълнят.","Следи за грешния ход: Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.","items":[{"id":"s3","text":"Избери ориентация, кадриране и продължителност според канала и материала."},{"id":"s4","text":"Провери читаемост на телефон, без звук и при реалната скорост на гледане."},{"id":"s2","text":"Напиши кои елементи трябва да се виждат или чуват, за да я изпълнят."},{"id":"s1","text":"Избери една задача на видеото: да покаже, обясни, сравни или разкаже."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст. Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За клип за грънчарското колело вертикалният кадър добре показва ръце и форма, но може да скрие инструктора и реакцията на участника.\n\nПроменено условие: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии."},{"id":"a","label":"Съкращаваш демонстрация до два бързи кадъра, за да се побере в „идеална“ дължина от интернет."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Снимай основното доказателство в основния формат и провери безопасното кадриране за други версии. При нужда прави отделен монтаж, вместо автоматично да отрязваш ръце, надписи или контекст. Границата тук е: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.\n\nКарта за работа — Избери формат според задачата и мястото на гледане\n1. Избери една задача на видеото: да покаже, обясни, сравни или разкаже.\n2. Напиши кои елементи трябва да се виждат или чуват, за да я изпълнят.\n3. Избери ориентация, кадриране и продължителност според канала и материала.\n4. Провери читаемост на телефон, без звук и при реалната скорост на гледане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-15","title":"Разгледай референция по решенията, не само по усещането","objective":"да разложиш пример на конкретни визуални и редакционни решения","hook":"„Изглежда професионално“ не ти казва какво да направиш със собствената си сцена.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разложиш пример на конкретни визуални и редакционни решения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Изглежда професионално“ не ти казва какво да направиш със собствената си сцена.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Разглеждай референцията по видими решения, а не само по усещането. Отдели какво се случва в кадъра от причината, поради която смяташ, че работи."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Запиши времеви маркери: първи образ, първа нова информация, смяна на план, пауза, доказателство, призив. Разгледай звука, надписите, движението и редакционния ритъм отделно. Една популярна публикация не доказва, че монтажът сам е създал успеха; аудитория, разпространение и тема също влияят.\n\nГраница на правилото: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Копираш текста, кадъра и музиката, защото клипът има много гледания. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери референция със сходна задача или зрител.\n2. Опиши наблюдаеми решения във времева линия, без оценки като „яко“.\n3. Свържи всяко решение с предполагаем ефект и маркирай това като хипотеза.\n4. Избери един принцип за тест, не копирай целия монтаж.\n\nСтоп-сигнал: Копираш текста, кадъра и музиката, защото клипът има много гледания. Нито резултатът е гарантиран, нито чуждите права стават твои. Ако това се случи, приложи корекцията преди да продължиш: Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"В референция за готварска рецепта първият кадър показва готовия резултат, после се вижда една критична техника и накрая подреден списък с времето. Това са наблюдения. „Затова е набрала 2 милиона“ е причинно твърдение, което видеото само не доказва.\n\nРешение в този случай:\nНаправи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия.\n\nГраница на извода:\nГледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Копираш текста, кадъра и музиката, защото клипът има много гледания. Нито резултатът е гарантиран, нито чуждите права стават твои."},"after":{"label":"По-доброто решение","text":"Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия.\n\nПреди да продължиш: Избери един принцип за тест, не копирай целия монтаж."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Разглоби референцията на времеви отрязъци: първи кадър, промяна, доказателство, надпис, звук и финал. Запиши само видимото. Не заключавай, че бързият монтаж е причината за успеха само защото клипът има гледания. Използвай времева линия или кадри с бележки, за да предадеш наблюдението на екипа.\n\nКритерий за приемане: Избери един принцип за тест, не копирай целия монтаж.\n\nКогато пробата се провали:\nСимптом: Копираш текста, кадъра и музиката, защото клипът има много гледания.\nКорекция: Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Разгледай референция по решенията, не само по усещането“?","options":[{"id":"a","label":"Копираш текста, кадъра и музиката, защото клипът има много гледания."},{"id":"b","label":"Разглеждай референцията по видими решения, а не само по усещането."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Разглеждай референцията по видими решения, а не само по усещането. Отдели какво се случва в кадъра от причината, поради която смяташ, че работи. Слабият ход е: Копираш текста, кадъра и музиката, защото клипът има много гледания. Нито резултатът е гарантиран, нито чуждите права стават твои. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: В референция за готварска рецепта първият кадър показва готовия резултат, после се вижда една критична техника и накрая подреден списък с времето. Това са наблюдения. „Затова е набрала 2 милиона“ е причинно твърдение, което видеото само не доказва.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка."},{"id":"b","label":"Копираш текста, кадъра и музиката, защото клипът има много гледания."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия. Грешният път — Копираш текста, кадъра и музиката, защото клипът има много гледания. — оставя риска нерешен. Провери и границата: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Разгледай референция по решенията, не само по усещането“?","options":[{"id":"a","label":"Гледанията често зависят от платено разпространение, аудитория и момент."},{"id":"b","label":"Копираш текста, кадъра и музиката, защото клипът има много гледания."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Разглеждай референцията по видими решения, а не само по усещането. Отдели какво се случва в кадъра от причината, поради която смяташ, че работи.","Първо: Избери референция със сходна задача или зрител. После: Опиши наблюдаеми решения във времева линия, без оценки като „яко“.","Следи за грешния ход: Копираш текста, кадъра и музиката, защото клипът има много гледания."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.","items":[{"id":"s1","text":"Избери референция със сходна задача или зрител."},{"id":"s4","text":"Избери един принцип за тест, не копирай целия монтаж."},{"id":"s3","text":"Свържи всяко решение с предполагаем ефект и маркирай това като хипотеза."},{"id":"s2","text":"Опиши наблюдаеми решения във времева линия, без оценки като „яко“."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия. Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: В референция за готварска рецепта първият кадър показва готовия резултат, после се вижда една критична техника и накрая подреден списък с времето.\n\nПроменено условие: Гледанията често зависят от платено разпространение, аудитория и момент.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Копираш текста, кадъра и музиката, защото клипът има много гледания."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи карта на структурата: обещание → демонстрация → доказателство → следваща стъпка. Приложи я към собствен пример, със свои кадри, думи и условия. Границата тук е: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.\n\nКарта за работа — Разгледай референция по решенията, не само по усещането\n1. Избери референция със сходна задача или зрител.\n2. Опиши наблюдаеми решения във времева линия, без оценки като „яко“.\n3. Свържи всяко решение с предполагаем ефект и маркирай това като хипотеза.\n4. Избери един принцип за тест, не копирай целия монтаж.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-16","title":"Вземи принципа от референцията, не чуждото видео","objective":"да създадеш оригинален подход, като отделиш механиката от израза","hook":"Копираният hook или кадър звучи и изглежда като чужда работа, дори темата да е твоя.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да създадеш оригинален подход, като отделиш механиката от израза. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Копираният hook или кадър звучи и изглежда като чужда работа, дори темата да е твоя.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Вземи принципа от референцията, като отделиш структурата от нейния отличителен израз. Търси преносимо решение: какво научава зрителят и кога го научава."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Можеш да пренесеш ритъм, вид демонстрация или ред на информацията; не пренасяй чужда реплика, графична система, музика, кадър или разпознаваем сценарий. Промени примерите, доказателствата, мястото и конкретния проблем така, че идеята да произхожда от твоя проект.\n\nГраница на правилото: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови какво точно работи като принцип: контраст, последователност или демонстрация.\n2. Извади отличителни думи, образи, музика и графики от чуждия материал.\n3. Замени примера с твои наблюдения и доказателства.\n4. Провери, че новата версия има собствена гледна точка и права.\n\nСтоп-сигнал: „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка. Ако това се случи, приложи корекцията преди да продължиш: Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Референцията започва с предмет, който не успява, после показва три поправки. Ателието може да използва самия принцип „виж грешката → виж поправката“, но да снима различна безопасна грешка с глина и обяснение от своя майстор — без да копира репликите, графиката или кадъра.\n\nРешение в този случай:\nСъстави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина.\n\nГраница на извода:\nИдеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка."},"after":{"label":"По-доброто решение","text":"Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина.\n\nПреди да продължиш: Провери, че новата версия има собствена гледна точка и права."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Пренеси принципа, не разпознаваемия израз: можеш да изучиш ритъма „въпрос—демонстрация—резултат“, но заснеми собствен предмет, обстановка, текст и визуално решение. Запази източника на референцията във вътрешния бриф и провери музика, шрифт, лого и кадри за права. Вдъхновението не заменя разрешението.\n\nКритерий за приемане: Провери, че новата версия има собствена гледна точка и права.\n\nКогато пробата се провали:\nСимптом: „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка.\nКорекция: Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Вземи принципа от референцията, не чуждото видео“?","options":[{"id":"a","label":"Вземи принципа от референцията, като отделиш структурата от нейния отличителен израз."},{"id":"b","label":"„Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Вземи принципа от референцията, като отделиш структурата от нейния отличителен израз. Търси преносимо решение: какво научава зрителят и кога го научава. Слабият ход е: „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Референцията започва с предмет, който не успява, после показва три поправки. Ателието може да използва самия принцип „виж грешката → виж поправката“, но да снима различна безопасна грешка с глина и обяснение от своя майстор — без да копира репликите, графиката или кадъра.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"„Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка."},{"id":"b","label":"Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина. Грешният път — „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената… — оставя риска нерешен. Провери и границата: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Вземи принципа от референцията, не чуждото видео“?","options":[{"id":"a","label":"„Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка."},{"id":"b","label":"Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Вземи принципа от референцията, като отделиш структурата от нейния отличителен израз. Търси преносимо решение: какво научава зрителят и кога го научава.","Първо: Назови какво точно работи като принцип: контраст, последователност или демонстрация. После: Извади отличителни думи, образи, музика и графики от чуждия материал.","Следи за грешния ход: „Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената…"],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.","items":[{"id":"s2","text":"Извади отличителни думи, образи, музика и графики от чуждия материал."},{"id":"s4","text":"Провери, че новата версия има собствена гледна точка и права."},{"id":"s1","text":"Назови какво точно работи като принцип: контраст, последователност или демонстрация."},{"id":"s3","text":"Замени примера с твои наблюдения и доказателства."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина. Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Референцията започва с предмет, който не успява, после показва три поправки.\n\nПроменено условие: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика."},{"id":"b","label":"„Само ще сменя логото и цвета, останалото е вдъхновение.“ Отличителният монтаж и сценарий могат да останат разпознаваеми и да подкопаят собствената марка."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Състави нова карта с четири полета: зрителски въпрос, твое доказателство, оригинална демонстрация, собствена реплика. Сравни финалния клип с референцията и махни елементи, които нямат независима причина. Границата тук е: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.\n\nКарта за работа — Вземи принципа от референцията, не чуждото видео\n1. Назови какво точно работи като принцип: контраст, последователност или демонстрация.\n2. Извади отличителни думи, образи, музика и графики от чуждия материал.\n3. Замени примера с твои наблюдения и доказателства.\n4. Провери, че новата версия има собствена гледна точка и права.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-17","title":"Напиши едностраничен творчески бриф","objective":"да събереш цел, аудитория, обещание, доказателство и производствени ограничения","hook":"Ако брифът е само тема, снимачният екип ще трябва да измисли останалото на място.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да събереш цел, аудитория, обещание, доказателство и производствени ограничения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако брифът е само тема, снимачният екип ще трябва да измисли останалото на място.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Събери творческия бриф на една страница, за да може клиентът, сценаристът и снимачният екип да вземат съвместими решения."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Брифът не е списък с прилагателни. Той свързва аудитория, ситуация, цел, обещание, доказателство, основен извод, формат, призив, права, ресурси и критерии за приемане. Ако две точки си противоречат — например „спокойно обяснение“ и „пет секунди, десет кадъра“ — реши конфликта преди снимане.\n\nГраница на правилото: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как… — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Попълни зрителя, момент и проблем от наличните наблюдения.\n2. Напиши обещание и доказателство, които си проверил.\n3. Посочи формат, призив за действие, ограничения и какво не включва проектът.\n4. Потвърди собственик на одобрението, срок и критерии за приемане.\n\nСтоп-сигнал: „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата е изпълнена. Ако това се случи, приложи корекцията преди да продължиш: Завърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Брифът за „Ръце в глина“ казва: начинаещ на телефон иска да знае дали ще се справи; цел — да види първите стъпки и да отвори графика; доказателство — инструктор демонстрира начално оформяне; формат — вертикален клип със субтитри; условията за материали са одобрени от ателието; участници в кадър — само с разрешение.\n\nРешение в този случай:\nЗавърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания.\n\nГраница на извода:\nБрифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата е изпълнена."},"after":{"label":"По-доброто решение","text":"Завърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания.\n\nПреди да продължиш: Потвърди собственик на одобрението, срок и критерии за приемане."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Брифът трябва да позволява действие без устно доуточняване. Включи цел, зрител, едно обещание, доказателства, неизвестни, канал, формат, срок, ограничения, права и човек за одобрение. Маркирай кое е окончателно и кой може да го промени. При противоречие между брифа и коментар в чат нека екипът знае кой запис е меродавен.\n\nКритерий за приемане: Потвърди собственик на одобрението, срок и критерии за приемане.\n\nКогато пробата се провали:\nСимптом: „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата е изпълнена.\nКорекция: Завърши брифа с поле „неизвестно/чака одобрение“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Напиши едностраничен творчески бриф“?","options":[{"id":"a","label":"„Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата…"},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Събери творческия бриф на една страница, за да може клиентът, сценаристът и снимачният екип да вземат съвместими решения."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Събери творческия бриф на една страница, за да може клиентът, сценаристът и снимачният екип да вземат съвместими решения. Слабият ход е: „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата е изпълнена. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Брифът за „Ръце в глина“ казва: начинаещ на телефон иска да знае дали ще се справи; цел — да види първите стъпки и да отвори графика; доказателство — инструктор демонстрира начално оформяне; формат — вертикален клип със субтитри; условията за материали са одобрени от ателието; участници в кадър — само с разрешение.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"„Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата…"},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Завърши брифа с поле „неизвестно/чака одобрение“."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Завърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания. Грешният път — „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме… — оставя риска нерешен. Провери и границата: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Напиши едностраничен творчески бриф“?","options":[{"id":"a","label":"„Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата…"},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Брифът е жив документ до одобрението на концепцията."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Събери творческия бриф на една страница, за да може клиентът, сценаристът и снимачният екип да вземат съвместими решения.","Първо: Попълни зрителя, момент и проблем от наличните наблюдения. После: Напиши обещание и доказателство, които си проверил.","Следи за грешния ход: „Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме…"],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.","items":[{"id":"s1","text":"Попълни зрителя, момент и проблем от наличните наблюдения."},{"id":"s3","text":"Посочи формат, призив за действие, ограничения и какво не включва проектът."},{"id":"s2","text":"Напиши обещание и доказателство, които си проверил."},{"id":"s4","text":"Потвърди собственик на одобрението, срок и критерии за приемане."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Завърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания. Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Брифът за „Ръце в глина“ казва: начинаещ на телефон иска да знае дали ще се справи; цел — да види първите стъпки и да отвори графика; доказателство — инструктор демонстрира начално оформяне; формат — вертикален клип със субтитри; условията за материали са одобрени от ателието; участници в кадър — само с разрешение.\n\nПроменено условие: Брифът е жив документ до одобрението на концепцията.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Завърши брифа с поле „неизвестно/чака одобрение“."},{"id":"a","label":"„Искаме луксозно, автентично, кинематографично и вирусно видео за всички платформи.“ Това не казва кой решава, какво показваме или как разбираме дали задачата е изпълнена."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Завърши брифа с поле „неизвестно/чака одобрение“. Ако е празно, не приемай мълчанието за съгласие. Раздай една версия на екипа, за да няма различни снимки на различни обещания. Границата тук е: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.\n\nКарта за работа — Напиши едностраничен творчески бриф\n1. Попълни зрителя, момент и проблем от наличните наблюдения.\n2. Напиши обещание и доказателство, които си проверил.\n3. Посочи формат, призив за действие, ограничения и какво не включва проектът.\n4. Потвърди собственик на одобрението, срок и критерии за приемане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-18","title":"Намери ъгъла, който прави темата конкретна","objective":"да избираш гледна точка, която добавя смисъл към позната тема","hook":"Темата може да е обща; разликата често е в конкретния въпрос, случай или ограничение.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш гледна точка, която добавя смисъл към позната тема. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Темата може да е обща; разликата често е в конкретния въпрос, случай или ограничение.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Намери ъгъл — конкретния смислов избор, който прави познатата тема полезна за точно определен зрител."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Един ъгъл може да започне от погрешно очакване, пропуснато условие, видим резултат или труден избор. Той не е просто по-шумен хук. Провери дали добавя информация, дали я можеш да докажеш и дали съответства на тона на проекта.\n\nГраница на правилото: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши широка тема без рекламна украса.\n2. Назови конкретното напрежение или въпрос на зрителя.\n3. Избери една гледна точка, която можеш да покажеш с материал.\n4. Сравни поне две версии за яснота, оригиналност и доказуемост.\n\nСтоп-сигнал: Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие. Това създава клик, после разочарование. Ако това се случи, приложи корекцията преди да продължиш: Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Широка тема: първи урок по керамика. Ъгъл 1: „Какво става през първите 10 минути, ако никога не си пипал глина?“ Ъгъл 2: „Коя форма е най-лесна?“ Първият отговаря на тревогата за непознатото, вторият обещава сравнение, което изисква ясно определение за „лесна“. Изборът следва сигнала от разговорите.\n\nРешение в този случай:\nПровери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка.\n\nГраница на извода:\nНе превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие. Това създава клик, после разочарование."},"after":{"label":"По-доброто решение","text":"Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка.\n\nПреди да продължиш: Сравни поне две версии за яснота, оригиналност и доказуемост."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Ъгълът не е просто остро заглавие. Той е конкретна позиция, която се доказва чрез сцена или факт. Запиши твърдението и веднага до него кадъра, който би го потвърдил; ако кадърът не може да съществува, ъгълът още не е готов. Провери и границата: какво няма да заключаваш от този пример.\n\nКритерий за приемане: Сравни поне две версии за яснота, оригиналност и доказуемост.\n\nКогато пробата се провали:\nСимптом: Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие.\nКорекция: Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това?\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Намери ъгъла, който прави темата конкретна“?","options":[{"id":"a","label":"Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Намери ъгъл — конкретния смислов избор, който прави познатата тема полезна за точно определен зрител."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Намери ъгъл — конкретния смислов избор, който прави познатата тема полезна за точно определен зрител. Слабият ход е: Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие. Това създава клик, после разочарование. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Широка тема: първи урок по керамика. Ъгъл 1: „Какво става през първите 10 минути, ако никога не си пипал глина?“ Ъгъл 2: „Коя форма е най-лесна?“ Първият отговаря на тревогата за непознатото, вторият обещава сравнение, което изисква ясно определение за „лесна“. Изборът следва сигнала от разговорите.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие."},{"id":"b","label":"Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това?"},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка. Грешният път — Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие. — оставя риска нерешен. Провери и границата: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Намери ъгъла, който прави темата конкретна“?","options":[{"id":"a","label":"Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие."},{"id":"b","label":"Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Намери ъгъл — конкретния смислов избор, който прави познатата тема полезна за точно определен зрител.","Първо: Запиши широка тема без рекламна украса. После: Назови конкретното напрежение или въпрос на зрителя.","Следи за грешния ход: Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.","items":[{"id":"s2","text":"Назови конкретното напрежение или въпрос на зрителя."},{"id":"s4","text":"Сравни поне две версии за яснота, оригиналност и доказуемост."},{"id":"s3","text":"Избери една гледна точка, която можеш да покажеш с материал."},{"id":"s1","text":"Запиши широка тема без рекламна украса."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка. Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Широка тема: първи урок по керамика.\n\nПроменено условие: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Избираш „Никой не ти казва това за глината!“ без тайна, доказателство или причина за прикритие."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това?"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Провери ъгъла с три въпроса: какво ново разбира човекът, как ще го види и какво се променя след това? Ако отговорът е само „ще изглежда по-интересно“, смени гледната точка. Границата тук е: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.\n\nКарта за работа — Намери ъгъла, който прави темата конкретна\n1. Запиши широка тема без рекламна украса.\n2. Назови конкретното напрежение или въпрос на зрителя.\n3. Избери една гледна точка, която можеш да покажеш с материал.\n4. Сравни поне две версии за яснота, оригиналност и доказуемост.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-19","title":"Планирай какво трябва да се види","objective":"да превърнеш брифа в материал, който зрителят може да наблюдава","hook":"Обяснение без видим пример често оставя зрителя с много думи и малко разбиране.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш брифа в материал, който зрителят може да наблюдава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Обяснение без видим пример често оставя зрителя с много думи и малко разбиране.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Превеждай всяко важно твърдение в кадър, звук или графика, която помага на зрителя да го провери. Списъкът с кадри трябва да носи смисъл, не просто да запълва монтаж."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Направи карта „твърдение → доказателство → кадър → надпис/звук“. Ако казваш, че материалите са включени, покажи реално какви и потвърди с клиента. Ако обясняваш натиск на ръката, снимай точката на контакт и движението. Декоративният допълнителен кадър не замества кадър, който доказва основното.\n\nГраница на правилото: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Маркирай всяка реплика или текст, който носи важно твърдение.\n2. Избери наблюдаемо доказателство и най-четим план за него.\n3. Добави реакционен, установяващ и детайлен кадър, ако наративът ги изисква.\n4. Провери, че кадрите не разкриват лични данни или чужда работа без право.\n\nСтоп-сигнал: Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие. Ако това се случи, приложи корекцията преди да продължиш: Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Реплика: „Инструкторът показва начинаещия ход.“ Кадрова двойка: среден план на ръцете за контекст, близък план на формата и кратък кадър на инструктора, който коригира натиска. Надписът назовава движението, не поставя недоказана оценка „най-добрата техника“.\n\nРешение в този случай:\nПодреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи.\n\nГраница на извода:\nНе обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."},"after":{"label":"По-доброто решение","text":"Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи.\n\nПреди да продължиш: Провери, че кадрите не разкриват лични данни или чужда работа без право."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Планирай покритие по действие: установяващ кадър за мястото, среден за човека и детайл за решаващото движение. Заснеми начално състояние, ключов момент и резултат, плюс резервен кадър за монтаж. Детайл без предходен контекст често е красив, но не обяснява какво се е случило.\n\nКритерий за приемане: Провери, че кадрите не разкриват лични данни или чужда работа без право.\n\nКогато пробата се провали:\nСимптом: Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие.\nКорекция: Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Планирай какво трябва да се види“?","options":[{"id":"a","label":"Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."},{"id":"b","label":"Превеждай всяко важно твърдение в кадър, звук или графика, която помага на зрителя да го провери."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Превеждай всяко важно твърдение в кадър, звук или графика, която помага на зрителя да го провери. Списъкът с кадри трябва да носи смисъл, не просто да запълва монтаж. Слабият ход е: Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Реплика: „Инструкторът показва начинаещия ход.“ Кадрова двойка: среден план на ръцете за контекст, близък план на формата и кратък кадър на инструктора, който коригира натиска. Надписът назовава движението, не поставя недоказана оценка „най-добрата техника“.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи. Грешният път — Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие. — оставя риска нерешен. Провери и границата: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Планирай какво трябва да се види“?","options":[{"id":"a","label":"Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не обещавай, че монтажът може да поправи липсващо доказателство."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Превеждай всяко важно твърдение в кадър, звук или графика, която помага на зрителя да го провери. Списъкът с кадри трябва да носи смисъл, не просто да запълва монтаж.","Първо: Маркирай всяка реплика или текст, който носи важно твърдение. После: Избери наблюдаемо доказателство и най-четим план за него.","Следи за грешния ход: Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.","items":[{"id":"s3","text":"Добави реакционен, установяващ и детайлен кадър, ако наративът ги изисква."},{"id":"s4","text":"Провери, че кадрите не разкриват лични данни или чужда работа без право."},{"id":"s1","text":"Маркирай всяка реплика или текст, който носи важно твърдение."},{"id":"s2","text":"Избери наблюдаемо доказателство и най-четим план за него."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи. Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Реплика: „Инструкторът показва начинаещия ход.“ Кадрова двойка: среден план на ръцете за контекст, близък план на формата и кратък кадър на инструктора, който коригира натиска.\n\nПроменено условие: Не обещавай, че монтажът може да поправи липсващо доказателство.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход."},{"id":"b","label":"Снимаш чаши, усмивки и завършени изделия, но нито един кадър не показва какво реално се случва на първото занятие."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Подреди списък с кадри по функция: ориентация, действие, детайл, резултат, преход. Отбележи кадър, който не бива да липсва, и резервен план, ако демонстрацията не се получи. Границата тук е: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.\n\nКарта за работа — Планирай какво трябва да се види\n1. Маркирай всяка реплика или текст, който носи важно твърдение.\n2. Избери наблюдаемо доказателство и най-четим план за него.\n3. Добави реакционен, установяващ и детайлен кадър, ако наративът ги изисква.\n4. Провери, че кадрите не разкриват лични данни или чужда работа без право.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-20","title":"Оцени място, време и налични ресурси","objective":"да направиш план, който може да се произведе при реалните ограничения","hook":"Най-добрата идея е безполезна, ако не можеш да я снимаш с времето и ресурсите си.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да направиш план, който може да се произведе при реалните ограничения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Най-добрата идея е безполезна, ако не можеш да я снимаш с времето и ресурсите си.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Оцени локация, време и ресурси преди да обещаеш снимане. Планът трябва да издържа на реалния шум, достъп, светлина, хора и резервни варианти."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Раздели задачите на задължителни и желателни. Провери кога локацията е тиха, къде има ток, как се движи слънцето, има ли разрешение и колко време е нужно за подготовка. Добави резерв за забавяне, копие на картите и място за безопасно съхранение. Нямаш нужда от най-скъпата техника, а от планиран контрол върху слабите звена.\n\nГраница на правилото: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Огледай мястото по време на планирания час и запиши шум, светлина и фон.\n2. Потвърди достъп, съгласие, захранване, карта памет и транспорт.\n3. Събери нужната екипировка по функция и провери съвместимостта.\n4. Определи резервен кадър, място или време за най-големия риск.\n\nСтоп-сигнал: Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор. Времето за запис е изядено от преместване. Ако това се случи, приложи корекцията преди да продължиш: Провери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Ателието е тихо сутрин, но в събота работи колелото и аспирацията. Снимането на репликите се мести преди групата; демонстрационните кадри се правят след като участниците напуснат или подпишат съгласие. Телефонът се зарежда, звукът се тества с машината включена, а картите се копират на отделен носител.\n\nРешение в този случай:\nПровери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна.\n\nГраница на извода:\nПри шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор. Времето за запис е изядено от преместване."},"after":{"label":"По-доброто решение","text":"Провери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна.\n\nПреди да продължиш: Определи резервен кадър, място или време за най-големия риск."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Разузнай мястото по часа на реалното снимане. Провери шум, достъп, ток, отражения, движение на хора, разрешения и къде ще стоят техниката и екипът. Не разчитай на оглед при различна светлина. Подготви резервна позиция и решение за звук, преди да поканиш участниците.\n\nКритерий за приемане: Определи резервен кадър, място или време за най-големия риск.\n\nКогато пробата се провали:\nСимптом: Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор.\nКорекция: Провери локацията с кратък тестов запис и слушай през слушалки.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Оцени място, време и налични ресурси“?","options":[{"id":"a","label":"Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор."},{"id":"b","label":"Една публикация доказва сама по себе си защо продажбите са се променили."},{"id":"c","label":"Оцени локация, време и ресурси преди да обещаеш снимане."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Оцени локация, време и ресурси преди да обещаеш снимане. Планът трябва да издържа на реалния шум, достъп, светлина, хора и резервни варианти. Слабият ход е: Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор. Времето за запис е изядено от преместване. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Ателието е тихо сутрин, но в събота работи колелото и аспирацията. Снимането на репликите се мести преди групата; демонстрационните кадри се правят след като участниците напуснат или подпишат съгласие. Телефонът се зарежда, звукът се тества с машината включена, а картите се копират на отделен носител.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор."},{"id":"b","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."},{"id":"c","label":"Провери локацията с кратък тестов запис и слушай през слушалки."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Провери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна. Грешният път — Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор. — оставя риска нерешен. Провери и границата: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Оцени място, време и налични ресурси“?","options":[{"id":"a","label":"Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Оцени локация, време и ресурси преди да обещаеш снимане. Планът трябва да издържа на реалния шум, достъп, светлина, хора и резервни варианти.","Първо: Огледай мястото по време на планирания час и запиши шум, светлина и фон. После: Потвърди достъп, съгласие, захранване, карта памет и транспорт.","Следи за грешния ход: Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.","items":[{"id":"s1","text":"Огледай мястото по време на планирания час и запиши шум, светлина и фон."},{"id":"s3","text":"Събери нужната екипировка по функция и провери съвместимостта."},{"id":"s4","text":"Определи резервен кадър, място или време за най-големия риск."},{"id":"s2","text":"Потвърди достъп, съгласие, захранване, карта памет и транспорт."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Провери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна. При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Ателието е тихо сутрин, но в събота работи колелото и аспирацията.\n\nПроменено условие: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Провери локацията с кратък тестов запис и слушай през слушалки."},{"id":"a","label":"Екипът пристига без оглед и разбира, че зад кадъра има огледало, чужди лица и силен компресор."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Провери локацията с кратък тестов запис и слушай през слушалки. Запиши кой носи всяка вещ, къде е резервното копие и кой може да разреши промяна. Границата тук е: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.\n\nКарта за работа — Оцени място, време и налични ресурси\n1. Огледай мястото по време на планирания час и запиши шум, светлина и фон.\n2. Потвърди достъп, съгласие, захранване, карта памет и транспорт.\n3. Събери нужната екипировка по функция и провери съвместимостта.\n4. Определи резервен кадър, място или време за най-големия риск.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-21","title":"Подреди деня на снимане по зависимости","objective":"да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко","hook":"Заснемането се бави, когато един необходим детайл се открие след пристигането на екипа.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Заснемането се бави, когато един необходим детайл се открие след пристигането на екипа.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подреди деня на снимане по зависимостите между хора, локации, светлина и техника, а не само по реда, в който видеото ще се гледа."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Групирай кадрите по настройка и локация; осигури непрекъснатост на реквизита и състоянието на материала. Предвиди време за монтаж, проба, дубъл и копиране на файловете. Сценарният ред остава в списъка с кадри, но снимачният ред може да е друг, ако това намалява пренастройването.\n\nГраница на правилото: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Снимаш в сценарен ред и сменяш осветлението шест пъти. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Раздели сценария на кадри, локации, хора и реквизит.\n2. Групирай по настройка, като запиши непрекъснатостта на реквизита, което трябва да остане еднакво.\n3. Добави буфер, тестов дубъл, паузи и резервно копиране.\n4. Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява.\n\nСтоп-сигнал: Снимаш в сценарен ред и сменяш осветлението шест пъти. Между кадрите глината изсъхва и позицията на инструмента се променя. Ако това се случи, приложи корекцията преди да продължиш: Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Същата маса и глина се виждат в началото и края. Вместо да снимаш по монтажния ред, снимай всички кадри на масата наведнъж; снимай референсна снимка на позицията. Раздели гласовите реплики от работилницата шумните. Планът съдържа 20 минути за тест на звук и поне две копия на картата преди напускане.\n\nРешение в този случай:\nИзползвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори.\n\nГраница на извода:\nНе притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Снимаш в сценарен ред и сменяш осветлението шест пъти. Между кадрите глината изсъхва и позицията на инструмента се променя."},"after":{"label":"По-доброто решение","text":"Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори.\n\nПреди да продължиш: Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Планирай снимачния ден по настройки и локации, не по реда на готовия клип. Така намаляваш смяната на светлина и техника. Между блоковете остави време за преместване, проверка на звук, резервна батерия и копиране на картите. Запиши отговорника за всяка зависимост и час, след който планът трябва да се промени.\n\nКритерий за приемане: Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява.\n\nКогато пробата се провали:\nСимптом: Снимаш в сценарен ред и сменяш осветлението шест пъти.\nКорекция: Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подреди деня на снимане по зависимости“?","options":[{"id":"a","label":"Подреди деня на снимане по зависимостите между хора, локации, светлина и техника, а не само по реда, в който видеото ще се гледа."},{"id":"b","label":"Снимаш в сценарен ред и сменяш осветлението шест пъти."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Подреди деня на снимане по зависимостите между хора, локации, светлина и техника, а не само по реда, в който видеото ще се гледа. Слабият ход е: Снимаш в сценарен ред и сменяш осветлението шест пъти. Между кадрите глината изсъхва и позицията на инструмента се променя. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Същата маса и глина се виждат в началото и края. Вместо да снимаш по монтажния ред, снимай всички кадри на масата наведнъж; снимай референсна снимка на позицията. Раздели гласовите реплики от работилницата шумните. Планът съдържа 20 минути за тест на звук и поне две копия на картата преди напускане.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Снимаш в сценарен ред и сменяш осветлението шест пъти."},{"id":"b","label":"Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори. Грешният път — Снимаш в сценарен ред и сменяш осветлението шест пъти. — оставя риска нерешен. Провери и границата: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подреди деня на снимане по зависимости“?","options":[{"id":"a","label":"Снимаш в сценарен ред и сменяш осветлението шест пъти."},{"id":"b","label":"Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подреди деня на снимане по зависимостите между хора, локации, светлина и техника, а не само по реда, в който видеото ще се гледа.","Първо: Раздели сценария на кадри, локации, хора и реквизит. После: Групирай по настройка, като запиши непрекъснатостта на реквизита, което трябва да остане еднакво.","Следи за грешния ход: Снимаш в сценарен ред и сменяш осветлението шест пъти."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.","items":[{"id":"s2","text":"Групирай по настройка, като запиши непрекъснатостта на реквизита, което трябва да остане еднакво."},{"id":"s1","text":"Раздели сценария на кадри, локации, хора и реквизит."},{"id":"s4","text":"Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява."},{"id":"s3","text":"Добави буфер, тестов дубъл, паузи и резервно копиране."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори. Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Същата маса и глина се виждат в началото и края.\n\nПроменено условие: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Снимаш в сценарен ред и сменяш осветлението шест пъти."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай графа на зависимостите: кой кадър изисква предишен материал, кой ресурс е общ и коя светлина се променя. Отбележи как ще възстановиш състоянието, ако дубълът се повтори. Границата тук е: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.\n\nКарта за работа — Подреди деня на снимане по зависимости\n1. Раздели сценария на кадри, локации, хора и реквизит.\n2. Групирай по настройка, като запиши непрекъснатостта на реквизита, което трябва да остане еднакво.\n3. Добави буфер, тестов дубъл, паузи и резервно копиране.\n4. Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-22","title":"Направи техническа и редакционна проверка преди запис","objective":"да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл","hook":"Един кратък тест може да спести час монтаж на неизползваем материал.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един кратък тест може да спести час монтаж на неизползваем материал.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Провери техническите и редакционните условия, преди да заснемеш основния материал. Кратък тест намира проблеми, докато още можеш да ги поправиш."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Проверявай системата от вход към изход: карта/формат/кадрова честота, експозиция и фокус, микрофон и шум, композиция и фон, разрешения, текст и обещание. Прослушай тест със слушалки; индикаторът на камерата не казва дали дрехата стърже по микрофона. Запиши тестовия файл и отвори файла, преди да започне дубълът.\n\nГраница на правилото: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Започваш пълния дубъл след едно бързо кимване „звук има“. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Провери заряд, място, формат, фокус и цвят на камерата.\n2. Запиши 10 секунди с човека на реалното му място и прослушай.\n3. Провери кадър за фон, надписи, права и неволно разкрити данни.\n4. Потвърди основния кадър и резервен вариант с отговорния човек.\n\nСтоп-сигнал: Започваш пълния дубъл след едно бързо кимване „звук има“. После откриваш клипинг и чуждо лице в отражението. Ако това се случи, приложи корекцията преди да продължиш: Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Картината на камерата изглежда добра, но тестът със слушалки улавя шум от машината и триене на престилката. Петличният микрофон се премества, аспирацията се спира по съгласуван начин, а кадърът се записва отново. Тестът също открива менюто с лични имена в периферията на кадъра.\n\nРешение в този случай:\nИзползвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран.\n\nГраница на извода:\nНе отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Започваш пълния дубъл след едно бързо кимване „звук има“. После откриваш клипинг и чуждо лице в отражението."},"after":{"label":"По-доброто решение","text":"Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран.\n\nПреди да продължиш: Потвърди основния кадър и резервен вариант с отговорния човек."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Тестовият дубъл трябва да съдържа реален човек, движение, осветление и звук от мястото. Гледай оригинала на по-голям екран, слушай със слушалки и провери четливостта на телефона. Ако първият тест разкрие проблем, спри преди основния запис. Краткото забавяне тук спестява преснимане и липсващ материал.\n\nКритерий за приемане: Потвърди основния кадър и резервен вариант с отговорния човек.\n\nКогато пробата се провали:\nСимптом: Започваш пълния дубъл след едно бързо кимване „звук има“.\nКорекция: Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Направи техническа и редакционна проверка преди запис“?","options":[{"id":"a","label":"Провери техническите и редакционните условия, преди да заснемеш основния материал."},{"id":"b","label":"Започваш пълния дубъл след едно бързо кимване „звук има“."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Провери техническите и редакционните условия, преди да заснемеш основния материал. Кратък тест намира проблеми, докато още можеш да ги поправиш. Слабият ход е: Започваш пълния дубъл след едно бързо кимване „звук има“. После откриваш клипинг и чуждо лице в отражението. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Картината на камерата изглежда добра, но тестът със слушалки улавя шум от машината и триене на престилката. Петличният микрофон се премества, аспирацията се спира по съгласуван начин, а кадърът се записва отново. Тестът също открива менюто с лични имена в периферията на кадъра.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Започваш пълния дубъл след едно бързо кимване „звук има“."},{"id":"b","label":"Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран. Грешният път — Започваш пълния дубъл след едно бързо кимване „звук има“. — оставя риска нерешен. Провери и границата: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Направи техническа и редакционна проверка преди запис“?","options":[{"id":"a","label":"Започваш пълния дубъл след едно бързо кимване „звук има“."},{"id":"b","label":"Не отваряй и не форматирай карта с единствено копие на материала."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Провери техническите и редакционните условия, преди да заснемеш основния материал. Кратък тест намира проблеми, докато още можеш да ги поправиш.","Първо: Провери заряд, място, формат, фокус и цвят на камерата. После: Запиши 10 секунди с човека на реалното му място и прослушай.","Следи за грешния ход: Започваш пълния дубъл след едно бързо кимване „звук има“."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.","items":[{"id":"s3","text":"Провери кадър за фон, надписи, права и неволно разкрити данни."},{"id":"s2","text":"Запиши 10 секунди с човека на реалното му място и прослушай."},{"id":"s1","text":"Провери заряд, място, формат, фокус и цвят на камерата."},{"id":"s4","text":"Потвърди основния кадър и резервен вариант с отговорния човек."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран. Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Картината на камерата изглежда добра, но тестът със слушалки улавя шум от машината и триене на престилката.\n\nПроменено условие: Не отваряй и не форматирай карта с единствено копие на материала.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл."},{"id":"b","label":"Започваш пълния дубъл след едно бързо кимване „звук има“."},{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай контролен списък за тестов дубъл и записвай резултата в името на тестовия файл. Не разчитай на слуха през вградения микрофон на телефона или на миниатюрния екран. Границата тук е: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.\n\nКарта за работа — Направи техническа и редакционна проверка преди запис\n1. Провери заряд, място, формат, фокус и цвят на камерата.\n2. Запиши 10 секунди с човека на реалното му място и прослушай.\n3. Провери кадър за фон, надписи, права и неволно разкрити данни.\n4. Потвърди основния кадър и резервен вариант с отговорния човек.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-23","title":"Планирай как ще научиш от резултата","objective":"да формулираш хипотеза и правило за следваща итерация","hook":"Ако смениш едновременно хук, тема, дължина и призив за действие, няма да знаеш какво е повлияло.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да формулираш хипотеза и правило за следваща итерация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако смениш едновременно хук, тема, дължина и призив за действие, няма да знаеш какво е повлияло.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Формулирай какво ще провериш след публикация и какъв резултат би променил следващата версия. Анализът е полезен само ако сравнява правилния момент и не превръща съвпадението в причина."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Преди теста запиши хипотеза, една променлива, основен показател, период и условие за решение. Не сменяй едновременно хук, аудитория и оферта. Гледай абсолютен брой заедно с процента и сравнявай клипове сходни по дължина и тема. YouTube Analytics показва задържане и ключови моменти; спадът е сигнал къде проверяваш, а не автоматична диагноза.\n\nГраница на правилото: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши хипотезата и една промяна, която ще тестваш.\n2. Определи показателя, знаменател, период и източник преди публикация.\n3. Сравни с релевантен базов клип и отбележи външни промени.\n4. Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн.\n\nСтоп-сигнал: Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината. Разпределението на показванията е различно. Ако това се случи, приложи корекцията преди да продължиш: Запази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Хипотеза: краткият кадър как инструкторът изправя формата ще задържи повече хора до обяснението. Версиите се различават само в първите три секунди; основен показател е задържането до 10-та секунда, вторичен — посещенията на графика. Сравняваш сходен период, но отбелязваш, че промоция в същия ден може да е повлияла.\n\nРешение в този случай:\nЗапази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“.\n\nГраница на извода:\nПри малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината. Разпределението на показванията е различно."},"after":{"label":"По-доброто решение","text":"Запази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“.\n\nПреди да продължиш: Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Преди публикация запиши хипотеза, една променлива, основен показател, знаменател и период. Сравнявай видеа, сходни по дължина и тема; отбелязвай бюджет, сезон и различна аудитория. Спадът в задържането показва къде да провериш кадъра, но не обяснява сам по себе си защо зрителят е напуснал.\n\nКритерий за приемане: Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн.\n\nКогато пробата се провали:\nСимптом: Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината.\nКорекция: Запази бележките за условието, дата, бюджет и линк.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Планирай как ще научиш от резултата“?","options":[{"id":"a","label":"Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината."},{"id":"b","label":"Формулирай какво ще провериш след публикация и какъв резултат би променил следващата версия."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Формулирай какво ще провериш след публикация и какъв резултат би променил следващата версия. Анализът е полезен само ако сравнява правилния момент и не превръща съвпадението в причина. Слабият ход е: Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината. Разпределението на показванията е различно. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Хипотеза: краткият кадър как инструкторът изправя формата ще задържи повече хора до обяснението. Версиите се различават само в първите три секунди; основен показател е задържането до 10-та секунда, вторичен — посещенията на графика. Сравняваш сходен период, но отбелязваш, че промоция в същия ден може да е повлияла.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Запази бележките за условието, дата, бюджет и линк."},{"id":"b","label":"Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Запази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“. Грешният път — Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината. — оставя риска нерешен. Провери и границата: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Планирай как ще научиш от резултата“?","options":[{"id":"a","label":"При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител."},{"id":"b","label":"Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Формулирай какво ще провериш след публикация и какъв резултат би променил следващата версия. Анализът е полезен само ако сравнява правилния момент и не превръща съвпадението в причина.","Първо: Запиши хипотезата и една промяна, която ще тестваш. После: Определи показателя, знаменател, период и източник преди публикация.","Следи за грешния ход: Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.","items":[{"id":"s3","text":"Сравни с релевантен базов клип и отбележи външни промени."},{"id":"s4","text":"Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн."},{"id":"s2","text":"Определи показателя, знаменател, период и източник преди публикация."},{"id":"s1","text":"Запиши хипотезата и една промяна, която ще тестваш."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Запази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“. При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Хипотеза: краткият кадър как инструкторът изправя формата ще задържи повече хора до обяснението.\n\nПроменено условие: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"b","label":"Запази бележките за условието, дата, бюджет и линк."},{"id":"a","label":"Публикуваш версия B след платено разпространение, виждаш повече гледания и заключаваш, че новото начало е причината."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Запази бележките за условието, дата, бюджет и линк. На YouTube прегледай отчетите за задържане и ключовите моменти, после провери самия кадър при спад; не приемай кривата като отговор на въпроса „защо“. Границата тук е: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.\n\nПри следващия сигнал сравни същия канал и период с изходната точка. Ако новият източник противоречи на първия, провери дали се е променило поведение, аудитория или условията, преди да смениш извод.\n\nПоследен тест: ако колега не може да намери източника или да повтори периода, остави изводът като предположение. Не представяй извадка от разговори като представителна статистика.\n\nКарта за работа — Планирай как ще научиш от резултата\n1. Запиши хипотезата и една промяна, която ще тестваш.\n2. Определи показателя, знаменател, период и източник преди публикация.\n3. Сравни с релевантен базов клип и отбележи външни промени.\n4. Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Audience retention and engagement: https://support.google.com/youtube/answer/9313698?hl=en (провери актуалната версия преди публикуване)."},"required":false,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-24","title":"Събери брифа и плана за производство","objective":"да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа","hook":"Първият модул има стойност, когато идеята вече е достатъчно ясна за следващата стъпка.","subtitle":"От наблюдение до снимаем план","estimated_minutes":26,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Първият модул има стойност, когато идеята вече е достатъчно ясна за следващата стъпка.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Предай проект, по който сценаристът и снимачният екип могат да започнат работа без да гадаят какво е обещано, какво е доказано и кой трябва да реши."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Пакетът за предаване събира одобрен бриф, сценарий или сценарните части, списък на кадрите, доказателства и източници, разрешения, формат за доставка, срокове, контакт за одобрение и резервен план. За всяко неизвестно посочи собственик и дата; не го скривай между бележките.\n\nГраница на правилото: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Събери последната одобрена версия на брифа и посланието.\n2. Прикачи списък с кадри, места, хора, реквизит, права и тестове.\n3. Напиши изискванията за предаване и критерии за приемане по канала.\n4. Маркирай зависимостите, неизвестните и следващия отговорник.\n\nСтоп-сигнал: Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст. Монтажистът не знае кой вариант е одобрен. Ако това се случи, приложи корекцията преди да продължиш: Използвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Екипът получава кратък бриф за видео за начинаещи, кадри за колелото и материалите, потвърдените условия за курса, формата 9:16, субтитри, линк към актуалния график и съгласие от инструктора. Наличността за следващата събота все още не е потвърдена, затова видеото не я обещава и линкът води към динамичния график.\n\nРешение в този случай:\nИзползвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия.\n\nГраница на извода:\nНе предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст. Монтажистът не знае кой вариант е одобрен."},"after":{"label":"По-доброто решение","text":"Използвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия.\n\nПреди да продължиш: Маркирай зависимостите, неизвестните и следващия отговорник."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"При предаване заключи папката с една одобрена версия, източници, права, списък с кадри и критерии за приемане. Използвай последователно име на проект, дата и версия; не записвай върху оригиналните файлове. Получателят трябва да знае какво е окончателно, какво е само справка и кого да потърси при промяна.\n\nКритерий за приемане: Маркирай зависимостите, неизвестните и следващия отговорник.\n\nКогато пробата се провали:\nСимптом: Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст.\nКорекция: Използвай един номер на версията и контролен списък за приети материали.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.\n\nАртефакт за брифа: запази точния сигнал, източника, датата и неизвестното; вържи извода към канала и периода. Повтори проверката, ако се смени каналът, аудиторията, периодът или показателят; изводът важи само за условията, при които е събран сигналът."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Събери брифа и плана за производство“?","options":[{"id":"a","label":"Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст."},{"id":"b","label":"Предай проект, по който сценаристът и снимачният екип могат да започнат работа без да гадаят какво е обещано, какво е доказано и кой трябва да реши."},{"id":"c","label":"Една публикация доказва сама по себе си защо продажбите са се променили."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Предай проект, по който сценаристът и снимачният екип могат да започнат работа без да гадаят какво е обещано, какво е доказано и кой трябва да реши. Слабият ход е: Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст. Монтажистът не знае кой вариант е одобрен. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Екипът получава кратък бриф за видео за начинаещи, кадри за колелото и материалите, потвърдените условия за курса, формата 9:16, субтитри, линк към актуалния график и съгласие от инструктора. Наличността за следващата събота все още не е потвърдена, затова видеото не я обещава и линкът води към динамичния график.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използвай един номер на версията и контролен списък за приети материали."},{"id":"b","label":"Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст."},{"id":"c","label":"Продължи към снимането, без да записваш източника и датата на наблюдението."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия. Грешният път — Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст. — оставя риска нерешен. Провери и границата: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Събери брифа и плана за производство“?","options":[{"id":"a","label":"Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка."},{"id":"b","label":"Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Предай проект, по който сценаристът и снимачният екип могат да започнат работа без да гадаят какво е обещано, какво е доказано и кой трябва да реши.","Първо: Събери последната одобрена версия на брифа и посланието. После: Прикачи списък с кадри, места, хора, реквизит, права и тестове.","Следи за грешния ход: Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст."],"nextStep":"Към своя проект приложи това върху последния реален сигнал; сравни дата и канал с изходната точка, а неизвестното остави за проверка. Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.","items":[{"id":"s1","text":"Събери последната одобрена версия на брифа и посланието."},{"id":"s4","text":"Маркирай зависимостите, неизвестните и следващия отговорник."},{"id":"s3","text":"Напиши изискванията за предаване и критерии за приемане по канала."},{"id":"s2","text":"Прикачи списък с кадри, места, хора, реквизит, права и тестове."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия. Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Екипът получава кратък бриф за видео за начинаещи, кадри за колелото и материалите, потвърдените условия за курса, формата 9:16, субтитри, линк към актуалния график и съгласие от инструктора.\n\nПроменено условие: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Предаването е папка „финално_ново2“ с различни сценарии и непотвърден текст."},{"id":"b","label":"Избери тема по личен вкус и обяви съвпадението след това като доказателство."},{"id":"c","label":"Използвай един номер на версията и контролен списък за приети материали."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай един номер на версията и контролен списък за приети материали. Отбележи, кой има право да одобрява и как връщате промяна, за да не се разминават изпратеният файл и текущите условия. Границата тук е: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.\n\nПреди предаване: съвпадат ли дата и период; можеш ли да посочиш първоизточника; маркирано ли е неизвестното; има ли разрешение за всеки човек и актив?\n\nКарта за работа — Събери брифа и плана за производство\n1. Събери последната одобрена версия на брифа и посланието.\n2. Прикачи списък с кадри, места, хора, реквизит, права и тестове.\n3. Напиши изискванията за предаване и критерии за приемане по канала.\n4. Маркирай зависимостите, неизвестните и следващия отговорник.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-01","title":"Остави на видеото една ясна работа","objective":"да сведеш сценария до една промяна, която зрителят трябва да разбере или направи","hook":"Сценарият става мъгляв, когато едновременно обяснява продукта, историята на бранда и всички услуги.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сведеш сценария до една промяна, която зрителят трябва да разбере или направи. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Сценарият става мъгляв, когато едновременно обяснява продукта, историята на бранда и всички услуги.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Остави на видеото една основна работа. Когато сценарият се опитва едновременно да обяснява услугата, разказва историята на марката, продава пакет и учи цялата професия, зрителят трудно разбира кое да запомни."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Преди да пишеш реплики, довърши изречението: „След това видео човекът ще може да…“. Избери действие или конкретно разбиране. Всяка сцена, графика и изречение трябва да помага за него; иначе е кандидат за съкращаване. Една основна цел не забранява емоция — тя дава причина на емоцията.\n\nГраница на правилото: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Вземи целта и зрителя от одобрения бриф.\n2. Напиши едно наблюдаемо завършване на изречението „след видеото…“.\n3. Провери всяка желана сцена спрямо целта и доказателството.\n4. Изнеси второстепенните теми в следващо видео или описание.\n\nСтоп-сигнал: Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди. Всеки фрагмент е разумен отделно, но заедно размиват задачата. Ако това се случи, приложи корекцията преди да продължиш: Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Брифът на ателието цели да помогне на начинаещ да разбере как протича първият урок. Сценарият не разказва цялата история на керамиката и не продава пет вида курс. Той показва входа, подготвеното работно място, инструктора, който демонстрира първото движение, и къде да се видят датите.\n\nРешение в този случай:\nНаправи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии.\n\nГраница на извода:\nЕдна цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди. Всеки фрагмент е разумен отделно, но заедно размиват задачата."},"after":{"label":"По-доброто решение","text":"Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии.\n\nПреди да продължиш: Изнеси второстепенните теми в следващо видео или описание."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Напиши едно проверимо изречение за това какво зрителят трябва да разбере или направи. После прегледай всяка сцена: ако тя не подготвя, доказва или довършва това изречение, изнеси я в друг материал. Това не забранява емоция; то не позволява на емоцията да замести работата на видеото.\n\nКритерий за приемане: Изнеси второстепенните теми в следващо видео или описание.\n\nКогато пробата се провали:\nСимптом: Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди.\nКорекция: Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Остави на видеото една ясна работа“?","options":[{"id":"a","label":"Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Остави на видеото една основна работа."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Остави на видеото една основна работа. Когато сценарият се опитва едновременно да обяснява услугата, разказва историята на марката, продава пакет и учи цялата професия, зрителят трудно разбира кое да запомни. Слабият ход е: Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди. Всеки фрагмент е разумен отделно, но заедно размиват задачата. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Брифът на ателието цели да помогне на начинаещ да разбере как протича първият урок. Сценарият не разказва цялата история на керамиката и не продава пет вида курс. Той показва входа, подготвеното работно място, инструктора, който демонстрира първото движение, и къде да се видят датите.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии. Грешният път — Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди. — оставя риска нерешен. Провери и границата: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Остави на видеото една ясна работа“?","options":[{"id":"a","label":"Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди."},{"id":"b","label":"Една цел за видеото не означава, че бизнесът има само един показател."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Остави на видеото една основна работа. Когато сценарият се опитва едновременно да обяснява услугата, разказва историята на марката, продава пакет и учи цялата професия, зрителят трудно разбира кое да запомни.","Първо: Вземи целта и зрителя от одобрения бриф. После: Напиши едно наблюдаемо завършване на изречението „след видеото…“.","Следи за грешния ход: Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.","items":[{"id":"s1","text":"Вземи целта и зрителя от одобрения бриф."},{"id":"s3","text":"Провери всяка желана сцена спрямо целта и доказателството."},{"id":"s4","text":"Изнеси второстепенните теми в следващо видео или описание."},{"id":"s2","text":"Напиши едно наблюдаемо завършване на изречението „след видеото…“."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии. Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Брифът на ателието цели да помогне на начинаещ да разбере как протича първият урок.\n\nПроменено условие: Една цел за видеото не означава, че бизнесът има само един показател.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава."},{"id":"b","label":"Добавяш интервю с основателката, списък на всички изделия, ценова таблица и три призива в 45 секунди."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи тест с един човек: след гледане помоли го да избере кое твърдение видеото защитава. Ако получиш три различни отговора, върни се към главната работа и махни конкуриращите се линии. Границата тук е: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.\n\nКарта за работа — Остави на видеото една ясна работа\n1. Вземи целта и зрителя от одобрения бриф.\n2. Напиши едно наблюдаемо завършване на изречението „след видеото…“.\n3. Провери всяка желана сцена спрямо целта и доказателството.\n4. Изнеси второстепенните теми в следващо видео или описание.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-02","title":"Намери гледната точка преди първия ред","objective":"да превърнеш темата от брифа в конкретна гледна точка за сценария","hook":"Две видеа могат да говорят за една тема, но едното да е полезно, а другото — общо.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш темата от брифа в конкретна гледна точка за сценария. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Две видеа могат да говорят за една тема, но едното да е полезно, а другото — общо.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Намери гледната точка, преди да пишеш първия ред. Темата казва за какво е клипът; гледната точка казва какво точно ще научи зрителят от този клип."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Избери между контраст, процес, решение, грешка, сравнение или конкретен въпрос. Гледната точка трябва да е достатъчно тясна за едно видео, но достатъчно богата за доказателство и развой. Провери я спрямо брифа: нова ли е за тази аудитория, вярна ли е и можеш ли да я покажеш?\n\nГраница на правилото: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши темата без рекламно заглавие.\n2. Избери конкретния въпрос или погрешно очакване на зрителя.\n3. Напиши гледната точка в едно изречение, без да обещаваш прекалено.\n4. Провери дали има кадър, факт или демонстрация, които я доказват.\n\nСтоп-сигнал: Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения. Звучи силно, но не може да замести наблюдаемата полза. Ако това се случи, приложи корекцията преди да продължиш: Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Тема: първо занятие по керамика. Гледна точка: „Първите минути не започват с готова чаша — започват с това да усетиш колко мека е глината.“ Това дава планове на ръцете и обяснение от инструктора, а не пореден клип с готови изделия.\n\nРешение в този случай:\nНапиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно.\n\nГраница на извода:\nГледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения. Звучи силно, но не може да замести наблюдаемата полза."},"after":{"label":"По-доброто решение","text":"Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно.\n\nПреди да продължиш: Провери дали има кадър, факт или демонстрация, които я доказват."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Раздели темата, гледната точка и хипотезата. „Глина“ е тема; „първото движение е по-лесно, когато центрираш преди да натиснеш“ е гледна точка; „новакът ще задържи вниманието, ако види ръцете отблизо“ е хипотеза. Избери хипотеза, която можеш да покажеш или провериш, а не само да заявиш.\n\nКритерий за приемане: Провери дали има кадър, факт или демонстрация, които я доказват.\n\nКогато пробата се провали:\nСимптом: Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения.\nКорекция: Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна?\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Намери гледната точка преди първия ред“?","options":[{"id":"a","label":"Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Намери гледната точка, преди да пишеш първия ред."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Намери гледната точка, преди да пишеш първия ред. Темата казва за какво е клипът; гледната точка казва какво точно ще научи зрителят от този клип. Слабият ход е: Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения. Звучи силно, но не може да замести наблюдаемата полза. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Тема: първо занятие по керамика. Гледна точка: „Първите минути не започват с готова чаша — започват с това да усетиш колко мека е глината.“ Това дава планове на ръцете и обяснение от инструктора, а не пореден клип с готови изделия.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна?"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно. Грешният път — Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения. — оставя риска нерешен. Провери и границата: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Намери гледната точка преди първия ред“?","options":[{"id":"a","label":"Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения."},{"id":"b","label":"Гледната точка може да се промени, когато ново наблюдение опровергае предположението."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Намери гледната точка, преди да пишеш първия ред. Темата казва за какво е клипът; гледната точка казва какво точно ще научи зрителят от този клип.","Първо: Запиши темата без рекламно заглавие. После: Избери конкретния въпрос или погрешно очакване на зрителя.","Следи за грешния ход: Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.","items":[{"id":"s2","text":"Избери конкретния въпрос или погрешно очакване на зрителя."},{"id":"s1","text":"Запиши темата без рекламно заглавие."},{"id":"s4","text":"Провери дали има кадър, факт или демонстрация, които я доказват."},{"id":"s3","text":"Напиши гледната точка в едно изречение, без да обещаваш прекалено."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно. Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Тема: първо занятие по керамика.\n\nПроменено условие: Гледната точка може да се промени, когато ново наблюдение опровергае предположението.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна?"},{"id":"a","label":"Пишеш „Керамиката е терапия“ като централна теза без доказателство или подходящи ограничения."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Напиши три различни гледни точки и провери всяка с въпрос: какво ново научава човекът, как ще го види и каква реплика трябва да бъде вярна? Избери варианта с най-добро съвпадение, не най-силното прилагателно. Границата тук е: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.\n\nКарта за работа — Намери гледната точка преди първия ред\n1. Запиши темата без рекламно заглавие.\n2. Избери конкретния въпрос или погрешно очакване на зрителя.\n3. Напиши гледната точка в едно изречение, без да обещаваш прекалено.\n4. Провери дали има кадър, факт или демонстрация, които я доказват.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-03","title":"Напиши хук, който изпълнява обещанието","objective":"да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава","hook":"Зрителят губи доверие, когато началото обещава „тайна“, а след това получава общ съвет.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Зрителят губи доверие, когато началото обещава „тайна“, а след това получава общ съвет.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Началната реплика или първият кадър трябва да съответства на обещанието и да отвори въпрос, на който видеото действително отговаря."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Полезният хук започва с конкретна сцена, проблем, резултат или въпрос. Той не е отделна реклама, която трябва после да бъде „изплатена“ с несвързан материал. Запиши първите секунди с образ, реплика, надпис и звук; после провери дали останалото видео изпълнява очакването.\n\nГраница на правилото: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови обещанието, което зрителят ще чуе или види.\n2. Избери кадър/реплика, който показва същия проблем или резултат.\n3. Премахни общите уводи и неподкрепените твърдения.\n4. Провери дали следващите сцени дават отговор, а не сменят темата.\n\nСтоп-сигнал: „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок. Хукът привлича с едно, материалът носи друго. Ако това се случи, приложи корекцията преди да продължиш: Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Преди: „Здравейте, днес ще ви покажем нашето ателие.“ След: близък кадър на ръце, които центрират глината, и реплика: „Не натискай по-силно — първо намери центъра.“ Следващата сцена показва как инструкторът го намира. Образът, думите и действието са едно обещание.\n\nРешение в този случай:\nНаправи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана.\n\nГраница на извода:\nЛюбопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"„Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок. Хукът привлича с едно, материалът носи друго."},"after":{"label":"По-доброто решение","text":"Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана.\n\nПреди да продължиш: Провери дали следващите сцени дават отговор, а не сменят темата."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Провери хука по обещание и изплащане: какво вижда човекът в първите секунди, какъв въпрос възниква и къде видеото отговаря? Не дръж отговора изкуствено до края. Ако хукът обещава резултат, покажи резултата или назови условието, което още трябва да се изпълни.\n\nКритерий за приемане: Провери дали следващите сцени дават отговор, а не сменят темата.\n\nКогато пробата се провали:\nСимптом: „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок.\nКорекция: Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Напиши хук, който изпълнява обещанието“?","options":[{"id":"a","label":"„Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок."},{"id":"b","label":"Началната реплика или първият кадър трябва да съответства на обещанието и да отвори въпрос, на който видеото действително отговаря."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Началната реплика или първият кадър трябва да съответства на обещанието и да отвори въпрос, на който видеото действително отговаря. Слабият ход е: „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок. Хукът привлича с едно, материалът носи друго. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Преди: „Здравейте, днес ще ви покажем нашето ателие.“ След: близък кадър на ръце, които центрират глината, и реплика: „Не натискай по-силно — първо намери центъра.“ Следващата сцена показва как инструкторът го намира. Образът, думите и действието са едно обещание.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава."},{"id":"b","label":"„Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана. Грешният път — „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок. — оставя риска нерешен. Провери и границата: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Напиши хук, който изпълнява обещанието“?","options":[{"id":"a","label":"„Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Началната реплика или първият кадър трябва да съответства на обещанието и да отвори въпрос, на който видеото действително отговаря.","Първо: Назови обещанието, което зрителят ще чуе или види. После: Избери кадър/реплика, който показва същия проблем или резултат.","Следи за грешния ход: „Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.","items":[{"id":"s3","text":"Премахни общите уводи и неподкрепените твърдения."},{"id":"s2","text":"Избери кадър/реплика, който показва същия проблем или резултат."},{"id":"s1","text":"Назови обещанието, което зрителят ще чуе или види."},{"id":"s4","text":"Провери дали следващите сцени дават отговор, а не сменят темата."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана. Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Преди: „Здравейте, днес ще ви покажем нашето ателие.“ След: близък кадър на ръце, които центрират глината, и реплика: „Не натискай по-силно — първо намери центъра.“ Следващата сцена показва как инструкторът го намира.\n\nПроменено условие: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"„Най-лесният начин да станеш майстор!“ преувеличава резултата, а видеото само показва първи урок."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи проверка „хук–доказателство“: подчертавай глаголите в първия ред и посочи кадъра, който ги потвърждава. Ако такъв кадър няма, сменяй текста или плана. Границата тук е: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nКарта за работа — Напиши хук, който изпълнява обещанието\n1. Назови обещанието, което зрителят ще чуе или види.\n2. Избери кадър/реплика, който показва същия проблем или резултат.\n3. Премахни общите уводи и неподкрепените твърдения.\n4. Провери дали следващите сцени дават отговор, а не сменят темата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-04","title":"Започни с действие, образ или реплика","objective":"да избираш начин на отваряне според това каква информация може да се покаже най-рано","hook":"Понякога първият кадър е достатъчно ясен; понякога зрителят има нужда от едно изречение контекст.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш начин на отваряне според това каква информация може да се покаже най-рано. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Понякога първият кадър е достатъчно ясен; понякога зрителят има нужда от едно изречение контекст.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избери как започва видеото според информацията, която можеш да покажеш веднага. Началният образ може да е действие, лице, резултат, детайл или текст — формата е подчинена на смисъла."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Първият кадър задава въпрос без думи: какво виждам, защо ми е важно и къде да гледам? Ако действието не се разпознава на малък екран, намали шумния фон и направи главния обект четим. Не е задължително монтажът да е бърз; важно е всяка ранна секунда да дава нова информация.\n\nГраница на правилото: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери визуален знак, който се разбира без предварителен контекст.\n2. Определи къде е погледът и какво се движи в кадъра.\n3. Добави само нужния надпис или звук, за да се разчете действието.\n4. Провери първия кадър без звук и на малък екран.\n\nСтоп-сигнал: Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата. Брандът заема време, но не обяснява ползата. Ако това се случи, приложи корекцията преди да продължиш: Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Видеото започва с широк план на празно ателие, но зрителят не разбира кое да гледа. Версията с близък план на глината, която се деформира от прекомерен натиск, веднага показва проблема. Следва кадър с по-лек натиск. Ако темата не е грешка, можеш да започнеш с човека, който задава истинския въпрос.\n\nРешение в този случай:\nСравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява.\n\nГраница на извода:\nКадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата. Брандът заема време, но не обяснява ползата."},"after":{"label":"По-доброто решение","text":"Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява.\n\nПреди да продължиш: Провери първия кадър без звук и на малък екран."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Първият образ може да започне с действие, завършен предмет или проблем, но нека зрителят веднага разбере връзката с темата. Заглавие, надпис и първи кадър не трябва да дават три различни обещания. Провери началото без звук и само със звук, защото и двете версии могат да стигнат до публика.\n\nКритерий за приемане: Провери първия кадър без звук и на малък екран.\n\nКогато пробата се провали:\nСимптом: Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата.\nКорекция: Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне?\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Започни с действие, образ или реплика“?","options":[{"id":"a","label":"Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата."},{"id":"b","label":"Избери как започва видеото според информацията, която можеш да покажеш веднага."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Избери как започва видеото според информацията, която можеш да покажеш веднага. Началният образ може да е действие, лице, резултат, детайл или текст — формата е подчинена на смисъла. Слабият ход е: Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата. Брандът заема време, но не обяснява ползата. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Видеото започва с широк план на празно ателие, но зрителят не разбира кое да гледа. Версията с близък план на глината, която се деформира от прекомерен натиск, веднага показва проблема. Следва кадър с по-лек натиск. Ако темата не е грешка, можеш да започнеш с човека, който задава истинския въпрос.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне?"},{"id":"b","label":"Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява. Грешният път — Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата. — оставя риска нерешен. Провери и границата: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Започни с действие, образ или реплика“?","options":[{"id":"a","label":"Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избери как започва видеото според информацията, която можеш да покажеш веднага. Началният образ може да е действие, лице, резултат, детайл или текст — формата е подчинена на смисъла.","Първо: Избери визуален знак, който се разбира без предварителен контекст. После: Определи къде е погледът и какво се движи в кадъра.","Следи за грешния ход: Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.","items":[{"id":"s3","text":"Добави само нужния надпис или звук, за да се разчете действието."},{"id":"s4","text":"Провери първия кадър без звук и на малък екран."},{"id":"s2","text":"Определи къде е погледът и какво се движи в кадъра."},{"id":"s1","text":"Избери визуален знак, който се разбира без предварителен контекст."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява. Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Видеото започва с широк план на празно ателие, но зрителят не разбира кое да гледа.\n\nПроменено условие: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне?"},{"id":"b","label":"Поставяш лого, анимация и надпис в първите пет секунди, преди зрителят да види темата."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Сравни първия кадър с целта: показва ли той действие, контекст или резултат, който ще се разгърне? Махни елемент, ако той само украсява. Границата тук е: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.\n\nКарта за работа — Започни с действие, образ или реплика\n1. Избери визуален знак, който се разбира без предварителен контекст.\n2. Определи къде е погледът и какво се движи в кадъра.\n3. Добави само нужния надпис или звук, за да се разчете действието.\n4. Провери първия кадър без звук и на малък екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-05","title":"Подреди сценария на ясни части","objective":"да изградиш последователност от контекст, напрежение, избор и резултат","hook":"Силен hook не спасява сценарий, който не знае накъде отива.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да изградиш последователност от контекст, напрежение, избор и резултат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Силен hook не спасява сценарий, който не знае накъде отива.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подреди сценария в части, които изпълняват отделни задачи: ориентират, поставят въпрос, показват решение и оставят зрителя с подходяща следваща стъпка.\n\nСценарият е ред от въпроси на зрителя. Всяка сцена трябва да добавя контекст, действие, доказателство или последствие; реплика без визуална опора често остава недоказана."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Структурата е причинно-следствена, не просто шаблон за попълване. Всяка част трябва да променя разбирането: нов факт, избор, препятствие или последствие. В кратко видео някои части могат да се слеят, но редът на нужната информация трябва да остане ясен.\n\nГраница на правилото: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Отбележи обещанието и въпроса, който ще бъде отговорен.\n2. Подреди необходимия контекст преди стъпката, която зависи от него.\n3. Постави доказателството след твърдението, но достатъчно рано за проверка.\n4. Завърши с резултат и призив за действие, който продължава темата.\n\nСтоп-сигнал: Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът. Редът изисква зрителят да пази неважна информация, преди да види причината. Ако това се случи, приложи корекцията преди да продължиш: Създай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Сценарий за начинаещ: 1) виж какво ще правиш; 2) въпрос „ще се справя ли?“; 3) кратък контекст за първото движение; 4) инструктор показва натиск; 5) вижда се оформена начална стена; 6) линк към датите и включените материали. Редът помага зрителят да разбере причината за всяка стъпка.\n\nРешение в този случай:\nСъздай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео.\n\nГраница на извода:\nНе налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът. Редът изисква зрителят да пази неважна информация, преди да види причината."},"after":{"label":"По-доброто решение","text":"Създай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео.\n\nПреди да продължиш: Завърши с резултат и призив за действие, който продължава темата."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Използвай структура като работен план, не като формула: контекст, въпрос, действие, доказателство, резултат и следващ ход. Ако зрителят вече знае контекста, съкрати го; ако действието е непознато, покажи го преди да обясниш изключенията. Всяка част трябва да променя разбирането, иначе тя е повторение.\n\nКритерий за приемане: Завърши с резултат и призив за действие, който продължава темата.\n\nКогато пробата се провали:\nСимптом: Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът.\nКорекция: Създай план на сцените с функция и въпрос за всяка.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подреди сценария на ясни части“?","options":[{"id":"a","label":"Подреди сценария в части, които изпълняват отделни задачи: ориентират, поставят въпрос, показват решение и оставят зрителя с подходяща следваща стъпка."},{"id":"b","label":"Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Подреди сценария в части, които изпълняват отделни задачи: ориентират, поставят въпрос, показват решение и оставят зрителя с подходяща следваща стъпка. Слабият ход е: Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът. Редът изисква зрителят да пази неважна информация, преди да види причината. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Сценарий за начинаещ: 1) виж какво ще правиш; 2) въпрос „ще се справя ли?“; 3) кратък контекст за първото движение; 4) инструктор показва натиск; 5) вижда се оформена начална стена; 6) линк към датите и включените материали. Редът помага зрителят да разбере причината за всяка стъпка.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът."},{"id":"b","label":"Създай план на сцените с функция и въпрос за всяка."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Създай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео. Грешният път — Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът. — оставя риска нерешен. Провери и границата: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подреди сценария на ясни части“?","options":[{"id":"a","label":"Не налагай механично триактен разказ на всяка демонстрация."},{"id":"b","label":"Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подреди сценария в части, които изпълняват отделни задачи: ориентират, поставят въпрос, показват решение и оставят зрителя с подходяща следваща стъпка.","Първо: Отбележи обещанието и въпроса, който ще бъде отговорен. После: Подреди необходимия контекст преди стъпката, която зависи от него.","Следи за грешния ход: Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.","items":[{"id":"s1","text":"Отбележи обещанието и въпроса, който ще бъде отговорен."},{"id":"s4","text":"Завърши с резултат и призив за действие, който продължава темата."},{"id":"s3","text":"Постави доказателството след твърдението, но достатъчно рано за проверка."},{"id":"s2","text":"Подреди необходимия контекст преди стъпката, която зависи от него."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Създай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео. Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Сценарий за начинаещ: 1) виж какво ще правиш; 2) въпрос „ще се справя ли?“; 3) кратък контекст за първото движение; 4) инструктор показва натиск; 5) вижда се оформена начална стена; 6) линк към датите и включените материали.\n\nПроменено условие: Не налагай механично триактен разказ на всяка демонстрация.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Създай план на сцените с функция и въпрос за всяка."},{"id":"a","label":"Започваш с подробности за историята на ателието, после показваш неуспешен резултат, а чак в края казваш за кого е курсът."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Създай план на сцените с функция и въпрос за всяка. Ако сцена не променя знание, очакване или емоция, провери дали тя принадлежи на това видео. Границата тук е: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.\n\nКарта за работа — Подреди сценария на ясни части\n1. Отбележи обещанието и въпроса, който ще бъде отговорен.\n2. Подреди необходимия контекст преди стъпката, която зависи от него.\n3. Постави доказателството след твърдението, но достатъчно рано за проверка.\n4. Завърши с резултат и призив за действие, който продължава темата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-06","title":"Създай напрежение без да подвеждаш","objective":"да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата","hook":"Празната интрига задържа секунда, но разрушава доверието, ако отговорът е дребен или липсва.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Празната интрига задържа секунда, но разрушава доверието, ако отговорът е дребен или липсва.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Поддържай интерес чрез истински въпрос, препятствие и разрешение, които произтичат от темата. Напрежението е разликата между цел и пречка, а не преувеличен конфликт."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Зрителят остава, когато разбира залога и иска да види какво ще се случи. Направи препятствието конкретно и справедливо: ограничено време, объркващ избор, неуспешна първа стъпка. Не измисляй риск, който услугата не носи, и не унижавай начинаещия заради грешка.\n\nГраница на правилото: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови какво иска човекът в тази сцена.\n2. Определи реалната пречка, която може да се види или обясни.\n3. Покажи опит, обратна връзка и последствие.\n4. Провери, че разрешението е честно и не обещава еднакъв резултат за всички.\n\nСтоп-сигнал: Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка. Ако това се случи, приложи корекцията преди да продължиш: Провери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Участникът иска да направи стените на малка чаша, но глината се накланя. Инструкторът не казва „всички го правят грешно“; той показва къде центърът се губи и как ръцете го връщат. Напрежението идва от реалния въпрос „ще удържа ли формата?“, а разрешението е демонстрация, не магическа трансформация.\n\nРешение в този случай:\nПровери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх.\n\nГраница на извода:\nПри тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."},"after":{"label":"По-доброто решение","text":"Провери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх.\n\nПреди да продължиш: Провери, че разрешението е честно и не обещава еднакъв резултат за всички."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Напрежението идва от истинска разлика между цел и пречка. Покажи какво затруднява човека и какво се променя след решението, без да превръщаш обикновена стъпка в катастрофа. Пази достойнството на участниците: не снимай грешка, която човекът не е разрешил да използва.\n\nКритерий за приемане: Провери, че разрешението е честно и не обещава еднакъв резултат за всички.\n\nКогато пробата се провали:\nСимптом: Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка.\nКорекция: Провери всяка драматична дума с факт и снимков план.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Създай напрежение без да подвеждаш“?","options":[{"id":"a","label":"Поддържай интерес чрез истински въпрос, препятствие и разрешение, които произтичат от темата."},{"id":"b","label":"Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Поддържай интерес чрез истински въпрос, препятствие и разрешение, които произтичат от темата. Напрежението е разликата между цел и пречка, а не преувеличен конфликт. Слабият ход е: Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Участникът иска да направи стените на малка чаша, но глината се накланя. Инструкторът не казва „всички го правят грешно“; той показва къде центърът се губи и как ръцете го връщат. Напрежението идва от реалния въпрос „ще удържа ли формата?“, а разрешението е демонстрация, не магическа трансформация.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."},{"id":"b","label":"Провери всяка драматична дума с факт и снимков план."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Провери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх. Грешният път — Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка. — оставя риска нерешен. Провери и границата: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Създай напрежение без да подвеждаш“?","options":[{"id":"a","label":"При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон."},{"id":"b","label":"Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Поддържай интерес чрез истински въпрос, препятствие и разрешение, които произтичат от темата. Напрежението е разликата между цел и пречка, а не преувеличен конфликт.","Първо: Назови какво иска човекът в тази сцена. После: Определи реалната пречка, която може да се види или обясни.","Следи за грешния ход: Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.","items":[{"id":"s2","text":"Определи реалната пречка, която може да се види или обясни."},{"id":"s4","text":"Провери, че разрешението е честно и не обещава еднакъв резултат за всички."},{"id":"s1","text":"Назови какво иска човекът в тази сцена."},{"id":"s3","text":"Покажи опит, обратна връзка и последствие."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Провери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх. При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Участникът иска да направи стените на малка чаша, но глината се накланя.\n\nПроменено условие: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Добавяш фалшиво обратно броене и реплика „това може да съсипе целия ти живот“ за дребна производствена грешка."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Провери всяка драматична дума с факт и снимков план."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Провери всяка драматична дума с факт и снимков план. Ако рискът е малък, покажи го като малък; честната конкретност е по-убедителна от шумния страх. Границата тук е: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nКарта за работа — Създай напрежение без да подвеждаш\n1. Назови какво иска човекът в тази сцена.\n2. Определи реалната пречка, която може да се види или обясни.\n3. Покажи опит, обратна връзка и последствие.\n4. Провери, че разрешението е честно и не обещава еднакъв резултат за всички.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-07","title":"Дай новата информация в правилния ред","objective":"да подредиш информацията така, че зрителят да може да следва решението","hook":"Точният съвет може да изгуби смисъл, ако се появи преди зрителят да разбере проблема.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да подредиш информацията така, че зрителят да може да следва решението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Точният съвет може да изгуби смисъл, ако се появи преди зрителят да разбере проблема.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Давай информацията в реда, в който зрителят може да я използва. Първо установи контекст и думи; после добавяй изключения и подробности."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Работната памет е ограничена: термин без пример или три инструкции наведнъж лесно се губят. Разделяй процеса на видими стъпки, казвай името на обекта преди местоимението, повтаряй само критичната опора и показвай причината за реда. Монтажът може да съкрати паузи, но не причинно-следствената връзка.\n\nГраница на правилото: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Установи обекта и задачата преди да използваш „това“ или „така“.\n2. Дай само контекста, който е нужен за следващото действие.\n3. Показвай стъпките в логичен ред и оставяй време за ключовия детайл.\n4. Добави изключение след основния случай, не преди зрителят да го разбере.\n\nСтоп-сигнал: Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин. Видео е кратко, но усилието за разбиране е високо. Ако това се случи, приложи корекцията преди да продължиш: Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Инструкторът казва „изравни това“, докато кадърът показва три инструмента и две ръце. Зрителят не знае кой обект има предвид. Новият монтаж назовава глинения цилиндър, показва конкретния ръб и чак тогава въвежда инструмента. Един кратък надпис помага, без да повтаря цялата реплика.\n\nРешение в този случай:\nИзползвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част.\n\nГраница на извода:\nНе повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин. Видео е кратко, но усилието за разбиране е високо."},"after":{"label":"По-доброто решение","text":"Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част.\n\nПреди да продължиш: Добави изключение след основния случай, не преди зрителят да го разбере."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Дай една нова идея наведнъж. Назови предмета, покажи действието и после добави изключението. Ако термин е необходим, обясни го при първа употреба и използвай същата дума по-късно. Рязка смяна на понятията кара зрителя да превърта, вместо да проследи причината и следствието.\n\nКритерий за приемане: Добави изключение след основния случай, не преди зрителят да го разбере.\n\nКогато пробата се провали:\nСимптом: Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин.\nКорекция: Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Дай новата информация в правилния ред“?","options":[{"id":"a","label":"Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Давай информацията в реда, в който зрителят може да я използва."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Давай информацията в реда, в който зрителят може да я използва. Първо установи контекст и думи; после добавяй изключения и подробности. Слабият ход е: Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин. Видео е кратко, но усилието за разбиране е високо. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Инструкторът казва „изравни това“, докато кадърът показва три инструмента и две ръце. Зрителят не знае кой обект има предвид. Новият монтаж назовава глинения цилиндър, показва конкретния ръб и чак тогава въвежда инструмента. Един кратък надпис помага, без да повтаря цялата реплика.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част. Грешният път — Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин. — оставя риска нерешен. Провери и границата: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Дай новата информация в правилния ред“?","options":[{"id":"a","label":"Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин."},{"id":"b","label":"Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Давай информацията в реда, в който зрителят може да я използва. Първо установи контекст и думи; после добавяй изключения и подробности.","Първо: Установи обекта и задачата преди да използваш „това“ или „така“. После: Дай само контекста, който е нужен за следващото действие.","Следи за грешния ход: Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.","items":[{"id":"s1","text":"Установи обекта и задачата преди да използваш „това“ или „така“."},{"id":"s3","text":"Показвай стъпките в логичен ред и оставяй време за ключовия детайл."},{"id":"s2","text":"Дай само контекста, който е нужен за следващото действие."},{"id":"s4","text":"Добави изключение след основния случай, не преди зрителят да го разбере."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част. Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Инструкторът казва „изравни това“, докато кадърът показва три инструмента и две ръце.\n\nПроменено условие: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“."},{"id":"b","label":"Четири нови термина се появяват в първата секунда и всеки се обяснява с друг непознат термин."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай тест „може ли човек да повтори последната стъпка, преди да чуе следващата?“. Ако не, раздели изречението, смени кадъра или забави точно тази част. Границата тук е: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.\n\nКарта за работа — Дай новата информация в правилния ред\n1. Установи обекта и задачата преди да използваш „това“ или „така“.\n2. Дай само контекста, който е нужен за следващото действие.\n3. Показвай стъпките в логичен ред и оставяй време за ключовия детайл.\n4. Добави изключение след основния случай, не преди зрителят да го разбере.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-08","title":"Покажи процеса, вместо само да го твърдиш","objective":"да превърнеш обяснението в наблюдаема демонстрация","hook":"„Вярвай ми“ е слабо доказателство, когато можеш да покажеш действието.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш обяснението в наблюдаема демонстрация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Вярвай ми“ е слабо доказателство, когато можеш да покажеш действието.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Показвай процеса, вместо да изговаряш твърдение без образ. Зрителят трябва да види действието, критичния детайл и резултата, който следва от него."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Планирай демонстрация като доказателство: начално състояние, действие, видима промяна, проверка. Камерата трябва да показва причината — натиск, позиция, движение — а не само красивия край. Когато реалният процес е дълъг, обозначи пропуснатото време, за да не внушиш непрекъснатост.\n\nГраница на правилото: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Слагаш кадър на усмихната участничка върху реплика за техниката. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Раздели умението на видимо начално състояние и критично движение.\n2. Избери план, който не скрива инструмента, ръцете или посоката.\n3. Запиши поне един дубъл на действието и един на последствието.\n4. Съпостави репликата и кадъра; отбележи всеки монтажен скок.\n\nСтоп-сигнал: Слагаш кадър на усмихната участничка върху реплика за техниката. Положителната емоция е полезна за историята, но не доказва движението. Ако това се случи, приложи корекцията преди да продължиш: Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Реплика: „Центрирай глината.“ Това не показва как се разбира, че е центрирана. Камерата снима отгоре и встрани; инструкторът забавя колелото, докосва периферията и показва равномерното движение. После кадърът се връща на нормална скорост и се вижда стабилната форма.\n\nРешение в този случай:\nАко обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено.\n\nГраница на извода:\nНе редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Слагаш кадър на усмихната участничка върху реплика за техниката. Положителната емоция е полезна за историята, но не доказва движението."},"after":{"label":"По-доброто решение","text":"Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено.\n\nПреди да продължиш: Съпостави репликата и кадъра; отбележи всеки монтажен скок."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"При демонстрация подготви широк план за ориентация, близък за пръстите и повторен кадър за резултата. Не изрязвай критичния момент и не ускорявай така, че да стане невъзможно да се разбере техниката. Ако движението е прекалено бързо, заснеми отделен забавен кадър и го обозначи.\n\nКритерий за приемане: Съпостави репликата и кадъра; отбележи всеки монтажен скок.\n\nКогато пробата се провали:\nСимптом: Слагаш кадър на усмихната участничка върху реплика за техниката.\nКорекция: Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Покажи процеса, вместо само да го твърдиш“?","options":[{"id":"a","label":"Слагаш кадър на усмихната участничка върху реплика за техниката."},{"id":"b","label":"Показвай процеса, вместо да изговаряш твърдение без образ."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Показвай процеса, вместо да изговаряш твърдение без образ. Зрителят трябва да види действието, критичния детайл и резултата, който следва от него. Слабият ход е: Слагаш кадър на усмихната участничка върху реплика за техниката. Положителната емоция е полезна за историята, но не доказва движението. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Реплика: „Центрирай глината.“ Това не показва как се разбира, че е центрирана. Камерата снима отгоре и встрани; инструкторът забавя колелото, докосва периферията и показва равномерното движение. После кадърът се връща на нормална скорост и се вижда стабилната форма.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Слагаш кадър на усмихната участничка върху реплика за техниката."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено. Грешният път — Слагаш кадър на усмихната участничка върху реплика за техниката. — оставя риска нерешен. Провери и границата: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Покажи процеса, вместо само да го твърдиш“?","options":[{"id":"a","label":"Слагаш кадър на усмихната участничка върху реплика за техниката."},{"id":"b","label":"Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Показвай процеса, вместо да изговаряш твърдение без образ. Зрителят трябва да види действието, критичния детайл и резултата, който следва от него.","Първо: Раздели умението на видимо начално състояние и критично движение. После: Избери план, който не скрива инструмента, ръцете или посоката.","Следи за грешния ход: Слагаш кадър на усмихната участничка върху реплика за техниката."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.","items":[{"id":"s2","text":"Избери план, който не скрива инструмента, ръцете или посоката."},{"id":"s4","text":"Съпостави репликата и кадъра; отбележи всеки монтажен скок."},{"id":"s3","text":"Запиши поне един дубъл на действието и един на последствието."},{"id":"s1","text":"Раздели умението на видимо начално състояние и критично движение."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено. Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Реплика: „Центрирай глината.“ Това не показва как се разбира, че е центрирана.\n\nПроменено условие: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено."},{"id":"a","label":"Слагаш кадър на усмихната участничка върху реплика за техниката."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Ако обяснението е твърде сложно за кадъра, използвай схема, повторение или замразяване на един момент, като ясно обозначиш кога е забавено. Границата тук е: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nКарта за работа — Покажи процеса, вместо само да го твърдиш\n1. Раздели умението на видимо начално състояние и критично движение.\n2. Избери план, който не скрива инструмента, ръцете или посоката.\n3. Запиши поне един дубъл на действието и един на последствието.\n4. Съпостави репликата и кадъра; отбележи всеки монтажен скок.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-09","title":"Подкрепи твърдението с проверимо доказателство","objective":"да използваш източник, пример или тест, който действително подкрепя твърдението","hook":"Увереният тон не замества доказателството — особено при числа, здраве, финанси и клиентски резултати.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш източник, пример или тест, който действително подкрепя твърдението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Увереният тон не замества доказателството — особено при числа, здраве, финанси и клиентски резултати.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подкрепяй фактите с източник, пример или тест, който действително доказва точното твърдение и не излиза извън неговите граници."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Различавай лично мнение, наблюдаван пример, вътрешни данни и външен източник. Провери автора, датата, методиката, обхвата и актуалността. Покажи източника четливо, но не прикривай ограниченията с дребен шрифт. Ако източникът казва „може“, не монтирай „ще“.\n\nГраница на правилото: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Маркирай всяко проверимо твърдение в текста.\n2. Провери първоизточник, дата и точни условия.\n3. Съпостави доказателството с формулировката и нужната аудитория.\n4. Покажи цитат/данни с контекст и отбележи връзката между тях.\n\nСтоп-сигнал: Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода. Картинката е убедителна, но доказателството не съвпада с твърдението. Ако това се случи, приложи корекцията преди да продължиш: Поддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"В клипа казваме, че курсът включва материалите. Офертата от текущия месец потвърждава глина и инструменти, но изпичането се таксува отделно. Надписът трябва да показва какво е включено и кое не е; кадърът с готов предмет не заменя условията.\n\nРешение в този случай:\nПоддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция.\n\nГраница на извода:\nКогато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода. Картинката е убедителна, но доказателството не съвпада с твърдението."},"after":{"label":"По-доброто решение","text":"Поддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция.\n\nПреди да продължиш: Покажи цитат/данни с контекст и отбележи връзката между тях."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Свери всяко число, суперлатив и обещание с източника преди запис. Запази дата и точната формулировка; ако източникът не покрива твърдението, намали обхвата му или го махни. В монтаж надписът и гласът трябва да казват едно и също. Не добавяй уверена реплика, за да прикриеш липса на доказателство.\n\nКритерий за приемане: Покажи цитат/данни с контекст и отбележи връзката между тях.\n\nКогато пробата се провали:\nСимптом: Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода.\nКорекция: Поддържай източник и дата в бележките към монтажа.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подкрепи твърдението с проверимо доказателство“?","options":[{"id":"a","label":"Подкрепяй фактите с източник, пример или тест, който действително доказва точното твърдение и не излиза извън неговите граници."},{"id":"b","label":"Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Подкрепяй фактите с източник, пример или тест, който действително доказва точното твърдение и не излиза извън неговите граници. Слабият ход е: Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода. Картинката е убедителна, но доказателството не съвпада с твърдението. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: В клипа казваме, че курсът включва материалите. Офертата от текущия месец потвърждава глина и инструменти, но изпичането се таксува отделно. Надписът трябва да показва какво е включено и кое не е; кадърът с готов предмет не заменя условията.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Поддържай източник и дата в бележките към монтажа."},{"id":"b","label":"Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Поддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция. Грешният път — Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода. — оставя риска нерешен. Провери и границата: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подкрепи твърдението с проверимо доказателство“?","options":[{"id":"a","label":"Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подкрепяй фактите с източник, пример или тест, който действително доказва точното твърдение и не излиза извън неговите граници.","Първо: Маркирай всяко проверимо твърдение в текста. После: Провери първоизточник, дата и точни условия.","Следи за грешния ход: Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.","items":[{"id":"s3","text":"Съпостави доказателството с формулировката и нужната аудитория."},{"id":"s4","text":"Покажи цитат/данни с контекст и отбележи връзката между тях."},{"id":"s1","text":"Маркирай всяко проверимо твърдение в текста."},{"id":"s2","text":"Провери първоизточник, дата и точни условия."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Поддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция. Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: В клипа казваме, че курсът включва материалите.\n\nПроменено условие: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използваш блог от преди пет години за текуща цена или изрязваш графика без оста и периода."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Поддържай източник и дата в бележките към монтажа."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Поддържай източник и дата в бележките към монтажа. Проверявай числа, отрицания, „винаги“, „всички“ и изключения отделно от останалата редакция. Границата тук е: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nКарта за работа — Подкрепи твърдението с проверимо доказателство\n1. Маркирай всяко проверимо твърдение в текста.\n2. Провери първоизточник, дата и точни условия.\n3. Съпостави доказателството с формулировката и нужната аудитория.\n4. Покажи цитат/данни с контекст и отбележи връзката между тях.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-10","title":"Обясни трудна идея с точен пример","objective":"да използваш аналогия или демонстрация, без тя да изкривява темата","hook":"Аналогията помага само ако прави понятие по-разбираемо и не създава нова заблуда.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш аналогия или демонстрация, без тя да изкривява темата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Аналогията помага само ако прави понятие по-разбираемо и не създава нова заблуда.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай пример или аналогия, които правят трудната идея по-разбираема, без да представят приблизителното сравнение като буквален факт."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Добрата аналогия запазва важната връзка и назовава границата си. Първо обясни реалния процес с прост пример; после сравни една характеристика. Ако аналогията кара зрителя да очаква невъзможен резултат, тя вреди повече от непознатия термин.\n\nГраница на правилото: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови частта от идеята, която затруднява зрителя.\n2. Избери познат предмет или действие със сходна една характеристика.\n3. Кажи къде сравнението спира да е вярно.\n4. Покажи реалния процес и върни вниманието към точния термин.\n\nСтоп-сигнал: Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства. Ако това се случи, приложи корекцията преди да продължиш: Използвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Центрирането на глина може да се сравни с въртене на топка около средата, но глината се деформира от натиск и влага — тя не е твърда топка. Инструкторът назовава това ограничение, след което показва как ръцете се опират и къде се променя формата.\n\nРешение в този случай:\nИзползвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция.\n\nГраница на извода:\nВ безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."},"after":{"label":"По-доброто решение","text":"Използвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция.\n\nПреди да продължиш: Покажи реалния процес и върни вниманието към точния термин."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Аналогията трябва да помага с една характеристика, не да пренася всички свойства на сравнението. Кажи къде сравнението спира. След аналогията върни се към конкретния предмет или действие в кадър; иначе зрителят може да запомни метафората, а не процеса.\n\nКритерий за приемане: Покажи реалния процес и върни вниманието към точния термин.\n\nКогато пробата се провали:\nСимптом: Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства.\nКорекция: Използвай фраза „подобно е само в това…; различава се по…“.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Обясни трудна идея с точен пример“?","options":[{"id":"a","label":"Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Използвай пример или аналогия, които правят трудната идея по-разбираема, без да представят приблизителното сравнение като буквален факт."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Използвай пример или аналогия, които правят трудната идея по-разбираема, без да представят приблизителното сравнение като буквален факт. Слабият ход е: Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Центрирането на глина може да се сравни с въртене на топка около средата, но глината се деформира от натиск и влага — тя не е твърда топка. Инструкторът назовава това ограничение, след което показва как ръцете се опират и къде се променя формата.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използвай фраза „подобно е само в това…; различава се по…“."},{"id":"b","label":"Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция. Грешният път — Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства. — оставя риска нерешен. Провери и границата: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Обясни трудна идея с точен пример“?","options":[{"id":"a","label":"Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай пример или аналогия, които правят трудната идея по-разбираема, без да представят приблизителното сравнение като буквален факт.","Първо: Назови частта от идеята, която затруднява зрителя. После: Избери познат предмет или действие със сходна една характеристика.","Следи за грешния ход: Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.","items":[{"id":"s1","text":"Назови частта от идеята, която затруднява зрителя."},{"id":"s3","text":"Кажи къде сравнението спира да е вярно."},{"id":"s4","text":"Покажи реалния процес и върни вниманието към точния термин."},{"id":"s2","text":"Избери познат предмет или действие със сходна една характеристика."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция. В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Центрирането на глина може да се сравни с въртене на топка около средата, но глината се деформира от натиск и влага — тя не е твърда топка.\n\nПроменено условие: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Използвай фраза „подобно е само в това…; различава се по…“."},{"id":"b","label":"Казваш „глината се държи точно като пластилин“ и оставяш зрителя да пренесе грешна техника към материал с други свойства."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай фраза „подобно е само в това…; различава се по…“. След аналогията дай точна демонстрация, за да не остане сравнението единствената инструкция. Границата тук е: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nКарта за работа — Обясни трудна идея с точен пример\n1. Назови частта от идеята, която затруднява зрителя.\n2. Избери познат предмет или действие със сходна една характеристика.\n3. Кажи къде сравнението спира да е вярно.\n4. Покажи реалния процес и върни вниманието към точния термин.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-11","title":"Пиши в своя глас, не в рекламна поза","objective":"да редактираш репликите така, че да звучат естествено и да пазят фактите","hook":"Зрителят чува, когато текстът се опитва да изглежда по-убедителен от самия автор.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да редактираш репликите така, че да звучат естествено и да пазят фактите. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Зрителят чува, когато текстът се опитва да изглежда по-убедителен от самия автор.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Пиши в гласа на човека или марката, а не в поза на реклама. Естественото звучене идва от точни думи, конкретни примери и ясни факти — не от нарочно разговорни украси."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Събери няколко реални реплики от интервю и обслужване, после потърси дължина на изреченията, думи, хумор и ниво на формалност. Запази смисъла, не копирай частен разговор. Изчисти клишета и суперлативи. Гласът трябва да издържи и прочетен на глас от друг член на екипа.\n\nГраница на правилото: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Събери одобрени примери за естествения говор на човека.\n2. Маркирай клишета, неподкрепени прилагателни и неестествени обещания.\n3. Пренапиши с конкретен глагол и думите, които аудиторията използва.\n4. Провери фактическата точност и произнеси репликите на глас.\n\nСтоп-сигнал: Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория. Тонът се превръща в имитация. Ако това се случи, приложи корекцията преди да продължиш: Остави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Вместо „Потопете се във вълшебния свят на творчеството“ инструкторът казва: „Първо ще омесим глината, после ще пробваме как се държи на колелото.“ Втората версия показва какво реално се случва и звучи като човек, който води урок.\n\nРешение в този случай:\nОстави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера.\n\nГраница на извода:\nНе сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория. Тонът се превръща в имитация."},"after":{"label":"По-доброто решение","text":"Остави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера.\n\nПреди да продължиш: Провери фактическата точност и произнеси репликите на глас."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Запиши естествения речник от интервю, коментар или реален разговор, но не копирай лични данни. Избери думи, които говорещият действително използва; махни рекламни прилагателни, които не може да защити. Прочети репликата на глас. Ако човекът трябва да я играе като чужда роля, тя не е неговият глас.\n\nКритерий за приемане: Провери фактическата точност и произнеси репликите на глас.\n\nКогато пробата се провали:\nСимптом: Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория.\nКорекция: Остави характерни думи, но не жертвай яснотата и фактите.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Пиши в своя глас, не в рекламна поза“?","options":[{"id":"a","label":"Пиши в гласа на човека или марката, а не в поза на реклама."},{"id":"b","label":"Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Пиши в гласа на човека или марката, а не в поза на реклама. Естественото звучене идва от точни думи, конкретни примери и ясни факти — не от нарочно разговорни украси. Слабият ход е: Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория. Тонът се превръща в имитация. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Вместо „Потопете се във вълшебния свят на творчеството“ инструкторът казва: „Първо ще омесим глината, после ще пробваме как се държи на колелото.“ Втората версия показва какво реално се случва и звучи като човек, който води урок.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Остави характерни думи, но не жертвай яснотата и фактите."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Остави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера. Грешният път — Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория. — оставя риска нерешен. Провери и границата: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Пиши в своя глас, не в рекламна поза“?","options":[{"id":"a","label":"Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория."},{"id":"b","label":"Не сменяй диалект, акцент или езиково ниво като комична характеристика."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Пиши в гласа на човека или марката, а не в поза на реклама. Естественото звучене идва от точни думи, конкретни примери и ясни факти — не от нарочно разговорни украси.","Първо: Събери одобрени примери за естествения говор на човека. После: Маркирай клишета, неподкрепени прилагателни и неестествени обещания.","Следи за грешния ход: Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.","items":[{"id":"s2","text":"Маркирай клишета, неподкрепени прилагателни и неестествени обещания."},{"id":"s1","text":"Събери одобрени примери за естествения говор на човека."},{"id":"s4","text":"Провери фактическата точност и произнеси репликите на глас."},{"id":"s3","text":"Пренапиши с конкретен глагол и думите, които аудиторията използва."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Остави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера. Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Вместо „Потопете се във вълшебния свят на творчеството“ инструкторът казва: „Първо ще омесим глината, после ще пробваме как се държи на колелото.“ Втората версия показва какво реално се случва и звучи като човек, който води урок.\n\nПроменено условие: Не сменяй диалект, акцент или езиково ниво като комична характеристика.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Остави характерни думи, но не жертвай яснотата и фактите."},{"id":"a","label":"Добавяш „брат, уникално е, буквално“ на всеки ред, защото смяташ, че това звучи естествено за млада аудитория."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Остави характерни думи, но не жертвай яснотата и фактите. Ако говорителят не би казал изречението на клиент, не го карай да го рецитира пред камера. Границата тук е: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.\n\nКарта за работа — Пиши в своя глас, не в рекламна поза\n1. Събери одобрени примери за естествения говор на човека.\n2. Маркирай клишета, неподкрепени прилагателни и неестествени обещания.\n3. Пренапиши с конкретен глагол и думите, които аудиторията използва.\n4. Провери фактическата точност и произнеси репликите на глас.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-12","title":"Раздели текста на дъхове и мисли","objective":"да превърнеш писмен текст в реплики, които лесно се произнасят и слушат","hook":"Дългото изречение може да изглежда гладко на екрана, но да звучи като четене.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш писмен текст в реплики, които лесно се произнасят и слушат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Дългото изречение може да изглежда гладко на екрана, но да звучи като четене.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Разделяй писмения текст на мисловни единици, които се произнасят лесно и се разбират от първо слушане."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Устната реплика трябва да има ясна опора: подлог, действие, предмет. Късите изречения помагат, но прекалено накъсаната реч звучи телеграфно. Маркирай пауза там, където смисълът сменя посока, и произнеси числата така, както ще ги чуе човекът.\n\nГраница на правилото: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Прочети текста на глас с естествена скорост и запиши време.\n2. Отбележи места за дъх, неясни местоимения и сложни натрупвания.\n3. Раздели идеите, като запазиш причината и условието.\n4. Направи пробен запис и провери разбираемост през слушалки.\n\nСтоп-сигнал: Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа. Темпото прикрива лошата редакция, но не я оправя. Ако това се случи, приложи корекцията преди да продължиш: Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Писмено: „За да предотвратим деформацията на съда, приложете равномерно, но не прекомерно, странично усилие…“ Устно: „Дръж натиска равномерен. Ако стената започне да се накланя, намали силата и върни ръцете към центъра.“ Демонстрацията показва момента за корекция.\n\nРешение в този случай:\nОриентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция.\n\nГраница на извода:\nНе режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа. Темпото прикрива лошата редакция, но не я оправя."},"after":{"label":"По-доброто решение","text":"Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция.\n\nПреди да продължиш: Направи пробен запис и провери разбираемост през слушалки."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Редактирай за изговаряне: една мисъл на дъх, естествено място за пауза, конкретно подлежащо и глагол. Сложните термини не стават ясни само защото са кратки. Прочети на реално темпо и мери времето с паузите; оценка по брой думи без произнасяне често пропуска трудната фраза.\n\nКритерий за приемане: Направи пробен запис и провери разбираемост през слушалки.\n\nКогато пробата се провали:\nСимптом: Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа.\nКорекция: Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Раздели текста на дъхове и мисли“?","options":[{"id":"a","label":"Разделяй писмения текст на мисловни единици, които се произнасят лесно и се разбират от първо слушане."},{"id":"b","label":"Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Разделяй писмения текст на мисловни единици, които се произнасят лесно и се разбират от първо слушане. Слабият ход е: Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа. Темпото прикрива лошата редакция, но не я оправя. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Писмено: „За да предотвратим деформацията на съда, приложете равномерно, но не прекомерно, странично усилие…“ Устно: „Дръж натиска равномерен. Ако стената започне да се накланя, намали силата и върни ръцете към центъра.“ Демонстрацията показва момента за корекция.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция. Грешният път — Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа. — оставя риска нерешен. Провери и границата: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Раздели текста на дъхове и мисли“?","options":[{"id":"a","label":"Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа."},{"id":"b","label":"Не режи условие или отрицание само за да стане по-кратко."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Разделяй писмения текст на мисловни единици, които се произнасят лесно и се разбират от първо слушане.","Първо: Прочети текста на глас с естествена скорост и запиши време. После: Отбележи места за дъх, неясни местоимения и сложни натрупвания.","Следи за грешния ход: Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.","items":[{"id":"s3","text":"Раздели идеите, като запазиш причината и условието."},{"id":"s2","text":"Отбележи места за дъх, неясни местоимения и сложни натрупвания."},{"id":"s1","text":"Прочети текста на глас с естествена скорост и запиши време."},{"id":"s4","text":"Направи пробен запис и провери разбираемост през слушалки."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция. Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Писмено: „За да предотвратим деформацията на съда, приложете равномерно, но не прекомерно, странично усилие…“ Устно: „Дръж натиска равномерен.\n\nПроменено условие: Не режи условие или отрицание само за да стане по-кратко.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Слагаш 38 думи в едно изречение с три подчинени части, после ускоряваш диктора в монтажа."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Ориентирът е лесно произнасяне и слушане, не фиксиран брой думи. Прочети два дубъла: ако говорителят спира на едно и също място, редактирай тази конструкция. Границата тук е: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.\n\nКарта за работа — Раздели текста на дъхове и мисли\n1. Прочети текста на глас с естествена скорост и запиши време.\n2. Отбележи места за дъх, неясни местоимения и сложни натрупвания.\n3. Раздели идеите, като запазиш причината и условието.\n4. Направи пробен запис и провери разбираемост през слушалки.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-13","title":"Изпълни сценария без да звучиш наизуст","objective":"да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение","hook":"Много добър текст звучи празно, ако говорещият се опитва да го възпроизведе дума по дума.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Много добър текст звучи празно, ако говорещият се опитва да го възпроизведе дума по дума.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Изпълни сценария така, че вниманието да остане върху смисъла, а не върху запомнянето на точния текст. Подготовката помага на естествеността; тя не трябва да създава измислена спонтанност."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Избери метод според материала: телесуфльор за точни условия, ключови точки за личен разказ, демонстрация с кратки реплики за действие. Постави погледа близо до обектива, провери скоростта и повтори важни думи еднакво между дублите. Запиши паузи и реакции, не само „чистия текст“.\n\nГраница на правилото: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Раздели сценария на мисли и маркирай факти, които не бива да се променят.\n2. Избери телесуфльор, опорни точки или демонстрация според задачата.\n3. Репетирай с кадър и звук; коригирай поглед, темпо и действия.\n4. Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия.\n\nСтоп-сигнал: Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали. Всеки дубъл казва различно условие. Ако това се случи, приложи корекцията преди да продължиш: Маркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Майсторката обяснява „първо отпусни натиска“ докато работи. Вместо да я караш да чете 120 думи, поставяш три опори до камерата: център, натиск, форма. Записваш действията и после добавяш само точния факт за материала. Дублите използват същата позиция на ръцете.\n\nРешение в този случай:\nМаркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва.\n\nГраница на извода:\nНе принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали. Всеки дубъл казва различно условие."},"after":{"label":"По-доброто решение","text":"Маркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва.\n\nПреди да продължиш: Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Използвай телепромптър като опора, не като доказателство за естествено звучене. Раздели текста по мисли, отбележи ударенията и остави място за поглед към събеседника или демонстрацията. Ако говорещият зацикля, снимай по смислови части, а после провери дали склейките не променят намерението му.\n\nКритерий за приемане: Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия.\n\nКогато пробата се провали:\nСимптом: Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали.\nКорекция: Маркирай числата и обещанията като неизменяеми реплики.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Изпълни сценария без да звучиш наизуст“?","options":[{"id":"a","label":"Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали."},{"id":"b","label":"Изпълни сценария така, че вниманието да остане върху смисъла, а не върху запомнянето на точния текст."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Изпълни сценария така, че вниманието да остане върху смисъла, а не върху запомнянето на точния текст. Подготовката помага на естествеността; тя не трябва да създава измислена спонтанност. Слабият ход е: Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали. Всеки дубъл казва различно условие. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Майсторката обяснява „първо отпусни натиска“ докато работи. Вместо да я караш да чете 120 думи, поставяш три опори до камерата: център, натиск, форма. Записваш действията и после добавяш само точния факт за материала. Дублите използват същата позиция на ръцете.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали."},{"id":"b","label":"Маркирай числата и обещанията като неизменяеми реплики."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Маркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва. Грешният път — Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали. — оставя риска нерешен. Провери и границата: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Изпълни сценария без да звучиш наизуст“?","options":[{"id":"a","label":"Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“."},{"id":"b","label":"Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Изпълни сценария така, че вниманието да остане върху смисъла, а не върху запомнянето на точния текст. Подготовката помага на естествеността; тя не трябва да създава измислена спонтанност.","Първо: Раздели сценария на мисли и маркирай факти, които не бива да се променят. После: Избери телесуфльор, опорни точки или демонстрация според задачата.","Следи за грешния ход: Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.","items":[{"id":"s3","text":"Репетирай с кадър и звук; коригирай поглед, темпо и действия."},{"id":"s4","text":"Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия."},{"id":"s2","text":"Избери телесуфльор, опорни точки или демонстрация според задачата."},{"id":"s1","text":"Раздели сценария на мисли и маркирай факти, които не бива да се променят."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Маркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва. Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Майсторката обяснява „първо отпусни натиска“ докато работи.\n\nПроменено условие: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Маркирай числата и обещанията като неизменяеми реплики."},{"id":"b","label":"Насърчаваш водещия да „говори спонтанно“, без да потвърдите цена или включени материали."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Маркирай числата и обещанията като неизменяеми реплики. Остави свободно място само за личен пример, който е одобрен и може да се използва. Границата тук е: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.\n\nКарта за работа — Изпълни сценария без да звучиш наизуст\n1. Раздели сценария на мисли и маркирай факти, които не бива да се променят.\n2. Избери телесуфльор, опорни точки или демонстрация според задачата.\n3. Репетирай с кадър и звук; коригирай поглед, темпо и действия.\n4. Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-14","title":"Използвай паузи и темпо за смисъл","objective":"да регулираш скоростта според сложността, емоцията и нуждата от разбиране","hook":"Постоянно бързо говорене не е равнозначно на енергично видео.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да регулираш скоростта според сложността, емоцията и нуждата от разбиране. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Постоянно бързо говорене не е равнозначно на енергично видео.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай паузи и темпо така, че зрителят да обработи сложна информация и да види ключово действие."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Променяй скоростта по функция: кратко въвеждане, спокойно критично действие, стегнат преход, достатъчна пауза за резултат. Еднакво бързият монтаж притъпява акцентите; забавеният клип без причина губи време. Остави естествен звук, когато той показва сила, допир или механичен сигнал.\n\nГраница на правилото: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Маркирай в сценария местата с висока когнитивна трудност.\n2. Сними действията в реално време и добави отделен чист детайл.\n3. Реши къде паузата носи напрежение, разбиране или въздух.\n4. Провери монтаж без музика, за да чуеш истинското темпо.\n\nСтоп-сигнал: Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика. Клипът изглежда динамичен, но действието се губи. Ако това се случи, приложи корекцията преди да продължиш: Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Когато инструкторът показва центъра на колелото, монтажът оставя 2–3 секунди непрекъснато действие. Преминаването към следващата сцена е бързо, но звукът на въртенето остава. Зрителят успява да проследи движението, без да гледа излишно чакане.\n\nРешение в този случай:\nСравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие.\n\nГраница на извода:\nПри субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика. Клипът изглежда динамичен, но действието се губи."},"after":{"label":"По-доброто решение","text":"Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие.\n\nПреди да продължиш: Провери монтаж без музика, за да чуеш истинското темпо."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Темпото не е равномерна скорост. Остави време преди важното действие, не режи дъха след отговор и не поставяй музика върху дума, от която зависи разбирането. При ускоряване или забавяне провери жестове, звук и надпис; монтажният ефект не трябва да изкривява истинския процес.\n\nКритерий за приемане: Провери монтаж без музика, за да чуеш истинското темпо.\n\nКогато пробата се провали:\nСимптом: Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика.\nКорекция: Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Използвай паузи и темпо за смисъл“?","options":[{"id":"a","label":"Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика."},{"id":"b","label":"Използвай паузи и темпо така, че зрителят да обработи сложна информация и да види ключово действие."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Използвай паузи и темпо така, че зрителят да обработи сложна информация и да види ключово действие. Слабият ход е: Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика. Клипът изглежда динамичен, но действието се губи. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Когато инструкторът показва центъра на колелото, монтажът оставя 2–3 секунди непрекъснато действие. Преминаването към следващата сцена е бързо, но звукът на въртенето остава. Зрителят успява да проследи движението, без да гледа излишно чакане.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика."},{"id":"b","label":"Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие. Грешният път — Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика. — оставя риска нерешен. Провери и границата: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Използвай паузи и темпо за смисъл“?","options":[{"id":"a","label":"При субтитри, инструкции и числа остави екранното време за реално прочитане."},{"id":"b","label":"Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай паузи и темпо така, че зрителят да обработи сложна информация и да види ключово действие.","Първо: Маркирай в сценария местата с висока когнитивна трудност. После: Сними действията в реално време и добави отделен чист детайл.","Следи за грешния ход: Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.","items":[{"id":"s1","text":"Маркирай в сценария местата с висока когнитивна трудност."},{"id":"s4","text":"Провери монтаж без музика, за да чуеш истинското темпо."},{"id":"s3","text":"Реши къде паузата носи напрежение, разбиране или въздух."},{"id":"s2","text":"Сними действията в реално време и добави отделен чист детайл."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие. При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Когато инструкторът показва центъра на колелото, монтажът оставя 2–3 секунди непрекъснато действие.\n\nПроменено условие: При субтитри, инструкции и числа остави екранното време за реално прочитане.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие."},{"id":"a","label":"Поставяш преход и звуков ефект на всеки кадър, включително над важната реплика."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Сравни версия с нормална скорост и версия с ускорение; забавяй само ако това прави детайла по-видим и ясно обозначи забавеното действие. Границата тук е: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.\n\nКарта за работа — Използвай паузи и темпо за смисъл\n1. Маркирай в сценария местата с висока когнитивна трудност.\n2. Сними действията в реално време и добави отделен чист детайл.\n3. Реши къде паузата носи напрежение, разбиране или въздух.\n4. Провери монтаж без музика, за да чуеш истинското темпо.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-15","title":"Напиши призив, който следва от видеото","objective":"да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя","hook":"Последните секунди звучат чуждо, когато призив за действие сменя темата и иска прекалено много.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Последните секунди звучат чуждо, когато призив за действие сменя темата и иска прекалено много.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Напиши един призив за действие, който продължава стойността на видеото и отговаря на готовността на зрителя."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Призивът съдържа действие и обект: „Виж графика“, „Свали списъка“, „Запази място“. Посочи къде се изпълнява и какво ще стане след това. Не наслагвай конкуриращи бутони; не обещавай бонус, крайна дата или дефицит без основание.\n\nГраница на правилото: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Завършваш с „последни места“, когато има свободни места и няма срок. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи каква информация вече има зрителят.\n2. Избери едно действие, което помага да реши оставащия въпрос.\n3. Назови връзката, бутона или мястото за следващата стъпка.\n4. Провери, че целевата страница е актуална и изпълнява обещанието.\n\nСтоп-сигнал: Завършваш с „последни места“, когато има свободни места и няма срок. Това може да доведе до клик, но е невярно. Ако това се случи, приложи корекцията преди да продължиш: Прочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие?"},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Клипът показва как протича първият урок, но не показва наличните дати. Призивът е „Виж датите и какво включва занятието“; страницата показва продължителност, цена, материали и правила. Ако видеото е само за умение, призивът може да води към следващ урок, не към продажба.\n\nРешение в този случай:\nПрочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие?\n\nГраница на извода:\nПризив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Завършваш с „последни места“, когато има свободни места и няма срок. Това може да доведе до клик, но е невярно."},"after":{"label":"По-доброто решение","text":"Прочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие?\n\nПреди да продължиш: Провери, че целевата страница е актуална и изпълнява обещанието."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Призивът съдържа действие и място, където зрителят го прави. Провери връзката от телефон, датата на офертата и условието, което следва след клика. Не създавай недостиг на места или срок, който не съществува. Ако готовността е ниска, предложи полезната следваща информация, не принудителна покупка.\n\nКритерий за приемане: Провери, че целевата страница е актуална и изпълнява обещанието.\n\nКогато пробата се провали:\nСимптом: Завършваш с „последни места“, когато има свободни места и няма срок.\nКорекция: Прочети призива заедно с началното обещание.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Напиши призив, който следва от видеото“?","options":[{"id":"a","label":"Завършваш с „последни места“, когато има свободни места и няма срок."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Напиши един призив за действие, който продължава стойността на видеото и отговаря на готовността на зрителя."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Напиши един призив за действие, който продължава стойността на видеото и отговаря на готовността на зрителя. Слабият ход е: Завършваш с „последни места“, когато има свободни места и няма срок. Това може да доведе до клик, но е невярно. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Клипът показва как протича първият урок, но не показва наличните дати. Призивът е „Виж датите и какво включва занятието“; страницата показва продължителност, цена, материали и правила. Ако видеото е само за умение, призивът може да води към следващ урок, не към продажба.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Прочети призива заедно с началното обещание."},{"id":"b","label":"Завършваш с „последни места“, когато има свободни места и няма срок."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Прочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие? Грешният път — Завършваш с „последни места“, когато има свободни места и няма срок. — оставя риска нерешен. Провери и границата: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Напиши призив, който следва от видеото“?","options":[{"id":"a","label":"Завършваш с „последни места“, когато има свободни места и няма срок."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Напиши един призив за действие, който продължава стойността на видеото и отговаря на готовността на зрителя.","Първо: Определи каква информация вече има зрителят. После: Избери едно действие, което помага да реши оставащия въпрос.","Следи за грешния ход: Завършваш с „последни места“, когато има свободни места и няма срок."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.","items":[{"id":"s2","text":"Избери едно действие, което помага да реши оставащия въпрос."},{"id":"s4","text":"Провери, че целевата страница е актуална и изпълнява обещанието."},{"id":"s1","text":"Определи каква информация вече има зрителят."},{"id":"s3","text":"Назови връзката, бутона или мястото за следващата стъпка."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Прочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие? Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Клипът показва как протича първият урок, но не показва наличните дати.\n\nПроменено условие: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Завършваш с „последни места“, когато има свободни места и няма срок."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Прочети призива заедно с началното обещание."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Прочети призива заедно с началното обещание. Ако човекът кликне, намира ли точно следващата информация без нова пречка или неочаквано условие? Границата тук е: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nКарта за работа — Напиши призив, който следва от видеото\n1. Определи каква информация вече има зрителят.\n2. Избери едно действие, което помага да реши оставащия въпрос.\n3. Назови връзката, бутона или мястото за следващата стъпка.\n4. Провери, че целевата страница е актуална и изпълнява обещанието.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Преди публикуване отвори целевата страница от телефон и провери, че съвпадат име, цена, срок и следваща стъпка. Скрито условие или неактивен линк превръща добрия призив в подвеждащ."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-16","title":"Подготви версия за различна готовност на зрителя","objective":"да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие","hook":"Един и същ призив може да е полезен за един зрител и преждевременен за друг.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един и същ призив може да е полезен за един зрител и преждевременен за друг.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подготви версии за различна готовност, като променяш акцента и следващата информация, а не истинността на продукта."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Човек, който тепърва научава за темата, има нужда от контекст и прост пример; сравняващият — от критерии и ограничения; готовият за действие — от цена, дата и условия. Сегментите са работни сценарии, не твърдения за всеки човек в групата. Не скривай съществен факт в една версия.\n\nГраница на правилото: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови етапа и нерешения въпрос на всеки сегмент.\n2. Запази общия доказуем факт и основното обещание.\n3. Промени началото, пример или призив за действие според нуждата.\n4. Провери, че всички версии са точни и не си противоречат.\n\nСтоп-сигнал: Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство. Ако това се случи, приложи корекцията преди да продължиш: Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Версия А започва „Какво става на първо занятие?“ Версия Б започва „Материалите и инструментите са включени; изпичането е след курса.“ Втората ползва потвърдени условия и не ги крие. И двете водят към една и съща страница с график.\n\nРешение в този случай:\nРазделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава.\n\nГраница на извода:\nНе използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."},"after":{"label":"По-доброто решение","text":"Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава.\n\nПреди да продължиш: Провери, че всички версии са точни и не си противоречат."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Различавай етапа на знание от личната стойност на човека. Новият зрител може да има нужда от термин и контекст; човекът, който сравнява, може да иска цена, срок или ограничение. Версиите променят подредбата на информацията, не истинността на твърдението и не скриват важни условия.\n\nКритерий за приемане: Провери, че всички версии са точни и не си противоречат.\n\nКогато пробата се провали:\nСимптом: Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство.\nКорекция: Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подготви версия за различна готовност на зрителя“?","options":[{"id":"a","label":"Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Подготви версии за различна готовност, като променяш акцента и следващата информация, а не истинността на продукта."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Подготви версии за различна готовност, като променяш акцента и следващата информация, а не истинността на продукта. Слабият ход е: Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Версия А започва „Какво става на първо занятие?“ Версия Б започва „Материалите и инструментите са включени; изпичането е след курса.“ Втората ползва потвърдени условия и не ги крие. И двете водят към една и съща страница с график.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава."},{"id":"b","label":"Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава. Грешният път — Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство. — оставя риска нерешен. Провери и границата: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подготви версия за различна готовност на зрителя“?","options":[{"id":"a","label":"Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подготви версии за различна готовност, като променяш акцента и следващата информация, а не истинността на продукта.","Първо: Назови етапа и нерешения въпрос на всеки сегмент. После: Запази общия доказуем факт и основното обещание.","Следи за грешния ход: Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.","items":[{"id":"s1","text":"Назови етапа и нерешения въпрос на всеки сегмент."},{"id":"s3","text":"Промени началото, пример или призив за действие според нуждата."},{"id":"s2","text":"Запази общия доказуем факт и основното обещание."},{"id":"s4","text":"Провери, че всички версии са точни и не си противоречат."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава. Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Версия А започва „Какво става на първо занятие?“ Версия Б започва „Материалите и инструментите са включени; изпичането е след курса.“ Втората ползва потвърдени условия и не ги крие.\n\nПроменено условие: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава."},{"id":"b","label":"Правиш една версия за „млади хора“, друга за „сериозни хора“ и приписваш мотиви по демография без доказателство."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Разделяй по поведение и нерешен въпрос, например нов/сравняващ/готов, и провери на данни дали различието реално се наблюдава. Границата тук е: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nКарта за работа — Подготви версия за различна готовност на зрителя\n1. Назови етапа и нерешения въпрос на всеки сегмент.\n2. Запази общия доказуем факт и основното обещание.\n3. Промени началото, пример или призив за действие според нуждата.\n4. Провери, че всички версии са точни и не си противоречат.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-17","title":"Адаптирай сценария към платформата без да го копираш на сляпо","objective":"да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла","hook":"Автоматичното изрязване не прави от един клип три подходящи версии.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Автоматичното изрязване не прави от един клип три подходящи версии.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Адаптирай сценария към платформата, като промениш кадрирането, началния контекст, темпо и призив за действие, но запазиш обещанието и доказателството."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Различните повърхности имат различен интерфейс, звуков режим, навигация, ограничения и начин на откриване. Не приемай, че един и същ файл, надпис и призив ще работи еднакво навсякъде. Проверявай текущите официални изисквания и прегледай тестовия качване на телефона.\n\nГраница на правилото: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Слагаш важен текст по долния край и той се покрива от описанието/управлението. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи къде и как видеото ще бъде открито и гледано.\n2. Пази главния обект и важния текст в безопасна композиция за този интерфейс.\n3. Настрой първите секунди и призива за реалния път на зрителя.\n4. Провери финалната публикация в приложението и потвърди връзките.\n\nСтоп-сигнал: Слагаш важен текст по долния край и той се покрива от описанието/управлението. Или приемаш, че платформата сама ще избере кадъра, който носи доказателството. Ако това се случи, приложи корекцията преди да продължиш: Използвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Хоризонталният разговорен запис се прекадрира автоматично за вертикален клип и отрязва ръцете, които показват техниката. Вместо централно изрязване, снимачният план предвижда отделен вертикален детайл. Надписът остава извън областта, която закриват бутони и профилни елементи.\n\nРешение в този случай:\nИзползвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране.\n\nГраница на извода:\nУказанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Слагаш важен текст по долния край и той се покрива от описанието/управлението. Или приемаш, че платформата сама ще избере кадъра, който носи доказателството."},"after":{"label":"По-доброто решение","text":"Използвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране.\n\nПреди да продължиш: Провери финалната публикация в приложението и потвърди връзките."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Направи отделен монтажен план за всяка платформа: началният контекст, вертикалното кадриране, надписите и призивът могат да се променят. Запази централното обещание и доказателство. Прегледай готовия файл в самото приложение; интерфейс, продължителност и позиция на бутоните се променят.\n\nКритерий за приемане: Провери финалната публикация в приложението и потвърди връзките.\n\nКогато пробата се провали:\nСимптом: Слагаш важен текст по долния край и той се покрива от описанието/управлението.\nКорекция: Използвай тестова публикация или предпреглед на реален телефон.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Адаптирай сценария към платформата без да го копираш на сляпо“?","options":[{"id":"a","label":"Адаптирай сценария към платформата, като промениш кадрирането, началния контекст, темпо и призив за действие, но запазиш обещанието и доказателството."},{"id":"b","label":"Слагаш важен текст по долния край и той се покрива от описанието/управлението."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Адаптирай сценария към платформата, като промениш кадрирането, началния контекст, темпо и призив за действие, но запазиш обещанието и доказателството. Слабият ход е: Слагаш важен текст по долния край и той се покрива от описанието/управлението. Или приемаш, че платформата сама ще избере кадъра, който носи доказателството. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Хоризонталният разговорен запис се прекадрира автоматично за вертикален клип и отрязва ръцете, които показват техниката. Вместо централно изрязване, снимачният план предвижда отделен вертикален детайл. Надписът остава извън областта, която закриват бутони и профилни елементи.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Слагаш важен текст по долния край и той се покрива от описанието/управлението."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Използвай тестова публикация или предпреглед на реален телефон."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране. Грешният път — Слагаш важен текст по долния край и той се покрива от описанието/управлението. — оставя риска нерешен. Провери и границата: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Адаптирай сценария към платформата без да го копираш на сляпо“?","options":[{"id":"a","label":"Слагаш важен текст по долния край и той се покрива от описанието/управлението."},{"id":"b","label":"Указанията за формат и интерфейс се променят."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Адаптирай сценария към платформата, като промениш кадрирането, началния контекст, темпо и призив за действие, но запазиш обещанието и доказателството.","Първо: Определи къде и как видеото ще бъде открито и гледано. После: Пази главния обект и важния текст в безопасна композиция за този интерфейс.","Следи за грешния ход: Слагаш важен текст по долния край и той се покрива от описанието/управлението."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.","items":[{"id":"s2","text":"Пази главния обект и важния текст в безопасна композиция за този интерфейс."},{"id":"s4","text":"Провери финалната публикация в приложението и потвърди връзките."},{"id":"s3","text":"Настрой първите секунди и призива за реалния път на зрителя."},{"id":"s1","text":"Определи къде и как видеото ще бъде открито и гледано."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране. Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Хоризонталният разговорен запис се прекадрира автоматично за вертикален клип и отрязва ръцете, които показват техниката.\n\nПроменено условие: Указанията за формат и интерфейс се променят.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Използвай тестова публикация или предпреглед на реален телефон."},{"id":"a","label":"Слагаш важен текст по долния край и той се покрива от описанието/управлението."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай тестова публикация или предпреглед на реален телефон. Провери първи кадър, четливост, субтитри, безопасна зона и призив за действие след компресиране. Границата тук е: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.\n\nКарта за работа — Адаптирай сценария към платформата без да го копираш на сляпо\n1. Определи къде и как видеото ще бъде открито и гледано.\n2. Пази главния обект и важния текст в безопасна композиция за този интерфейс.\n3. Настрой първите секунди и призива за реалния път на зрителя.\n4. Провери финалната публикация в приложението и потвърди връзките.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-18","title":"Тествай две версии с една ясна хипотеза","objective":"да сравниш варианти, без да приписваш разликата на грешен фактор","hook":"„Този hook работи“ е прибързан извод, ако сравненията са правени пред различни аудитории.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш варианти, без да приписваш разликата на грешен фактор. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Този hook работи“ е прибързан извод, ако сравненията са правени пред различни аудитории.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Тествай две версии чрез ясна хипотеза и промяна на един елемент. Сравнявай еднакъв тип аудитория и избери показател, който отразява полезността, не само клик."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Промени например само първия кадър, остави текста и разпространението еднакви и определи предварително времето за тест. Провери колко показвания имаш, дали аудиториите са съпоставими и дали сезонност/бюджет се различават. „Победител“ може да не гарантира повторение в друг сегмент.\n\nГраница на правилото: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Напиши A/B хипотеза: кой елемент и какъв резултат ще промени.\n2. Направи варианти, които се различават само по този елемент.\n3. Избери метрика и минимални условия за сравнение преди пускане.\n4. Запиши резултат, ограничения и следващия тест, включително когато няма победител.\n\nСтоп-сигнал: Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила. Ако това се случи, приложи корекцията преди да продължиш: Записвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Ателието сравнява два миниатюра кадъра за дълго YouTube видео: готова чаша срещу близък план на ръцете. Заглавие, видео и аудитория остават еднакви. Екипът гледа не само клик, а и дали избраната корица привлича правилните зрители към съдържанието. YouTube Test & Compare сравнява до три миниатюри по дела от общото време на гледане; това е тест за миниатюра, не за всички елементи на сценария.\n\nРешение в този случай:\nЗаписвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“.\n\nГраница на извода:\nПлатформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."},"after":{"label":"По-доброто решение","text":"Записвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“.\n\nПреди да продължиш: Запиши резултат, ограничения и следващия тест, включително когато няма победител."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Преди тест запиши коя промяна тестваш и какво ще означава „по-добре“. Не обявявай победител при несъпоставими аудитории, периоди или разпространение. Ако платформеният инструмент проверява миниатюра, изводът му не отговаря автоматично на въпроса кой сценарий или хук е по-добър.\n\nКритерий за приемане: Запиши резултат, ограничения и следващия тест, включително когато няма победител.\n\nКогато пробата се провали:\nСимптом: Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила.\nКорекция: Записвай версия, дата, аудитория, показвания и контекст.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Тествай две версии с една ясна хипотеза“?","options":[{"id":"a","label":"Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."},{"id":"b","label":"Тествай две версии чрез ясна хипотеза и промяна на един елемент."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Тествай две версии чрез ясна хипотеза и промяна на един елемент. Сравнявай еднакъв тип аудитория и избери показател, който отразява полезността, не само клик. Слабият ход е: Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Ателието сравнява два миниатюра кадъра за дълго YouTube видео: готова чаша срещу близък план на ръцете. Заглавие, видео и аудитория остават еднакви. Екипът гледа не само клик, а и дали избраната корица привлича правилните зрители към съдържанието. YouTube Test & Compare сравнява до три миниатюри по дела от общото време на гледане; това е тест за миниатюра, не за всички елементи на сценария.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."},{"id":"b","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."},{"id":"c","label":"Записвай версия, дата, аудитория, показвания и контекст."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Записвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“. Грешният път — Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила. — оставя риска нерешен. Провери и границата: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Тествай две версии с една ясна хипотеза“?","options":[{"id":"a","label":"Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."},{"id":"b","label":"Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Тествай две версии чрез ясна хипотеза и промяна на един елемент. Сравнявай еднакъв тип аудитория и избери показател, който отразява полезността, не само клик.","Първо: Напиши A/B хипотеза: кой елемент и какъв резултат ще промени. После: Направи варианти, които се различават само по този елемент.","Следи за грешния ход: Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.","items":[{"id":"s3","text":"Избери метрика и минимални условия за сравнение преди пускане."},{"id":"s4","text":"Запиши резултат, ограничения и следващия тест, включително когато няма победител."},{"id":"s1","text":"Напиши A/B хипотеза: кой елемент и какъв резултат ще промени."},{"id":"s2","text":"Направи варианти, които се различават само по този елемент."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Записвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“. Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Ателието сравнява два миниатюра кадъра за дълго YouTube видео: готова чаша срещу близък план на ръцете.\n\nПроменено условие: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Едновременно сменяш хук, заглавие, бюджет, миниатюра и призив за действие, после обявяваш коя промяна е спечелила."},{"id":"b","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"c","label":"Записвай версия, дата, аудитория, показвания и контекст."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Записвай версия, дата, аудитория, показвания и контекст. Ако обемът е малък или резултатите са близки, заключението е „няма достатъчно ясен победител“. Границата тук е: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.\n\nКогато пробният зрител не може да повтори обещанието, намери първата сцена, в която темата се отклонява. Поправи това звено и провери отново; не пренаписвай автоматично целия сценарий.\n\nКарта за работа — Тествай две версии с една ясна хипотеза\n1. Напиши A/B хипотеза: кой елемент и какъв резултат ще промени.\n2. Направи варианти, които се различават само по този елемент.\n3. Избери метрика и минимални условия за сравнение преди пускане.\n4. Запиши резултат, ограничения и следващия тест, включително когато няма победител.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Test & compare миниатюри: https://support.google.com/youtube/answer/13861714?hl=en (провери актуалната версия преди публикуване)."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-19","title":"Редактирай сценария за яснота и време","objective":"да съкратиш сценария, без да махнеш доказателството и нужния контекст","hook":"„Кратко“ не е полезно, ако зрителят вече не разбира как да повтори действието.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съкратиш сценария, без да махнеш доказателството и нужния контекст. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Кратко“ не е полезно, ако зрителят вече не разбира как да повтори действието.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Редактирай сценария за яснота и реално време, като запазиш контекста, доказателството и условието, които са нужни на зрителя.\n\nСлушай текста без музика и гледай кадъра без звук. Ако зрителят пак не разбира действието и причината, добави нужния образ или пренапиши репликата."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Премахвай повторение, празни уводи и странични примери преди да режеш доказателство. Времетраенето не се оценява само по броя думи: пауза, демонстрация, субтитри и преход също заемат време. Направи груб прочит с хронометър и отделно пробен монтаж.\n\nГраница на правилото: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Прочети текста на глас и измери естественото време.\n2. Маркирай повторения и изречения, които не променят разбирането.\n3. Пази твърдение, доказателство, условие и следваща стъпка.\n4. Провери новия монтаж с човек, който не е писал сценария.\n\nСтоп-сигнал: Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа. Това скъсява видеото, но променя очакването. Ако това се случи, приложи корекцията преди да продължиш: При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"45-секундната версия е 72 секунди, защото представя историята, продуктите и целия процес. Екипът маха дублирания увод и втория пример, но запазва момента, в който материалите са уточнени. Демонстрацията остава в реално време; само преходите се стягат.\n\nРешение в този случай:\nПри всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш.\n\nГраница на извода:\nОграничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа. Това скъсява видеото, но променя очакването."},"after":{"label":"По-доброто решение","text":"При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш.\n\nПреди да продължиш: Провери новия монтаж с човек, който не е писал сценария."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Съкращавай след като структурата работи. Премахни повторение, дълъг преход и факт, който не помага на текущото обещание; не махай условие, което прави твърдението вярно. Провери времето при реално произнасяне и остави място за реакция, жест и визуален детайл.\n\nКритерий за приемане: Провери новия монтаж с човек, който не е писал сценария.\n\nКогато пробата се провали:\nСимптом: Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа.\nКорекция: При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи?\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Редактирай сценария за яснота и време“?","options":[{"id":"a","label":"Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа."},{"id":"b","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."},{"id":"c","label":"Редактирай сценария за яснота и реално време, като запазиш контекста, доказателството и условието, които са нужни на зрителя."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Редактирай сценария за яснота и реално време, като запазиш контекста, доказателството и условието, които са нужни на зрителя. Слабият ход е: Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа. Това скъсява видеото, но променя очакването. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: 45-секундната версия е 72 секунди, защото представя историята, продуктите и целия процес. Екипът маха дублирания увод и втория пример, но запазва момента, в който материалите са уточнени. Демонстрацията остава в реално време; само преходите се стягат.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа."},{"id":"b","label":"При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи?"},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш. Грешният път — Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа. — оставя риска нерешен. Провери и границата: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Редактирай сценария за яснота и време“?","options":[{"id":"a","label":"Ограничение по дължина не оправдава скрито условие."},{"id":"b","label":"Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Редактирай сценария за яснота и реално време, като запазиш контекста, доказателството и условието, които са нужни на зрителя.","Първо: Прочети текста на глас и измери естественото време. После: Маркирай повторения и изречения, които не променят разбирането.","Следи за грешния ход: Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.","items":[{"id":"s4","text":"Провери новия монтаж с човек, който не е писал сценария."},{"id":"s1","text":"Прочети текста на глас и измери естественото време."},{"id":"s2","text":"Маркирай повторения и изречения, които не променят разбирането."},{"id":"s3","text":"Пази твърдение, доказателство, условие и следваща стъпка."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш. Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: 45-секундната версия е 72 секунди, защото представя историята, продуктите и целия процес.\n\nПроменено условие: Ограничение по дължина не оправдава скрито условие.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи?"},{"id":"b","label":"Изтриваш „само за начинаещи“ и „изпичането става след курса“, защото удължават надписа."},{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: При всяко изрязване запитай: кой факт става неразбираем, кой кадър престава да доказва и кой знак за преход се губи? Ако отговорът е съществен, преработи вместо да режеш. Границата тук е: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.\n\nНаправи и по-кратка версия, но първо реши кой пример или повторение да махнеш. Остави обещанието, доказателството и нужната граница; прочети версията на глас и провери кадъра без звук.\n\nПоследен тест: чути само репликите, видеото пак трябва да има ясна мисъл; видени без звук, кадрите трябва да показват основното действие. Ако двете версии си противоречат, сценарият още не е готов.\n\nКарта за работа — Редактирай сценария за яснота и време\n1. Прочети текста на глас и измери естественото време.\n2. Маркирай повторения и изречения, които не променят разбирането.\n3. Пази твърдение, доказателство, условие и следваща стъпка.\n4. Провери новия монтаж с човек, който не е писал сценария.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-20","title":"Подготви сценарий, готов за снимане","objective":"да предадеш сценарий с текст, кадри, доказателства и начин за проверка","hook":"Хубав текст не е снимачен документ, докато екипът не разбира какво да заснеме.","subtitle":"Сценарий, който се снима и проверява","estimated_minutes":28,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш сценарий с текст, кадри, доказателства и начин за проверка. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Хубав текст не е снимачен документ, докато екипът не разбира какво да заснеме.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подготви сценарий, който е достатъчно ясен, за да започне снимането: реплики, кадри, доказателства, звук, надписи, времетраене, права и отговорник за одобрение."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Професионалният сценарий е работен документ, не само диалог. За всяка секция запиши приблизително време, картина, звук/реплика, графика, източник на факта и нужния актив. Отдели задължителен кадър от резервен. Версиите и името на одобряващия предотвратяват спор кое е последно.\n\nГраница на правилото: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Документът е една колона с диалог. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Раздели сценария на части и оцени времето с пробен прочит.\n2. Попълни паралелно картина, звук, надпис и доказателство.\n3. Посочи права, хора, реквизит, място и резервен вариант.\n4. Провери версията, сроковете, спецификацията и критериите за приемане.\n\nСтоп-сигнал: Документът е една колона с диалог. Операторът измисля кадри на място, а монтажистът не знае дали графиката съдържа проверен факт. Ако това се случи, приложи корекцията преди да продължиш: Предай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Предаването съдържа 00:00–00:03 ръце на колелото/звук на въртене/въпрос; 00:03–00:09 инструктор показва център/кратка реплика; 00:09–00:15 близък план на формата/етикет „материалите са включени“ след потвърждение; финал — актуален график и призив за действие. Списъкът посочва кой кадър се снима вертикално и кой факт чака клиента.\n\nРешение в този случай:\nПредай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения.\n\nГраница на извода:\nСценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Документът е една колона с диалог. Операторът измисля кадри на място, а монтажистът не знае дали графиката съдържа проверен факт."},"after":{"label":"По-доброто решение","text":"Предай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения.\n\nПреди да продължиш: Провери версията, сроковете, спецификацията и критериите за приемане."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Сценарият за снимане трябва да има време, кадър, реплика, надпис, звук, доказателство и отговорник за одобрение. Отбележи какво изисква клиентска проверка и какво е само предложение. Прочети целия ред на глас и виж дали оператор може да заснеме кадъра без допълнително гадаене.\n\nКритерий за приемане: Провери версията, сроковете, спецификацията и критериите за приемане.\n\nКогато пробата се провали:\nСимптом: Документът е една колона с диалог.\nКорекция: Предай една одобрена версия и добави коментар само за неуредените точки.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.\n\nАртефакт за снимачния сценарий: вържи всяка важна реплика към кадър, който я доказва; маркирай фактите за одобрение и надписите за гледане без звук. Прочети репликата на глас и прегледай кадъра без звук; ако се смени актьор, формат или платформа, провери отново дали обещанието и доказателството съвпадат."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подготви сценарий, готов за снимане“?","options":[{"id":"a","label":"Документът е една колона с диалог."},{"id":"b","label":"Подготви сценарий, който е достатъчно ясен, за да започне снимането: реплики, кадри, доказателства, звук, надписи, времетраене, права и отговорник за одобрение."},{"id":"c","label":"Достатъчно е да напишеш силна реплика; кадърът и доказателството се измислят по-късно."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Подготви сценарий, който е достатъчно ясен, за да започне снимането: реплики, кадри, доказателства, звук, надписи, времетраене, права и отговорник за одобрение. Слабият ход е: Документът е една колона с диалог. Операторът измисля кадри на място, а монтажистът не знае дали графиката съдържа проверен факт. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Предаването съдържа 00:00–00:03 ръце на колелото/звук на въртене/въпрос; 00:03–00:09 инструктор показва център/кратка реплика; 00:09–00:15 близък план на формата/етикет „материалите са включени“ след потвърждение; финал — актуален график и призив за действие. Списъкът посочва кой кадър се снима вертикално и кой факт чака клиента.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Документът е една колона с диалог."},{"id":"b","label":"Предай една одобрена версия и добави коментар само за неуредените точки."},{"id":"c","label":"Остави липсващия кадър или условие на монтажиста да го реши след снимането."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Предай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения. Грешният път — Документът е една колона с диалог. — оставя риска нерешен. Провери и границата: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подготви сценарий, готов за снимане“?","options":[{"id":"a","label":"Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран."},{"id":"b","label":"Документът е една колона с диалог."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подготви сценарий, който е достатъчно ясен, за да започне снимането: реплики, кадри, доказателства, звук, надписи, времетраене, права и отговорник за одобрение.","Първо: Раздели сценария на части и оцени времето с пробен прочит. После: Попълни паралелно картина, звук, надпис и доказателство.","Следи за грешния ход: Документът е една колона с диалог."],"nextStep":"Към своя проект прочети сценария на глас и провери кадъра без звук; съкрати повторението, не доказателството или условието. Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.","items":[{"id":"s2","text":"Попълни паралелно картина, звук, надпис и доказателство."},{"id":"s1","text":"Раздели сценария на части и оцени времето с пробен прочит."},{"id":"s4","text":"Провери версията, сроковете, спецификацията и критериите за приемане."},{"id":"s3","text":"Посочи права, хора, реквизит, място и резервен вариант."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Предай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения. Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Предаването съдържа 00:00–00:03 ръце на колелото/звук на въртене/въпрос; 00:03–00:09 инструктор показва център/кратка реплика; 00:09–00:15 близък план на формата/етикет „материалите са включени“ след потвърждение; финал — актуален график и призив за действие.\n\nПроменено условие: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Добави по-силно обещание, дори когато няма кадър или източник, който да го потвърди."},{"id":"b","label":"Предай една одобрена версия и добави коментар само за неуредените точки."},{"id":"a","label":"Документът е една колона с диалог."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Предай една одобрена версия и добави коментар само за неуредените точки. В началото на снимачния ден потвърди промени в дата, цена, наличност и разрешения. Границата тук е: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.\n\nПреди монтаж: прочети сценария на глас; гледай пробния кадър без звук; провери дали кадърът доказва репликата; виж дали призивът води точно към обещаната информация.\n\nРаботна карта за сценария: време; въпрос на зрителя; реплика; кадър, който я доказва; надпис; преход; призив за действие; факт или условие за одобрение. Ако кадърът не носи репликата, промени сценария преди снимането.\n\nКарта за работа — Подготви сценарий, готов за снимане\n1. Раздели сценария на части и оцени времето с пробен прочит.\n2. Попълни паралелно картина, звук, надпис и доказателство.\n3. Посочи права, хора, реквизит, място и резервен вариант.\n4. Провери версията, сроковете, спецификацията и критериите за приемане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-01","title":"Избери кадровата честота за движението и доставката","objective":"да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството","hook":"„24 срещу 60“ няма смисъл без въпрос какво се движи и къде ще се гледа.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„24 срещу 60“ няма смисъл без въпрос какво се движи и къде ще се гледа.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избирай кадрова честота според движението, светлината и начина на възпроизвеждане. 25 кадъра/секунда е често използван избор за европейски проект; 50/60 може да даде плавно движение или забавяне, ако проектът го поддържа.\n\nКамерата записва физически условия — движение, светлина, дистанция и звук. Смени една променлива, направи тест и прегледай файла, преди да решиш, че настройката е правилна.\n\nПроменяй една настройка наведнъж и пази референтен дубъл. Така ще знаеш дали фокусът, цветът, звукът или движението действително са се подобрили."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Кадровата честота определя колко различни момента се записват за секунда. Повече кадри означават повече данни и други възможности за движение, но не автоматично по-високо качество. Смяната между честоти може да създаде насичане или неестествено забавяне. Първо провери настройките на проекта и крайното място за публикуване.\n\nГраница на правилото: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи дали действието трябва да изглежда в реално време или забавено.\n2. Провери електрическото осветление и ограниченията на камерата.\n3. Настрой кадрите/секунда в камерата и проекта преди запис.\n4. Сними кратък тест и провери движението на реалния екран.\n\nСтоп-сигнал: Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът. Ако това се случи, приложи корекцията преди да продължиш: Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За говорещия инструктор е избран 25 кадъра/секунда и затвор 1/50 като начална настройка; за отделен кадър на пръстите, който ще се забави на 25 кадъра/секунда, записът е 50 кадъра/секунда с тест за светлина. Екипът не снима целия клип на 50, защото така губи избрания естествен ритъм и увеличава размера на файловете.\n\nРешение в този случай:\nЗапиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление.\n\nГраница на извода:\nНе смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."},"after":{"label":"По-доброто решение","text":"Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление.\n\nПреди да продължиш: Сними кратък тест и провери движението на реалния екран."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Избери кадровата честота според крайния монтаж. При 25 кадъра/секунда движение изглежда нормално; 50 кадъра/секунда може да се забави наполовина в проект 25, ако това е замисълът. Смеси честоти само със съзнателно решение как редакторът ще ги обработи и провери кратък кадър на целевия екран.\n\nКритерий за приемане: Сними кратък тест и провери движението на реалния екран.\n\nКогато пробата се провали:\nСимптом: Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът.\nКорекция: Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Избери кадровата честота за движението и доставката“?","options":[{"id":"a","label":"Избирай кадрова честота според движението, светлината и начина на възпроизвеждане."},{"id":"b","label":"Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Избирай кадрова честота според движението, светлината и начина на възпроизвеждане. 25 кадъра/секунда е често използван избор за европейски проект; 50/60 може да даде плавно движение или забавяне, ако проектът го поддържа. Слабият ход е: Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За говорещия инструктор е избран 25 кадъра/секунда и затвор 1/50 като начална настройка; за отделен кадър на пръстите, който ще се забави на 25 кадъра/секунда, записът е 50 кадъра/секунда с тест за светлина. Екипът не снима целия клип на 50, защото така губи избрания естествен ритъм и увеличава размера на файловете.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."},{"id":"b","label":"Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление. Грешният път — Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът. — оставя риска нерешен. Провери и границата: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Избери кадровата честота за движението и доставката“?","options":[{"id":"a","label":"Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж."},{"id":"b","label":"Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избирай кадрова честота според движението, светлината и начина на възпроизвеждане. 25 кадъра/секунда е често използван избор за европейски проект; 50/60 може да даде плавно движение или забавяне, ако проектът го поддържа.","Първо: Определи дали действието трябва да изглежда в реално време или забавено. После: Провери електрическото осветление и ограниченията на камерата.","Следи за грешния ход: Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.","items":[{"id":"s2","text":"Провери електрическото осветление и ограниченията на камерата."},{"id":"s1","text":"Определи дали действието трябва да изглежда в реално време или забавено."},{"id":"s4","text":"Сними кратък тест и провери движението на реалния екран."},{"id":"s3","text":"Настрой кадрите/секунда в камерата и проекта преди запис."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление. Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За говорещия инструктор е избран 25 кадъра/секунда и затвор 1/50 като начална настройка; за отделен кадър на пръстите, който ще се забави на 25 кадъра/секунда, записът е 50 кадъра/секунда с тест за светлина.\n\nПроменено условие: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Включваш най-високата стойност в менюто, без да знаеш дали монтажът ще се забавя, дали светлината ще мига и как ще се възпроизвежда файлът."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Запиши избора в листа за камера: честота, затвор, резолюция, баланс на бялото и режим. Тествай панорама и движение на ръцете при реалното осветление. Границата тук е: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.\n\nКарта за работа — Избери кадровата честота за движението и доставката\n1. Определи дали действието трябва да изглежда в реално време или забавено.\n2. Провери електрическото осветление и ограниченията на камерата.\n3. Настрой кадрите/секунда в камерата и проекта преди запис.\n4. Сними кратък тест и провери движението на реалния екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-02","title":"Настрой затвора според движението","objective":"да разпознаваш как времето на експонация влияе на размазването при движение","hook":"Стоп-кадърът е рязък, но всяко движение в готовото видео оставя неестествена следа.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разпознаваш как времето на експонация влияе на размазването при движение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Стоп-кадърът е рязък, но всяко движение в готовото видео оставя неестествена следа.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Настрой затвора според кадровата честота и характера на движението. Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"При 25 кадъра/секунда често започват от 1/50 секунда, при 30 кадъра/секунда — около 1/60. По-бързият затвор прави движението по-рязко и насечено; по-бавният добавя размазване, което може да скрива детайл. LED (светодиодни) лампи и екрани могат да пулсират при неподходяща комбинация със затвора и честотата на захранването — провери на място.\n\nГраница на правилото: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери кадри/секунда и зададената естетика на движението.\n2. Постави затвора като начална точка около двойната честота.\n3. Коригирай експозицията със светлина, диафрагма или ND, не със случайни промени.\n4. Запиши тест с панорама и осветлението включено; търси мигане.\n\nСтоп-сигнал: Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление. Ако това се случи, приложи корекцията преди да продължиш: Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Снимаш ръцете на колелото при 25 кадъра/секунда. На 1/50 движението изглежда естествено; при 1/250 глината и пръстите стават прекалено резки и серията изглежда накъсана. светодиодната лента мига, затова променяш честота/затвор след тест, вместо да приемеш, че всеки 1/50 ще е без трептене.\n\nРешение в този случай:\nКогато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място.\n\nГраница на извода:\nПри бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."},"after":{"label":"По-доброто решение","text":"Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място.\n\nПреди да продължиш: Запиши тест с панорама и осветлението включено; търси мигане."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"При 25 кадъра/секунда 1/50 секунда е обичайна отправна точка за естествено размазване, не задължителен закон. По-късият затвор прави движението рязко и насечено; по-дългият го размазва. Ако лампа трепти, заснеми тест в помещението и провери съвместимостта с честотата на осветлението.\n\nКритерий за приемане: Запиши тест с панорама и осветлението включено; търси мигане.\n\nКогато пробата се провали:\nСимптом: Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление.\nКорекция: Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Настрой затвора според движението“?","options":[{"id":"a","label":"Настрой затвора според кадровата честота и характера на движението."},{"id":"b","label":"Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Настрой затвора според кадровата честота и характера на движението. Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон. Слабият ход е: Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Снимаш ръцете на колелото при 25 кадъра/секунда. На 1/50 движението изглежда естествено; при 1/250 глината и пръстите стават прекалено резки и серията изглежда накъсана. светодиодната лента мига, затова променяш честота/затвор след тест, вместо да приемеш, че всеки 1/50 ще е без трептене.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."},{"id":"b","label":"Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място. Грешният път — Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление. — оставя риска нерешен. Провери и границата: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Настрой затвора според движението“?","options":[{"id":"a","label":"При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор."},{"id":"b","label":"Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Настрой затвора според кадровата честота и характера на движението. Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.","Първо: Избери кадри/секунда и зададената естетика на движението. После: Постави затвора като начална точка около двойната честота.","Следи за грешния ход: Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.","items":[{"id":"s3","text":"Коригирай експозицията със светлина, диафрагма или ND, не със случайни промени."},{"id":"s2","text":"Постави затвора като начална точка около двойната честота."},{"id":"s1","text":"Избери кадри/секунда и зададената естетика на движението."},{"id":"s4","text":"Запиши тест с панорама и осветлението включено; търси мигане."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място. При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Снимаш ръцете на колелото при 25 кадъра/секунда.\n\nПроменено условие: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място."},{"id":"b","label":"Вдигаш затвора, за да затъмниш изображението, без да провериш какво става с движението и светодиодното осветление."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Когато затворът трябва да остане постоянен, контролирай светлината с експозиционни средства и тествай всяка комбинация на конкретното място. Границата тук е: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.\n\nКарта за работа — Настрой затвора според движението\n1. Избери кадри/секунда и зададената естетика на движението.\n2. Постави затвора като начална точка около двойната честота.\n3. Коригирай експозицията със светлина, диафрагма или ND, не със случайни промени.\n4. Запиши тест с панорама и осветлението включено; търси мигане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-03","title":"Експонирай чисто преди да вдигаш ISO","objective":"да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина","hook":"Подекспонираното лице не става чисто само защото го изсветлиш в монтажа.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Подекспонираното лице не става чисто само защото го изсветлиш в монтажа.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Постигни чиста експозиция с наличната светлина и избрани настройки, преди да вдигаш ISO или да разчиташ на спасение в монтажа."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Експозицията включва яркост, детайл в светлите части и шум в сенките. Прекалено тъмният запис, повдигнат после, често разкрива шум и цветни петна; изгорелите светли части не винаги могат да се върнат. Следи хистограма, зебра или waveform монитор (графика на сигнала), ако камерата ги има, и проверявай лицето, а не само екрана.\n\nГраница на правилото: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Оценяваш експозицията само по яркостта на LCD екрана на открито. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Настрой кадрова честота и затвор за движението.\n2. Постави светлина така, че важните тонове да са отчетливи.\n3. Следи светлите части и сенките с наличните инструменти.\n4. Повиши ISO само колкото е нужно и запиши тест за шум.\n\nСтоп-сигнал: Оценяваш експозицията само по яркостта на LCD екрана на открито. Файлът после се оказва тъмен, а корекцията руши сенките. Ако това се случи, приложи корекцията преди да продължиш: Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"До прозореца лицето на инструктора е тъмно, докато отвън всичко е ярко. Ако увеличиш ISO значително, сенките ще станат шумни. Завърташ човека към прозореца, добавяш отражател от другата страна и леко намаляваш експозицията, за да запазиш прозоречния детайл.\n\nРешение в този случай:\nПровери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек.\n\nГраница на извода:\nПравилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Оценяваш експозицията само по яркостта на LCD екрана на открито. Файлът после се оказва тъмен, а корекцията руши сенките."},"after":{"label":"По-доброто решение","text":"Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек.\n\nПреди да продължиш: Повиши ISO само колкото е нужно и запиши тест за шум."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Следи светлите части, преди да вдигнеш яркостта на екрана. Хистограмата показва разпределение, зебрата сигнализира избрани нива, а waveform показва светлинните стойности по кадъра; нито един инструмент не замества прегледа на лице и важен предмет. Ако сенките се рушат, добави светлина или приближи източника.\n\nКритерий за приемане: Повиши ISO само колкото е нужно и запиши тест за шум.\n\nКогато пробата се провали:\nСимптом: Оценяваш експозицията само по яркостта на LCD екрана на открито.\nКорекция: Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Експонирай чисто преди да вдигаш ISO“?","options":[{"id":"a","label":"Оценяваш експозицията само по яркостта на LCD екрана на открито."},{"id":"b","label":"Постигни чиста експозиция с наличната светлина и избрани настройки, преди да вдигаш ISO или да разчиташ на спасение в монтажа."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Постигни чиста експозиция с наличната светлина и избрани настройки, преди да вдигаш ISO или да разчиташ на спасение в монтажа. Слабият ход е: Оценяваш експозицията само по яркостта на LCD екрана на открито. Файлът после се оказва тъмен, а корекцията руши сенките. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: До прозореца лицето на инструктора е тъмно, докато отвън всичко е ярко. Ако увеличиш ISO значително, сенките ще станат шумни. Завърташ човека към прозореца, добавяш отражател от другата страна и леко намаляваш експозицията, за да запазиш прозоречния детайл.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия."},{"id":"b","label":"Оценяваш експозицията само по яркостта на LCD екрана на открито."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек. Грешният път — Оценяваш експозицията само по яркостта на LCD екрана на открито. — оставя риска нерешен. Провери и границата: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Експонирай чисто преди да вдигаш ISO“?","options":[{"id":"a","label":"Оценяваш експозицията само по яркостта на LCD екрана на открито."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Правилната експозиция зависи от сцената и естетиката."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Постигни чиста експозиция с наличната светлина и избрани настройки, преди да вдигаш ISO или да разчиташ на спасение в монтажа.","Първо: Настрой кадрова честота и затвор за движението. После: Постави светлина така, че важните тонове да са отчетливи.","Следи за грешния ход: Оценяваш експозицията само по яркостта на LCD екрана на открито."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.","items":[{"id":"s3","text":"Следи светлите части и сенките с наличните инструменти."},{"id":"s4","text":"Повиши ISO само колкото е нужно и запиши тест за шум."},{"id":"s2","text":"Постави светлина така, че важните тонове да са отчетливи."},{"id":"s1","text":"Настрой кадрова честота и затвор за движението."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек. Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: До прозореца лицето на инструктора е тъмно, докато отвън всичко е ярко.\n\nПроменено условие: Правилната експозиция зависи от сцената и естетиката.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия."},{"id":"a","label":"Оценяваш експозицията само по яркостта на LCD екрана на открито."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Провери тестов файл на по-голям екран и гледай кожата и важния обект при същите условия. Използвай waveform монитор (графика на сигнала)/зебра като ориентир, а не универсална стойност за всеки човек. Границата тук е: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.\n\nКарта за работа — Експонирай чисто преди да вдигаш ISO\n1. Настрой кадрова честота и затвор за движението.\n2. Постави светлина така, че важните тонове да са отчетливи.\n3. Следи светлите части и сенките с наличните инструменти.\n4. Повиши ISO само колкото е нужно и запиши тест за шум.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-04","title":"Дръж фокуса върху важното","objective":"да избираш между автофокус, заключен фокус и ръчен фокус според сцената","hook":"Камерата следи ръката зад продукта, докато зрителят трябва да вижда лицето.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш между автофокус, заключен фокус и ръчен фокус според сцената. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата следи ръката зад продукта, докато зрителят трябва да вижда лицето.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избери автофокус, заключен или ръчен фокус според движението и повторяемостта на сцената; провери точката на фокус върху кадъра, който ще се използва."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Следящият автофокус помага, когато говорителят или предметът се движи; може да „лови“ фона, ако преминава друг обект или контрастът е нисък. За статична демонстрация заключеният фокус може да бъде по-надежден. При ръчен фокус използвай увеличен преглед и маркирай позицията, особено ако човекът се движи към/от камерата.\n\nГраница на правилото: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи кой обект трябва да остане рязък през всяка част.\n2. Избери режим и тествай с истинското движение на човека.\n3. Провери фокус в началото, средата и края на дубъла.\n4. Запиши резервен дубъл и не мести предметите след заключване.\n\nСтоп-сигнал: Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек. Ако това се случи, приложи корекцията преди да продължиш: Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Инструкторът стои на фиксирано място и показва центъра на колелото. Камерата превключва към ръцете, когато те влязат пред лицето, затова екипът тества проследяването. За близкия детайл използва фиксирана дистанция и ръчен фокус; отделно записва лицето, за да няма търсене на фокус в решаващия момент.\n\nРешение в този случай:\nУвеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието.\n\nГраница на извода:\nЛицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."},"after":{"label":"По-доброто решение","text":"Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието.\n\nПреди да продължиш: Запиши резервен дубъл и не мести предметите след заключване."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Избери непрекъснат фокус за движение само ако системата следи правилния обект; заключи фокуса, когато сцената е предвидима. Фокусният пик подчертава ръбове, но не гарантира, че очите или детайлът са остри. Запиши тест с движението на ръцете и увеличи кадъра при проверка.\n\nКритерий за приемане: Запиши резервен дубъл и не мести предметите след заключване.\n\nКогато пробата се провали:\nСимптом: Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек.\nКорекция: Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Дръж фокуса върху важното“?","options":[{"id":"a","label":"Избери автофокус, заключен или ръчен фокус според движението и повторяемостта на сцената; провери точката на фокус върху кадъра, който ще се използва."},{"id":"b","label":"Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Избери автофокус, заключен или ръчен фокус според движението и повторяемостта на сцената; провери точката на фокус върху кадъра, който ще се използва. Слабият ход е: Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Инструкторът стои на фиксирано място и показва центъра на колелото. Камерата превключва към ръцете, когато те влязат пред лицето, затова екипът тества проследяването. За близкия детайл използва фиксирана дистанция и ръчен фокус; отделно записва лицето, за да няма търсене на фокус в решаващия момент.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."},{"id":"b","label":"Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието. Грешният път — Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек. — оставя риска нерешен. Провери и границата: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Дръж фокуса върху важното“?","options":[{"id":"a","label":"Лицевият автофокус зависи от модела и настройките."},{"id":"b","label":"Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избери автофокус, заключен или ръчен фокус според движението и повторяемостта на сцената; провери точката на фокус върху кадъра, който ще се използва.","Първо: Определи кой обект трябва да остане рязък през всяка част. После: Избери режим и тествай с истинското движение на човека.","Следи за грешния ход: Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.","items":[{"id":"s1","text":"Определи кой обект трябва да остане рязък през всяка част."},{"id":"s4","text":"Запиши резервен дубъл и не мести предметите след заключване."},{"id":"s3","text":"Провери фокус в началото, средата и края на дубъла."},{"id":"s2","text":"Избери режим и тествай с истинското движение на човека."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието. Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Инструкторът стои на фиксирано място и показва центъра на колелото.\n\nПроменено условие: Лицевият автофокус зависи от модела и настройките.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Оставяш автофокуса да прехвърля от ръцете към фона, без да забележиш, после избираш кадър, в който критичният детайл е мек."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Увеличи кадъра и провери рязкостта на важния детайл, не само че зелена рамка е мигнала. Ако режимът е несигурен, промени сцената или разстоянието. Границата тук е: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.\n\nКарта за работа — Дръж фокуса върху важното\n1. Определи кой обект трябва да остане рязък през всяка част.\n2. Избери режим и тествай с истинското движение на човека.\n3. Провери фокус в началото, средата и края на дубъла.\n4. Запиши резервен дубъл и не мести предметите след заключване.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-05","title":"Заключи баланса на бялото за последователни цветове","objective":"да поддържаш постоянен цвят на кожата и предметите между дублите","hook":"Камерата сменя топлия и студения тон, когато човек се движи през различно осветени места.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поддържаш постоянен цвят на кожата и предметите между дублите. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата сменя топлия и студения тон, когато човек се движи през различно осветени места.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Заключи баланса на бялото за последователен цвят между кадрите. Автоматичният баланс може да променя оттенъка в средата на дубъла, особено при смесено осветление."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Настройката описва как камерата тълкува неутралното бяло при източника на светлина; тя не поправя лоша експозиция или различни цветове на лампите. Използвай сива карта/бяла карта като ориентир под светлината на обекта и направи персонална настройка. При смесени лампи първо реши коя светлина доминира или намали нежеланата.\n\nГраница на правилото: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Постави човека/предмета в реалната светлина на сцената.\n2. Използвай карта или фиксиран готов режим или стойност в Kelvin като отправна точка.\n3. Заключи баланса и снимай референсен кадър.\n4. Сравни два кадъра при същото осветление и коригирай източника.\n\nСтоп-сигнал: Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят. Ако това се случи, приложи корекцията преди да продължиш: Запази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"В широкия кадър автоматичният баланс е топъл заради лампите; при близкия план камерата вижда повече дневна светлина и кожата става синкава. Екипът изключва една смесена лампа, измерва карта на мястото на лицето, заключва настройката и снима двата плана без промяна.\n\nРешение в този случай:\nЗапази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър.\n\nГраница на извода:\nПерсоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."},"after":{"label":"По-доброто решение","text":"Запази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър.\n\nПреди да продължиш: Сравни два кадъра при същото осветление и коригирай източника."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Смеси различни източници на светлина само след като видиш цвета на кожата и бял предмет. Автоматичният баланс може да се променя вътре в дубъла; зададена стойност или сива карта улеснява съвпадането между кадри. Запиши настройката, преди да смениш локация.\n\nКритерий за приемане: Сравни два кадъра при същото осветление и коригирай източника.\n\nКогато пробата се провали:\nСимптом: Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят.\nКорекция: Запази карта/референция за основната сцена и снимай тест преди ролките.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Заключи баланса на бялото за последователни цветове“?","options":[{"id":"a","label":"Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."},{"id":"b","label":"Заключи баланса на бялото за последователен цвят между кадрите."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Заключи баланса на бялото за последователен цвят между кадрите. Автоматичният баланс може да променя оттенъка в средата на дубъла, особено при смесено осветление. Слабият ход е: Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: В широкия кадър автоматичният баланс е топъл заради лампите; при близкия план камерата вижда повече дневна светлина и кожата става синкава. Екипът изключва една смесена лампа, измерва карта на мястото на лицето, заключва настройката и снима двата плана без промяна.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Запази карта/референция за основната сцена и снимай тест преди ролките."},{"id":"b","label":"Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Запази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър. Грешният път — Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят. — оставя риска нерешен. Провери и границата: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Заключи баланса на бялото за последователни цветове“?","options":[{"id":"a","label":"Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Заключи баланса на бялото за последователен цвят между кадрите. Автоматичният баланс може да променя оттенъка в средата на дубъла, особено при смесено осветление.","Първо: Постави човека/предмета в реалната светлина на сцената. После: Използвай карта или фиксиран готов режим или стойност в Kelvin като отправна точка.","Следи за грешния ход: Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.","items":[{"id":"s2","text":"Използвай карта или фиксиран готов режим или стойност в Kelvin като отправна точка."},{"id":"s4","text":"Сравни два кадъра при същото осветление и коригирай източника."},{"id":"s1","text":"Постави човека/предмета в реалната светлина на сцената."},{"id":"s3","text":"Заключи баланса и снимай референсен кадър."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Запази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър. Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: В широкия кадър автоматичният баланс е топъл заради лампите; при близкия план камерата вижда повече дневна светлина и кожата става синкава.\n\nПроменено условие: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Запази карта/референция за основната сцена и снимай тест преди ролките."},{"id":"b","label":"Използваш автоматичен баланс на бялото във всеки дубъл и очакваш монтажа да направи еднакви кадри, въпреки че източниците се сменят."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Запази карта/референция за основната сцена и снимай тест преди ролките. Ако светлината се промени, отбележи нова настройка и направи нов референсен кадър. Границата тук е: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.\n\nКарта за работа — Заключи баланса на бялото за последователни цветове\n1. Постави човека/предмета в реалната светлина на сцената.\n2. Използвай карта или фиксиран готов режим или стойност в Kelvin като отправна точка.\n3. Заключи баланса и снимай референсен кадър.\n4. Сравни два кадъра при същото осветление и коригирай източника.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-06","title":"Подготви светлина, фон и звук в стаята","objective":"да използваш наличната светлина и място за четим образ и разбираем глас","hook":"Камерата записва всичко в стаята: плоска светлина, претрупан фон и ехо също влизат в кадъра.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш наличната светлина и място за четим образ и разбираем глас. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата записва всичко в стаята: плоска светлина, претрупан фон и ехо също влизат в кадъра.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Подготви мястото така, че светлината, фонът и звукът да помагат на основното действие. Качеството на звука зависи силно от микрофона и разстоянието му до говорителя."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Първо изключи или премести източника на шум, ако е възможно; постави микрофона близо, но извън кадъра, и слушай през слушалки. Твърдите стени създават отражения; завеси, дрехи и меки материали могат да намалят ехото. За светлина избери посока и контраст, не просто яркост. Запиши тих запис на помещението за монтаж.\n\nГраница на правилото: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Огледай светлината, отраженията, шумовете и захранването.\n2. Постави микрофона близо до устата и обезопаси кабела.\n3. Направи тестов запис с реалния фон и прослушай със слушалки.\n4. Подреди фон и светлина, после запиши тих запис на помещението.\n\nСтоп-сигнал: Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после. Ехото и помещението остават по-силни от гласа. Ако това се случи, приложи корекцията преди да продължиш: Запиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Аспирацията в ателието прави постоянен шум, а престилката докосва микрофона. Изключваш аспирацията само за репликата след съгласуване; микрофонът се премества на яката с резервна примка, кабелът се фиксира. Тестът включва и колелото, което ще се чува в демонстрацията. Кадърът оставя лицето отделено от натрупаните инструменти.\n\nРешение в този случай:\nЗапиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане.\n\nГраница на извода:\nНе спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после. Ехото и помещението остават по-силни от гласа."},"after":{"label":"По-доброто решение","text":"Запиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане.\n\nПреди да продължиш: Подреди фон и светлина, после запиши тих запис на помещението."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Голям и близък източник обикновено прави сенките по-меки; отдалечаването му променя както мекотата, така и яркостта. Светлината не компенсира микрофон, поставен твърде далеч. Направи тест за лице, ръце, фон и шум в стаята. Не мести кабели и стойки през прохода, по който работят хората.\n\nКритерий за приемане: Подреди фон и светлина, после запиши тих запис на помещението.\n\nКогато пробата се провали:\nСимптом: Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после.\nКорекция: Запиши 10–15 секунди тест, после слушай със слушалки през тишина.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Подготви светлина, фон и звук в стаята“?","options":[{"id":"a","label":"Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после."},{"id":"b","label":"Подготви мястото така, че светлината, фонът и звукът да помагат на основното действие."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Подготви мястото така, че светлината, фонът и звукът да помагат на основното действие. Качеството на звука зависи силно от микрофона и разстоянието му до говорителя. Слабият ход е: Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после. Ехото и помещението остават по-силни от гласа. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Аспирацията в ателието прави постоянен шум, а престилката докосва микрофона. Изключваш аспирацията само за репликата след съгласуване; микрофонът се премества на яката с резервна примка, кабелът се фиксира. Тестът включва и колелото, което ще се чува в демонстрацията. Кадърът оставя лицето отделено от натрупаните инструменти.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Запиши 10–15 секунди тест, после слушай със слушалки през тишина."},{"id":"b","label":"Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Запиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане. Грешният път — Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после. — оставя риска нерешен. Провери и границата: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Подготви светлина, фон и звук в стаята“?","options":[{"id":"a","label":"Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Подготви мястото така, че светлината, фонът и звукът да помагат на основното действие. Качеството на звука зависи силно от микрофона и разстоянието му до говорителя.","Първо: Огледай светлината, отраженията, шумовете и захранването. После: Постави микрофона близо до устата и обезопаси кабела.","Следи за грешния ход: Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.","items":[{"id":"s1","text":"Огледай светлината, отраженията, шумовете и захранването."},{"id":"s3","text":"Направи тестов запис с реалния фон и прослушай със слушалки."},{"id":"s2","text":"Постави микрофона близо до устата и обезопаси кабела."},{"id":"s4","text":"Подреди фон и светлина, после запиши тих запис на помещението."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Запиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане. Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Аспирацията в ателието прави постоянен шум, а престилката докосва микрофона.\n\nПроменено условие: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Запиши 10–15 секунди тест, после слушай със слушалки през тишина."},{"id":"a","label":"Разчиташ на вградения микрофон на камерата от три метра и усилваш звука после."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Запиши 10–15 секунди тест, после слушай със слушалки през тишина. Ако гласът е неразбираем, промени микрофон/позиция/среда преди снимане. Границата тук е: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.\n\nПреди да изтриеш теста: гледай фокус и движение на голям екран; слушай през слушалки; сравни цветовете между дублите; отвори изнесения файл на целевия телефон.\n\nАко преместиш снимането в друга стая или смениш камера/телефон, повтори теста. Не пренасяй стойностите по памет: друга светлина, дистанция и сензор променят резултата.\n\nКарта за работа — Подготви светлина, фон и звук в стаята\n1. Огледай светлината, отраженията, шумовете и захранването.\n2. Постави микрофона близо до устата и обезопаси кабела.\n3. Направи тестов запис с реалния фон и прослушай със слушалки.\n4. Подреди фон и светлина, после запиши тих запис на помещението.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-07","title":"Запази файл, който отговаря на целевия екран","objective":"да съчетаеш резолюция, кадрова честота, формат и качество при експортиране","hook":"„Най-висок bitrate“ не поправя фокус, светлина или грешен формат.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съчетаеш резолюция, кадрова честота, формат и качество при експортиране. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Най-висок bitrate“ не поправя фокус, светлина или грешен формат.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Изнеси файл, който отговаря на задачата и целевия екран: правилни размери, честота, кодек, звук, цвят и проверка след компресията."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Преди експорт провери спецификацията на конкретната платформа, после настрой проект и изход; не променяй кадрите без причина. За YouTube SDR официалните указания препоръчват MP4/H.264, прогресивно сканиране и кадрова честота като записаната; за 1080p посочват ориентир 8 Mbps при стандартни честоти и 12 Mbps при високи. Това е ориентир за този канал, не магическа стойност за всички платформи.\n\nГраница на правилото: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Потвърди целевата платформа, ориентация, резолюция и максимална дължина.\n2. Сравни изхода с източника: кадри/секунда, цвят, аудио и пропорции.\n3. Експортирай тестов сегмент и провери текст, движение и звук на телефон.\n4. Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно.\n\nСтоп-сигнал: Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл. Размерът става огромен без автоматичен видим плюс. Ако това се случи, приложи корекцията преди да продължиш: Проверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Клипът е заснет вертикално 1080×1920 при 25 кадъра/секунда за мобилен feed. Изходът запазва тези пропорции и кадрова честота, H.264/MP4 е избран за съвместимост, а AAC 48 kHz носи стереозвук. На YouTube файлът се тества против актуалната таблица; за друга платформа профилът се проверява отново.\n\nРешение в този случай:\nПроверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията.\n\nГраница на извода:\nКодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл. Размерът става огромен без автоматичен видим плюс."},"after":{"label":"По-доброто решение","text":"Проверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията.\n\nПреди да продължиш: Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Експортът започва от файла и целевата платформа, не от най-високата цифра в менюто. Сравни резолюция, пропорция, кадри/секунда, цветово пространство и звук с оригинала; после гледай тестовия файл през телефона. Препоръката за YouTube не е универсален профил за всяко приложение.\n\nКритерий за приемане: Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно.\n\nКогато пробата се провали:\nСимптом: Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл.\nКорекция: Проверявай файла след експорт, не само настройките в диалога.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Запази файл, който отговаря на целевия екран“?","options":[{"id":"a","label":"Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Изнеси файл, който отговаря на задачата и целевия екран: правилни размери, честота, кодек, звук, цвят и проверка след компресията."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Изнеси файл, който отговаря на задачата и целевия екран: правилни размери, честота, кодек, звук, цвят и проверка след компресията. Слабият ход е: Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл. Размерът става огромен без автоматичен видим плюс. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Клипът е заснет вертикално 1080×1920 при 25 кадъра/секунда за мобилен feed. Изходът запазва тези пропорции и кадрова честота, H.264/MP4 е избран за съвместимост, а AAC 48 kHz носи стереозвук. На YouTube файлът се тества против актуалната таблица; за друга платформа профилът се проверява отново.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл."},{"id":"b","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."},{"id":"c","label":"Проверявай файла след експорт, не само настройките в диалога."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Проверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията. Грешният път — Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл. — оставя риска нерешен. Провери и границата: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Запази файл, който отговаря на целевия екран“?","options":[{"id":"a","label":"Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл."},{"id":"b","label":"Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Изнеси файл, който отговаря на задачата и целевия екран: правилни размери, честота, кодек, звук, цвят и проверка след компресията.","Първо: Потвърди целевата платформа, ориентация, резолюция и максимална дължина. После: Сравни изхода с източника: кадри/секунда, цвят, аудио и пропорции.","Следи за грешния ход: Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.","items":[{"id":"s2","text":"Сравни изхода с източника: кадри/секунда, цвят, аудио и пропорции."},{"id":"s4","text":"Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно."},{"id":"s3","text":"Експортирай тестов сегмент и провери текст, движение и звук на телефон."},{"id":"s1","text":"Потвърди целевата платформа, ориентация, резолюция и максимална дължина."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Проверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията. Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Клипът е заснет вертикално 1080×1920 при 25 кадъра/секунда за мобилен feed.\n\nПроменено условие: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Избираш „4K, максимум“ за всичко, хоча исходникът е 1080p и мобилният зрител ще гледа компресиран файл."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Проверявай файла след експорт, не само настройките в диалога."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Проверявай файла след експорт, не само настройките в диалога. Виж цветни ленти, субтитри, липсващ звук, края на клипа и дали платформата е променила ориентацията. Границата тук е: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.\n\nКогато клипът не минава проверка, отдели запис, монтаж и експорт: отвори оригинала, после кадъра в проекта, после финалния файл. Така няма да преснимаш проблем, възникнал при експорта.\n\nПоследен тест: сравни оригиналния запис с финалния файл на целевия телефон. Провери движение, фокус, цвят, четим текст и звук; ако проблемът се вижда само във финала, поправи експорта, не преснимай сцената.\n\nКарта за работа — Запази файл, който отговаря на целевия екран\n1. Потвърди целевата платформа, ориентация, резолюция и максимална дължина.\n2. Сравни изхода с източника: кадри/секунда, цвят, аудио и пропорции.\n3. Експортирай тестов сегмент и провери текст, движение и звук на телефон.\n4. Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Recommended upload encoding settings: https://support.google.com/youtube/answer/1722171?hl=en (провери актуалната версия преди публикуване)."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-08","title":"Кадрирай за вертикално и хоризонтално гледане","objective":"да планираш композицията така, че основният смисъл да остане видим в избрания формат","hook":"Изрязаният кадър може да отреже не само рамката, а и важната информация.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да планираш композицията така, че основният смисъл да остане видим в избрания формат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Изрязаният кадър може да отреже не само рамката, а и важната информация.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Кадрирай с мисъл за хоризонтално и вертикално гледане още на снимачния етап. Не разчитай, че централното автоматично изрязване ще запази ръце, инструмент и контекст."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Основната информация трябва да остане в рамката и след прекадриране. Запиши отделни версии или използвай отворено кадриране, ако проектът и камерата го позволяват. Остави място за надписи и интерфейсни елементи; държи очите, ръцете и ключовия инструмент далеч от ръбовете.\n\nГраница на правилото: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи главен формат и вторични места за публикуване.\n2. Планирай безопасна рамка/зона за ръце, лице, графика и субтитри.\n3. Сними тестов кадър и прекадрирай за всяко отношение на страните.\n4. Провери двата файла в реалните приложения и на телефон.\n\nСтоп-сигнал: Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16. Ако това се случи, приложи корекцията преди да продължиш: Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Инструкторът демонстрира движение с ръце по широк работен плот. В хоризонталния кадър се виждат майстор и ученик; във вертикалния — само ръцете и центърът. Екипът снима отделен близък план за вертикалната версия, вместо да отреже обясняващата ръка.\n\nРешение в този случай:\nСнимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец.\n\nГраница на извода:\nТочната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."},"after":{"label":"По-доброто решение","text":"Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец.\n\nПреди да продължиш: Провери двата файла в реалните приложения и на телефон."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Ако едно видео трябва да се използва в 16:9 и 9:16, реши го преди снимането. Остави място около ръцете, предмета и надписа; широкият кадър често не съдържа достатъчно пиксели за чисто вертикално изрязване. Заснеми отделен близък план вместо да разчиташ на автоматично прекадриране.\n\nКритерий за приемане: Провери двата файла в реалните приложения и на телефон.\n\nКогато пробата се провали:\nСимптом: Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16.\nКорекция: Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Кадрирай за вертикално и хоризонтално гледане“?","options":[{"id":"a","label":"Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."},{"id":"b","label":"Кадрирай с мисъл за хоризонтално и вертикално гледане още на снимачния етап."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Кадрирай с мисъл за хоризонтално и вертикално гледане още на снимачния етап. Не разчитай, че централното автоматично изрязване ще запази ръце, инструмент и контекст. Слабият ход е: Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Инструкторът демонстрира движение с ръце по широк работен плот. В хоризонталния кадър се виждат майстор и ученик; във вертикалния — само ръцете и центърът. Екипът снима отделен близък план за вертикалната версия, вместо да отреже обясняващата ръка.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."},{"id":"b","label":"Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец. Грешният път — Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16. — оставя риска нерешен. Провери и границата: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Кадрирай за вертикално и хоризонтално гледане“?","options":[{"id":"a","label":"Точната safe зона зависи от интерфейса, бутони и устройство."},{"id":"b","label":"Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Кадрирай с мисъл за хоризонтално и вертикално гледане още на снимачния етап. Не разчитай, че централното автоматично изрязване ще запази ръце, инструмент и контекст.","Първо: Определи главен формат и вторични места за публикуване. После: Планирай безопасна рамка/зона за ръце, лице, графика и субтитри.","Следи за грешния ход: Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.","items":[{"id":"s3","text":"Сними тестов кадър и прекадрирай за всяко отношение на страните."},{"id":"s4","text":"Провери двата файла в реалните приложения и на телефон."},{"id":"s1","text":"Определи главен формат и вторични места за публикуване."},{"id":"s2","text":"Планирай безопасна рамка/зона за ръце, лице, графика и субтитри."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец. Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Инструкторът демонстрира движение с ръце по широк работен плот.\n\nПроменено условие: Точната safe зона зависи от интерфейса, бутони и устройство.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор."},{"id":"b","label":"Поставяш важна реплика вляво, защото има място в 16:9; след изрязване тя изчезва в 9:16."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Снимай два кадъра с различен акцент или използвай ръководство за безопасна рамка на монитор. Провери финалните субтитри върху всеки кадър, не само в монтажния прозорец. Границата тук е: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.\n\nКарта за работа — Кадрирай за вертикално и хоризонтално гледане\n1. Определи главен формат и вторични места за публикуване.\n2. Планирай безопасна рамка/зона за ръце, лице, графика и субтитри.\n3. Сними тестов кадър и прекадрирай за всяко отношение на страните.\n4. Провери двата файла в реалните приложения и на телефон.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-09","title":"Различавай фокусно разстояние и перспектива","objective":"да избираш позиция и обектив според пространството и характера на кадъра","hook":"Близкият портрет с широкоъгълен обектив може да преувеличи носа и да направи лицето непривично.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш позиция и обектив според пространството и характера на кадъра. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Близкият портрет с широкоъгълен обектив може да преувеличи носа и да направи лицето непривично.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Различавай фокусното разстояние от перспективата. Перспективата променя отношението между близки и далечни обекти основно когато смениш позицията на камерата."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Късо фокусно разстояние дава по-широк зрителен ъгъл; ако стоиш много близо, разликата между нос и ухо или ръце и фон изглежда силно преувеличена. За по-стегнат план с по-малко изкривяване отдалечи камерата и избери по-дълго фокусно разстояние. Не движи само пръстена на обектива и не очаквай същата перспектива.\n\nГраница на правилото: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи желаната рамка и разстоянието до основния обект.\n2. Избери позиция според отношението на предмета и фона.\n3. Използвай фокусно разстояние, което улавя нужния ъгъл от тази позиция.\n4. Провери лицето/обекта по краищата и при близък план.\n\nСтоп-сигнал: Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта. Ако това се случи, приложи корекцията преди да продължиш: Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Снимаш ръце и чаша с широкия край на телефона много близо; чашата изглежда несъразмерна и пръстите се разтягат. Отдалечаваш камерата и използваш по-тясно зрително поле, за да запазиш по-естествената форма. Фонът визуално се приближава, защото камерата се е преместила, а не защото обективът магически е променил пространството.\n\nРешение в този случай:\nНаправи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило.\n\nГраница на извода:\nТелефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."},"after":{"label":"По-доброто решение","text":"Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило.\n\nПреди да продължиш: Провери лицето/обекта по краищата и при близък план."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Перспективата се променя, когато преместиш камерата спрямо обекта; фокусното разстояние променя колко от сцената влиза в кадъра. Не сменяй позицията без да провериш размера на предметите един спрямо друг. Сними сравнение от различни дистанции и кадрирай сходно, за да видиш ефекта.\n\nКритерий за приемане: Провери лицето/обекта по краищата и при близък план.\n\nКогато пробата се провали:\nСимптом: Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта.\nКорекция: Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Различавай фокусно разстояние и перспектива“?","options":[{"id":"a","label":"Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Различавай фокусното разстояние от перспективата."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Различавай фокусното разстояние от перспективата. Перспективата променя отношението между близки и далечни обекти основно когато смениш позицията на камерата. Слабият ход е: Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Снимаш ръце и чаша с широкия край на телефона много близо; чашата изглежда несъразмерна и пръстите се разтягат. Отдалечаваш камерата и използваш по-тясно зрително поле, за да запазиш по-естествената форма. Фонът визуално се приближава, защото камерата се е преместила, а не защото обективът магически е променил пространството.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер."},{"id":"b","label":"Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило. Грешният път — Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта. — оставя риска нерешен. Провери и границата: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Различавай фокусно разстояние и перспектива“?","options":[{"id":"a","label":"Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Телефоните могат да превключват между отделни модули и цифрово изрязване."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Различавай фокусното разстояние от перспективата. Перспективата променя отношението между близки и далечни обекти основно когато смениш позицията на камерата.","Първо: Определи желаната рамка и разстоянието до основния обект. После: Избери позиция според отношението на предмета и фона.","Следи за грешния ход: Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.","items":[{"id":"s4","text":"Провери лицето/обекта по краищата и при близък план."},{"id":"s1","text":"Определи желаната рамка и разстоянието до основния обект."},{"id":"s2","text":"Избери позиция според отношението на предмета и фона."},{"id":"s3","text":"Използвай фокусно разстояние, което улавя нужния ъгъл от тази позиция."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило. Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Снимаш ръце и чаша с широкия край на телефона много близо; чашата изглежда несъразмерна и пръстите се разтягат.\n\nПроменено условие: Телефоните могат да превключват между отделни модули и цифрово изрязване.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер."},{"id":"a","label":"Казваш „телеобективът компресира перспективата“ без да обясниш, че операторът обикновено се отдалечава, за да запази размера на обекта."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи два теста: една позиция с две фокусни разстояния и две позиции с кадър, приблизително еднакъв по размер. Сравнението показва кое се е променило. Границата тук е: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.\n\nКарта за работа — Различавай фокусно разстояние и перспектива\n1. Определи желаната рамка и разстоянието до основния обект.\n2. Избери позиция според отношението на предмета и фона.\n3. Използвай фокусно разстояние, което улавя нужния ъгъл от тази позиция.\n4. Провери лицето/обекта по краищата и при близък план.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-10","title":"Отдели субекта от фона без софтуерен трик","objective":"да използваш разстояние, кадриране и светлина за по-ясни планове","hook":"Портретният режим прави косата на човек назъбена, а фонът пак остава разсейващ.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш разстояние, кадриране и светлина за по-ясни планове. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Портретният режим прави косата на човек назъбена, а фонът пак остава разсейващ.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Отделяй субекта от фона с разстояние, светлина, тон и кадриране, преди да разчиташ на софтуерно размазване."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Отдалечи човека от фона, дай му отделна светлина или намери контраст по яркост и цвят. Дълбочината на рязкост зависи от фокусно разстояние, дистанции, диафрагма и размер на сензора; прекалено малката зона на рязкост може да размие нужната ръка. Избери достатъчно отделяне, без да губиш доказателствения детайл.\n\nГраница на правилото: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Включваш максимално размазване през телефонен филтър. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи коя част от субекта трябва да остане четима.\n2. Премести субекта по-напред от фона, ако мястото позволява.\n3. Използвай светлина/цвят/контраст, за да създадеш визуално разделяне.\n4. Провери ръцете, очите и инструмента във финален размер.\n\nСтоп-сигнал: Включваш максимално размазване през телефонен филтър. Алгоритъмът отрязва пръсти и край на инструмента. Ако това се случи, приложи корекцията преди да продължиш: Първо размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Зад инструктора има полица с инструменти в същия цвят като престилката. Преместването му на метър напред и малка контрова светлина отделят раменете; камерата запазва лицето и ръцете резки, за да се вижда демонстрацията. Портретният режим на телефона не е нужен и не размазва пръстите.\n\nРешение в този случай:\nПърво размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет.\n\nГраница на извода:\nСубектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Включваш максимално размазване през телефонен филтър. Алгоритъмът отрязва пръсти и край на инструмента."},"after":{"label":"По-доброто решение","text":"Първо размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет.\n\nПреди да продължиш: Провери ръцете, очите и инструмента във финален размер."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Разстоянието между обекта и фона често е по-лесният лост за отделяне, преди да отваряш диафрагмата. Провери контурите около пръсти и инструмент: портретният режим може да изреже част от тях. При оптично размазване виж дали важната ръка остава във фокус през цялото действие.\n\nКритерий за приемане: Провери ръцете, очите и инструмента във финален размер.\n\nКогато пробата се провали:\nСимптом: Включваш максимално размазване през телефонен филтър.\nКорекция: Първо размести хората и източниците, после коригирай оптиката.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Отдели субекта от фона без софтуерен трик“?","options":[{"id":"a","label":"Отделяй субекта от фона с разстояние, светлина, тон и кадриране, преди да разчиташ на софтуерно размазване."},{"id":"b","label":"Включваш максимално размазване през телефонен филтър."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Отделяй субекта от фона с разстояние, светлина, тон и кадриране, преди да разчиташ на софтуерно размазване. Слабият ход е: Включваш максимално размазване през телефонен филтър. Алгоритъмът отрязва пръсти и край на инструмента. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Зад инструктора има полица с инструменти в същия цвят като престилката. Преместването му на метър напред и малка контрова светлина отделят раменете; камерата запазва лицето и ръцете резки, за да се вижда демонстрацията. Портретният режим на телефона не е нужен и не размазва пръстите.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Включваш максимално размазване през телефонен филтър."},{"id":"b","label":"Първо размести хората и източниците, после коригирай оптиката."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Първо размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет. Грешният път — Включваш максимално размазване през телефонен филтър. — оставя риска нерешен. Провери и границата: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Отдели субекта от фона без софтуерен трик“?","options":[{"id":"a","label":"Субектът не винаги трябва да изпъква силно."},{"id":"b","label":"Включваш максимално размазване през телефонен филтър."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Отделяй субекта от фона с разстояние, светлина, тон и кадриране, преди да разчиташ на софтуерно размазване.","Първо: Определи коя част от субекта трябва да остане четима. После: Премести субекта по-напред от фона, ако мястото позволява.","Следи за грешния ход: Включваш максимално размазване през телефонен филтър."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.","items":[{"id":"s2","text":"Премести субекта по-напред от фона, ако мястото позволява."},{"id":"s1","text":"Определи коя част от субекта трябва да остане четима."},{"id":"s4","text":"Провери ръцете, очите и инструмента във финален размер."},{"id":"s3","text":"Използвай светлина/цвят/контраст, за да създадеш визуално разделяне."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Първо размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет. Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Зад инструктора има полица с инструменти в същия цвят като престилката.\n\nПроменено условие: Субектът не винаги трябва да изпъква силно.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Включваш максимално размазване през телефонен филтър."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Първо размести хората и източниците, после коригирай оптиката."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Първо размести хората и източниците, после коригирай оптиката. Увеличи кадъра и провери контурите около коса, пръсти и предмет. Границата тук е: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.\n\nКарта за работа — Отдели субекта от фона без софтуерен трик\n1. Определи коя част от субекта трябва да остане четима.\n2. Премести субекта по-напред от фона, ако мястото позволява.\n3. Използвай светлина/цвят/контраст, за да създадеш визуално разделяне.\n4. Провери ръцете, очите и инструмента във финален размер.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Отдалечи фона от героя, приближи камерата и провери контурите; отворената бленда също намалява дълбочината на рязкост, но резултатът зависи от дистанцията и фокусното разстояние."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-11","title":"Използвай ND филтър, когато светлината е прекалено силна","objective":"да разпознаеш условията, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата","hook":"На обяд снимаш движение с намерения вид, но светлината кара камерата да избере прекалено кратка експозиция.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разпознаеш условията, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"На обяд снимаш движение с намерения вид, но светлината кара камерата да избере прекалено кратка експозиция.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай ND филтър, когато светлината е прекалено силна, а искаш да запазиш избраните кадри/секунда, затвор и диафрагма."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Неутрално-сивият филтър намалява количеството светлина, което стига до сензора. Той помага да снимаш на открито при творчески желан затвор и бленда; не поправя грешен баланс на бялото и не замества контрол над контраста. Променлив ND може да даде цветен оттенък или X-образен артефакт близо до крайно положение.\n\nГраница на правилото: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Измери яркостта и определи кои настройки искаш да запазиш.\n2. Постави филтър с подходяща плътност и провери цветния неутралитет.\n3. Настрой експозицията отново и тествай неравни/широки повърхности.\n4. Провери винетиране, отражения и кръстосани поляризационни артефакти.\n\nСтоп-сигнал: Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър. Ако това се случи, приложи корекцията преди да продължиш: Дръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"На слънчевата маса 25 кадъра/секунда и 1/50 дават преекспонирана глина при избраната диафрагма. Вместо да повишава затвора, операторът поставя ND, проверява бялата карта и оглежда целия кадър. С променлив филтър се появява тъмно X в небето, затова той намалява плътността и използва фиксиран ND.\n\nРешение в този случай:\nДръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите.\n\nГраница на извода:\nND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."},"after":{"label":"По-доброто решение","text":"Дръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите.\n\nПреди да продължиш: Провери винетиране, отражения и кръстосани поляризационни артефакти."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Неутрално-сивият ND филтър намалява светлината без да променя желаните кадри и движение. Различавай постоянен ND от поляризиращ: поляризаторът влияе и на отраженията, а променлив ND може да даде неравномерна шарка при крайни положения. Завърти филтъра бавно и огледай небето и равни стени.\n\nКритерий за приемане: Провери винетиране, отражения и кръстосани поляризационни артефакти.\n\nКогато пробата се провали:\nСимптом: Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър.\nКорекция: Дръж чиста кърпа и провери филтъра на равномерна стена и небе.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Използвай ND филтър, когато светлината е прекалено силна“?","options":[{"id":"a","label":"Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Използвай ND филтър, когато светлината е прекалено силна, а искаш да запазиш избраните кадри/секунда, затвор и диафрагма."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Използвай ND филтър, когато светлината е прекалено силна, а искаш да запазиш избраните кадри/секунда, затвор и диафрагма. Слабият ход е: Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: На слънчевата маса 25 кадъра/секунда и 1/50 дават преекспонирана глина при избраната диафрагма. Вместо да повишава затвора, операторът поставя ND, проверява бялата карта и оглежда целия кадър. С променлив филтър се появява тъмно X в небето, затова той намалява плътността и използва фиксиран ND.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."},{"id":"b","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."},{"id":"c","label":"Дръж чиста кърпа и провери филтъра на равномерна стена и небе."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Дръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите. Грешният път — Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър. — оставя риска нерешен. Провери и границата: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Използвай ND филтър, когато светлината е прекалено силна“?","options":[{"id":"a","label":"Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."},{"id":"b","label":"ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай ND филтър, когато светлината е прекалено силна, а искаш да запазиш избраните кадри/секунда, затвор и диафрагма.","Първо: Измери яркостта и определи кои настройки искаш да запазиш. После: Постави филтър с подходяща плътност и провери цветния неутралитет.","Следи за грешния ход: Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.","items":[{"id":"s3","text":"Настрой експозицията отново и тествай неравни/широки повърхности."},{"id":"s2","text":"Постави филтър с подходяща плътност и провери цветния неутралитет."},{"id":"s1","text":"Измери яркостта и определи кои настройки искаш да запазиш."},{"id":"s4","text":"Провери винетиране, отражения и кръстосани поляризационни артефакти."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Дръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите. ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: На слънчевата маса 25 кадъра/секунда и 1/50 дават преекспонирана глина при избраната диафрагма.\n\nПроменено условие: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Дръж чиста кърпа и провери филтъра на равномерна стена и небе."},{"id":"b","label":"Завърташ променливия ND до край, докато експозицията стане правилна, без да провериш цвета и петната по целия кадър."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Дръж чиста кърпа и провери филтъра на равномерна стена и небе. Запиши стойността или отбележи филтъра, за да запази екипът последователността между кадрите. Границата тук е: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nКарта за работа — Използвай ND филтър, когато светлината е прекалено силна\n1. Измери яркостта и определи кои настройки искаш да запазиш.\n2. Постави филтър с подходяща плътност и провери цветния неутралитет.\n3. Настрой експозицията отново и тествай неравни/широки повърхности.\n4. Провери винетиране, отражения и кръстосани поляризационни артефакти.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-12","title":"Пази посоката на действие в монтажа","objective":"да използваш оста и правилото на 180° за ясна пространствена ориентация","hook":"Двама души сменят страните си през монтажния скок, въпреки че никой не е помръднал.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш оста и правилото на 180° за ясна пространствена ориентация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Двама души сменят страните си през монтажния скок, въпреки че никой не е помръднал.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Пази посоката на действие и поглед в монтажа, за да разбере зрителят къде са хората и накъде се движат."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Оста на действие е въображаемата линия между участници или посоки. Ако камерата остава от едната страна, посоката на екрана е последователна; пресичане без преход може да обърне движението. Можеш да преминеш през оста с видимо движение, кадър по оста, установяващ план или промяна, която зрителят разбира.\n\nГраница на правилото: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Редуваш кадри от двата края на линията без установяващ план. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи линията на действие и посоките на поглед/движение.\n2. Постави камерата от едната страна за основните кадри.\n3. Провери посоката в широк, среден и близък план.\n4. Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка.\n\nСтоп-сигнал: Редуваш кадри от двата края на линията без установяващ план. Ученикът изглежда, че сменя място и гледа в една и съща посока. Ако това се случи, приложи корекцията преди да продължиш: Пусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Ученикът гледа инструктора вдясно от кадъра, инструкторът отговаря вляво. Близките планове пазят тази връзка. Камерата минава през линията, когато следва ученика около колелото; по време на движението зрителят вижда смяната и новата позиция.\n\nРешение в този случай:\nПусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър.\n\nГраница на извода:\n180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Редуваш кадри от двата края на линията без установяващ план. Ученикът изглежда, че сменя място и гледа в една и съща посока."},"after":{"label":"По-доброто решение","text":"Пусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър.\n\nПреди да продължиш: Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Оста на действие е въображаемата линия между участници или посоки на движение. Кадри от една страна поддържат посоката на екрана; пресичането ѝ може да обърка зрителя, освен ако не покажеш преход или нов установяващ план. Провери монтажа без звук и следи къде гледат очите и ръцете.\n\nКритерий за приемане: Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка.\n\nКогато пробата се провали:\nСимптом: Редуваш кадри от двата края на линията без установяващ план.\nКорекция: Пусни черновия монтаж без звук и проследи погледа/направлението.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Пази посоката на действие в монтажа“?","options":[{"id":"a","label":"Редуваш кадри от двата края на линията без установяващ план."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Пази посоката на действие и поглед в монтажа, за да разбере зрителят къде са хората и накъде се движат."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Пази посоката на действие и поглед в монтажа, за да разбере зрителят къде са хората и накъде се движат. Слабият ход е: Редуваш кадри от двата края на линията без установяващ план. Ученикът изглежда, че сменя място и гледа в една и съща посока. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Ученикът гледа инструктора вдясно от кадъра, инструкторът отговаря вляво. Близките планове пазят тази връзка. Камерата минава през линията, когато следва ученика около колелото; по време на движението зрителят вижда смяната и новата позиция.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Редуваш кадри от двата края на линията без установяващ план."},{"id":"b","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."},{"id":"c","label":"Пусни черновия монтаж без звук и проследи погледа/направлението."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Пусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър. Грешният път — Редуваш кадри от двата края на линията без установяващ план. — оставя риска нерешен. Провери и границата: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Пази посоката на действие в монтажа“?","options":[{"id":"a","label":"Редуваш кадри от двата края на линията без установяващ план."},{"id":"b","label":"180-градусовото правило е ориентир за разбираемост, не забрана."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Пази посоката на действие и поглед в монтажа, за да разбере зрителят къде са хората и накъде се движат.","Първо: Определи линията на действие и посоките на поглед/движение. После: Постави камерата от едната страна за основните кадри.","Следи за грешния ход: Редуваш кадри от двата края на линията без установяващ план."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.","items":[{"id":"s3","text":"Провери посоката в широк, среден и близък план."},{"id":"s4","text":"Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка."},{"id":"s2","text":"Постави камерата от едната страна за основните кадри."},{"id":"s1","text":"Определи линията на действие и посоките на поглед/движение."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Пусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър. 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Ученикът гледа инструктора вдясно от кадъра, инструкторът отговаря вляво.\n\nПроменено условие: 180-градусовото правило е ориентир за разбираемост, не забрана.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Пусни черновия монтаж без звук и проследи погледа/направлението."},{"id":"a","label":"Редуваш кадри от двата края на линията без установяващ план."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Пусни черновия монтаж без звук и проследи погледа/направлението. Ако ориентацията се губи, вмъкни план по оста или преснеми преходен кадър. Границата тук е: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.\n\nКарта за работа — Пази посоката на действие в монтажа\n1. Определи линията на действие и посоките на поглед/движение.\n2. Постави камерата от едната страна за основните кадри.\n3. Провери посоката в широк, среден и близък план.\n4. Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-13","title":"Използвай третините като насока, не закон","objective":"да разположиш субект и поглед така, че кадърът да подкрепя сцената","hook":"Лице точно в пресечната точка не е автоматично по-добър кадър.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разположиш субект и поглед така, че кадърът да подкрепя сцената. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Лице точно в пресечната точка не е автоматично по-добър кадър.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай третините като начална мрежа за разположение, после провери поглед, движение, място за текст и баланс на кадъра."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Поставянето на очите близо до горната третина често оставя достатъчно headroom, но лице, инструмент и пространство могат да изискват друга позиция. Остави място пред погледа и движението; не изрязвай ръка, която носи действието. Премести камерата физически, ако фонът пречи.\n\nГраница на правилото: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Намери основния обект и важната посока на поглед.\n2. Провери headroom и свободното място пред погледа/движението.\n3. Подреди фон и хоризонт преди да коригираш мрежата.\n4. Сравни третини с централна композиция за задачата.\n\nСтоп-сигнал: Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето. Ако това се случи, приложи корекцията преди да продължиш: Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Водещата гледа към инструктора извън кадър. Ако лицето е крайно вдясно, няма място за поглед; ако е точно в центъра, липсва възможност да се види работният плот. Преместваш камерата и оставяш място в посоката на очите, докато композицията пази и ръцете.\n\nРешение в този случай:\nПровери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена.\n\nГраница на извода:\nНарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."},"after":{"label":"По-доброто решение","text":"Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена.\n\nПреди да продължиш: Сравни третини с централна композиция за задачата."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Третините са помощна мрежа, не правило за всеки кадър. Първо реши къде трябва да гледа окото; после провери свободното място пред лицето, посоката на движение и конкуриращия предмет. Центриран кадър може да е точен за симетрия, демонстрация или осъзнат акцент.\n\nКритерий за приемане: Сравни третини с централна композиция за задачата.\n\nКогато пробата се провали:\nСимптом: Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето.\nКорекция: Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Използвай третините като насока, не закон“?","options":[{"id":"a","label":"Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."},{"id":"b","label":"Използвай третините като начална мрежа за разположение, после провери поглед, движение, място за текст и баланс на кадъра."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Използвай третините като начална мрежа за разположение, после провери поглед, движение, място за текст и баланс на кадъра. Слабият ход е: Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Водещата гледа към инструктора извън кадър. Ако лицето е крайно вдясно, няма място за поглед; ако е точно в центъра, липсва възможност да се види работният плот. Преместваш камерата и оставяш място в посоката на очите, докато композицията пази и ръцете.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център."},{"id":"b","label":"Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена. Грешният път — Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето. — оставя риска нерешен. Провери и границата: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Използвай третините като насока, не закон“?","options":[{"id":"a","label":"Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай третините като начална мрежа за разположение, после провери поглед, движение, място за текст и баланс на кадъра.","Първо: Намери основния обект и важната посока на поглед. После: Провери headroom и свободното място пред погледа/движението.","Следи за грешния ход: Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.","items":[{"id":"s1","text":"Намери основния обект и важната посока на поглед."},{"id":"s4","text":"Сравни третини с централна композиция за задачата."},{"id":"s3","text":"Подреди фон и хоризонт преди да коригираш мрежата."},{"id":"s2","text":"Провери headroom и свободното място пред погледа/движението."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена. Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Водещата гледа към инструктора извън кадър.\n\nПроменено условие: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Прилепваш субекта към една от линиите, макар в тази страна да минава ярък кабел, който е по-забележим от лицето."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Провери кадъра в черно-бял преглед или намален размер, за да видиш визуалния център. Мрежата е помощен ориентир; избирай позиция за конкретна сцена. Границата тук е: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.\n\nКарта за работа — Използвай третините като насока, не закон\n1. Намери основния обект и важната посока на поглед.\n2. Провери headroom и свободното място пред погледа/движението.\n3. Подреди фон и хоризонт преди да коригираш мрежата.\n4. Сравни третини с централна композиция за задачата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-14","title":"Насочи погледа с линии и форми","objective":"да използваш видимите линии, без да отклоняваш вниманието от главния субект","hook":"Пътеката води погледа право извън кадъра, вместо към действието.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш видимите линии, без да отклоняваш вниманието от главния субект. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Пътеката води погледа право извън кадъра, вместо към действието.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай линии и форми, за да насочиш вниманието към действие или обект, без конкурентна линия да го отнеме."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Ръб на маса, поглед, инструмент или светлинна ивица могат да водят окото. Диагоналите дават движение, вертикалите — устойчивост, повторенията — ритъм, но това не са автоматични емоции. Провери къде линиите се срещат и дали не излизат от кадъра към по-ярък елемент.\n\nГраница на правилото: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Поставяш инструмент точно пред лицето, защото линията трябва да води към него. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи какво зрителят трябва да види първо.\n2. Огледай реални линии във фона и предния план.\n3. Премести камерата/предмета, за да водят към основното действие.\n4. Провери ръбове за линии, които пресичат лице или изкарват погледа.\n\nСтоп-сигнал: Поставяш инструмент точно пред лицето, защото линията трябва да води към него. Визуалният трик закрива човека и създава нежелана асоциация. Ако това се случи, приложи корекцията преди да продължиш: Огледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Масата и рамото на оператора образуват диагонал към ръцете на колелото; рафтът зад инструктора е почти хоризонтален и спокоен. В кадър влиза ярък кабел, който също сочи навън. Преместваш го, вместо да добавяш графична стрелка.\n\nРешение в този случай:\nОгледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект.\n\nГраница на извода:\nФормалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Поставяш инструмент точно пред лицето, защото линията трябва да води към него. Визуалният трик закрива човека и създава нежелана асоциация."},"after":{"label":"По-доброто решение","text":"Огледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект.\n\nПреди да продължиш: Провери ръбове за линии, които пресичат лице или изкарват погледа."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Линия насочва поглед само ако има ясно начало и край. Провери къде водят ръбът на масата, ръката и светлината; после огледай за тангенти, при които линия докосва контур на лице или предмет и прави формата неясна. Премести камерата малко, преди да добавиш графичен ефект.\n\nКритерий за приемане: Провери ръбове за линии, които пресичат лице или изкарват погледа.\n\nКогато пробата се провали:\nСимптом: Поставяш инструмент точно пред лицето, защото линията трябва да води към него.\nКорекция: Огледай кадъра по краищата и отбележи най-ярката линия.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Насочи погледа с линии и форми“?","options":[{"id":"a","label":"Поставяш инструмент точно пред лицето, защото линията трябва да води към него."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Използвай линии и форми, за да насочиш вниманието към действие или обект, без конкурентна линия да го отнеме."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Използвай линии и форми, за да насочиш вниманието към действие или обект, без конкурентна линия да го отнеме. Слабият ход е: Поставяш инструмент точно пред лицето, защото линията трябва да води към него. Визуалният трик закрива човека и създава нежелана асоциация. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Масата и рамото на оператора образуват диагонал към ръцете на колелото; рафтът зад инструктора е почти хоризонтален и спокоен. В кадър влиза ярък кабел, който също сочи навън. Преместваш го, вместо да добавяш графична стрелка.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Поставяш инструмент точно пред лицето, защото линията трябва да води към него."},{"id":"b","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."},{"id":"c","label":"Огледай кадъра по краищата и отбележи най-ярката линия."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Огледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект. Грешният път — Поставяш инструмент точно пред лицето, защото линията трябва да води към него. — оставя риска нерешен. Провери и границата: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Насочи погледа с линии и форми“?","options":[{"id":"a","label":"Поставяш инструмент точно пред лицето, защото линията трябва да води към него."},{"id":"b","label":"Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото важи при проверените условия: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай линии и форми, за да насочиш вниманието към действие или обект, без конкурентна линия да го отнеме.","Първо: Определи какво зрителят трябва да види първо. После: Огледай реални линии във фона и предния план.","Следи за грешния ход: Поставяш инструмент точно пред лицето, защото линията трябва да води към него."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.","items":[{"id":"s2","text":"Огледай реални линии във фона и предния план."},{"id":"s4","text":"Провери ръбове за линии, които пресичат лице или изкарват погледа."},{"id":"s1","text":"Определи какво зрителят трябва да види първо."},{"id":"s3","text":"Премести камерата/предмета, за да водят към основното действие."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Огледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект. Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Масата и рамото на оператора образуват диагонал към ръцете на колелото; рафтът зад инструктора е почти хоризонтален и спокоен.\n\nПроменено условие: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Огледай кадъра по краищата и отбележи най-ярката линия."},{"id":"b","label":"Поставяш инструмент точно пред лицето, защото линията трябва да води към него."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Огледай кадъра по краищата и отбележи най-ярката линия. Ако погледът напуска кадъра, промени позицията или осветлението преди да прибягваш до ефект. Границата тук е: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.\n\nКарта за работа — Насочи погледа с линии и форми\n1. Определи какво зрителят трябва да види първо.\n2. Огледай реални линии във фона и предния план.\n3. Премести камерата/предмета, за да водят към основното действие.\n4. Провери ръбове за линии, които пресичат лице или изкарват погледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-15","title":"Остави място за поглед и графика","objective":"да използваш празното пространство така, че да балансира кадъра и да побере нужната информация","hook":"Надписът закрива демонстрацията, защото кадърът е бил композиран само за красив screenshot.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш празното пространство така, че да балансира кадъра и да побере нужната информация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Надписът закрива демонстрацията, защото кадърът е бил композиран само за красив screenshot.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Оставяй празно пространство с функция: място за поглед, движение, надпис или визуално спокойствие. Празното място е част от подредбата, не загубен кадър."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Провери къде ще се появяват интерфейс, субтитри и заглавие; остави фона достатъчно чист, за да се чете текстът. Празно пространство може да създаде дистанция или напрежение, но ако погледът на човек се блъска в ръба, сцената се усеща притисната.\n\nГраница на правилото: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи къде ще се поставят субтитри и графика.\n2. Остави място в посоката на поглед или движение.\n3. Провери контраста и чистотата на избраната зона.\n4. Прегледай надпис върху реален кадър и екран.\n\nСтоп-сигнал: Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика. Главното действие няма място да диша. Ако това се случи, приложи корекцията преди да продължиш: Премахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Водещата гледа наляво към демонстрацията; свободното място е отляво и там се появява кратък надпис. Във вертикалната версия бутони и описанието могат да покрият долната част, затова важната цена не се поставя там и се повтаря в описанието по достъпен начин.\n\nРешение в този случай:\nПремахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен.\n\nГраница на извода:\nИнтерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика. Главното действие няма място да диша."},"after":{"label":"По-доброто решение","text":"Премахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен.\n\nПреди да продължиш: Прегледай надпис върху реален кадър и екран."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Празното пространство може да остави място за поглед, движение или четим надпис. То не е автоматично свободно за лого. Провери кадъра със субтитри и интерфейс върху реален телефон; критичният текст и предметът трябва да останат видими едновременно.\n\nКритерий за приемане: Прегледай надпис върху реален кадър и екран.\n\nКогато пробата се провали:\nСимптом: Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика.\nКорекция: Премахни графиката и провери дали кадърът пак е балансиран.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Остави място за поглед и графика“?","options":[{"id":"a","label":"Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика."},{"id":"b","label":"Оставяй празно пространство с функция: място за поглед, движение, надпис или визуално спокойствие."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Оставяй празно пространство с функция: място за поглед, движение, надпис или визуално спокойствие. Празното място е част от подредбата, не загубен кадър. Слабият ход е: Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика. Главното действие няма място да диша. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Водещата гледа наляво към демонстрацията; свободното място е отляво и там се появява кратък надпис. Във вертикалната версия бутони и описанието могат да покрият долната част, затова важната цена не се поставя там и се повтаря в описанието по достъпен начин.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Премахни графиката и провери дали кадърът пак е балансиран."},{"id":"b","label":"Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Премахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен. Грешният път — Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика. — оставя риска нерешен. Провери и границата: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Остави място за поглед и графика“?","options":[{"id":"a","label":"Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Интерфейсните зони и позицията на субтитрите се различават по платформа."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Оставяй празно пространство с функция: място за поглед, движение, надпис или визуално спокойствие. Празното място е част от подредбата, не загубен кадър.","Първо: Определи къде ще се поставят субтитри и графика. После: Остави място в посоката на поглед или движение.","Следи за грешния ход: Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.","items":[{"id":"s1","text":"Определи къде ще се поставят субтитри и графика."},{"id":"s3","text":"Провери контраста и чистотата на избраната зона."},{"id":"s2","text":"Остави място в посоката на поглед или движение."},{"id":"s4","text":"Прегледай надпис върху реален кадър и екран."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Премахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен. Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Водещата гледа наляво към демонстрацията; свободното място е отляво и там се появява кратък надпис.\n\nПроменено условие: Интерфейсните зони и позицията на субтитрите се различават по платформа.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Премахни графиката и провери дали кадърът пак е балансиран."},{"id":"a","label":"Запълваш всеки ъгъл с лого, субтитри, иконка и бърза графика."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Премахни графиката и провери дали кадърът пак е балансиран. Добавяй само текст, който дава нова информация; прегледай и с текст включен. Границата тук е: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.\n\nКарта за работа — Остави място за поглед и графика\n1. Определи къде ще се поставят субтитри и графика.\n2. Остави място в посоката на поглед или движение.\n3. Провери контраста и чистотата на избраната зона.\n4. Прегледай надпис върху реален кадър и екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Планирай празното място по посоката на погледа или движението. Дръж критичния текст извън зоната на бутоните и субтитрите, после прегледай финалния размер на телефона."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-16","title":"Използвай преден, среден и заден план","objective":"да добавиш дълбочина и контекст, без да претрупаш кадъра","hook":"Кадърът изглежда плосък, защото камерата вижда само стена и лице.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да добавиш дълбочина и контекст, без да претрупаш кадъра. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Кадърът изглежда плосък, защото камерата вижда само стена и лице.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай преден, среден и заден план, за да покажеш пространство и контекст, като държиш конкуренцията под контрол."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Дълбочина може да се създаде чрез припокриване, размер, светлина, цвят, фокус и движение на камерата. Предният план може да рамкира действието; средният носи героя; задният уточнява мястото. Всеки слой трябва да добавя информация. Проверявай дали случаен предмет прилича на част от субекта или отвлича вниманието.\n\nГраница на правилото: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Очерти главния субект и мястото му в сцената.\n2. Добави смислен преден план или остави кадъра чист.\n3. Подреди фон и светлина отделно от героя.\n4. Провери припокриванията и дали всички планове са четими.\n\nСтоп-сигнал: Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус. Ако това се случи, приложи корекцията преди да продължиш: Прегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Кадърът през рафта към инструктора показва инструменти отпред, работа по средата и ателието отзад. Една висока ваза обаче съвпада с главата му и изглежда като продължение. Местиш вазата и намаляваш яркостта на фона, без да го заличаваш.\n\nРешение в този случай:\nПрегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет.\n\nГраница на извода:\nДълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."},"after":{"label":"По-доброто решение","text":"Прегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет.\n\nПреди да продължиш: Провери припокриванията и дали всички планове са четими."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Постави преден, среден и заден план с ясна причина: да покажат място, действие и контекст. Ако всеки слой се бори за фокус, избери кой е главен и насочи светлината към него. Следи дали предният предмет не закрива ръцете точно в момента на демонстрацията.\n\nКритерий за приемане: Провери припокриванията и дали всички планове са четими.\n\nКогато пробата се провали:\nСимптом: Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус.\nКорекция: Прегледай кадъра в стоп-кадър и в движение.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Използвай преден, среден и заден план“?","options":[{"id":"a","label":"Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."},{"id":"b","label":"Използвай преден, среден и заден план, за да покажеш пространство и контекст, като държиш конкуренцията под контрол."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Използвай преден, среден и заден план, за да покажеш пространство и контекст, като държиш конкуренцията под контрол. Слабият ход е: Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Кадърът през рафта към инструктора показва инструменти отпред, работа по средата и ателието отзад. Една висока ваза обаче съвпада с главата му и изглежда като продължение. Местиш вазата и намаляваш яркостта на фона, без да го заличаваш.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Прегледай кадъра в стоп-кадър и в движение."},{"id":"b","label":"Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Прегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет. Грешният път — Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус. — оставя риска нерешен. Провери и границата: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Използвай преден, среден и заден план“?","options":[{"id":"a","label":"Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Дълбочината на рязкост не е равна на дълбочина в историята."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай преден, среден и заден план, за да покажеш пространство и контекст, като държиш конкуренцията под контрол.","Първо: Очерти главния субект и мястото му в сцената. После: Добави смислен преден план или остави кадъра чист.","Следи за грешния ход: Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.","items":[{"id":"s2","text":"Добави смислен преден план или остави кадъра чист."},{"id":"s4","text":"Провери припокриванията и дали всички планове са четими."},{"id":"s3","text":"Подреди фон и светлина отделно от героя."},{"id":"s1","text":"Очерти главния субект и мястото му в сцената."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Прегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет. Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Кадърът през рафта към инструктора показва инструменти отпред, работа по средата и ателието отзад.\n\nПроменено условие: Дълбочината на рязкост не е равна на дълбочина в историята.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Натрупваш предмети в предния план и отваряш диафрагмата толкова, че ръцете и инструментът излизат от фокус."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Прегледай кадъра в стоп-кадър и в движение."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Прегледай кадъра в стоп-кадър и в движение. Премести камерата на няколко сантиметра — малка промяна може да раздели ръка и лице от фонов предмет. Границата тук е: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.\n\nКарта за работа — Използвай преден, среден и заден план\n1. Очерти главния субект и мястото му в сцената.\n2. Добави смислен преден план или остави кадъра чист.\n3. Подреди фон и светлина отделно от героя.\n4. Провери припокриванията и дали всички планове са четими.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-17","title":"Движи камерата само когато движението помага","objective":"да избираш статичен кадър, панорама, наклон или проследяване според действието","hook":"Камерата се движи пет секунди по празна стена и нищо ново не научаваме.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш статичен кадър, панорама, наклон или проследяване според действието. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата се движи пет секунди по празна стена и нищо ново не научаваме.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Движи камерата само когато движението помага да се разкрие пространство, проследи действие или промени отношенията между хората."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Преди панорама, наклон или проследяване определи начална точка, крайна точка, скорост и причина. Статичният кадър често е по-четим за демонстрация. Движението трябва да има подготовка и да завърши стабилно; стабилизаторът намалява трептене, но не измисля цел и може да създаде лошо поклащане.\n\nГраница на правилото: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови защо камерата трябва да се движи в тази сцена.\n2. Маркирай старт, край, траектория и фокус.\n3. Репетирай с актьора/действието и провери препятствията.\n4. Запиши статична алтернатива и сравни кой кадър е по-ясен.\n\nСтоп-сигнал: Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“. Зрителят няма време да види техниката. Ако това се случи, приложи корекцията преди да продължиш: Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Камерата следва участник от вратата до работното място, за да покаже как той стига до инструктора. Вътре движението спира, преди демонстрацията на ръцете; близък план остава стабилен. Екипът снима и отделен широк установяващ план като монтажна опора.\n\nРешение в този случай:\nВключи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна.\n\nГраница на извода:\nНе ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“. Зрителят няма време да види техниката."},"after":{"label":"По-доброто решение","text":"Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна.\n\nПреди да продължиш: Запиши статична алтернатива и сравни кой кадър е по-ясен."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Преди да движиш камерата, опиши каква нова информация ще разкрие движението. Започни и завърши с кратка неподвижна част, дръж движението равномерно и провери дали опората или стабилизацията изрязва кадъра. Ако движението не променя разбирането, статичният кадър е по-ясен.\n\nКритерий за приемане: Запиши статична алтернатива и сравни кой кадър е по-ясен.\n\nКогато пробата се провали:\nСимптом: Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“.\nКорекция: Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Движи камерата само когато движението помага“?","options":[{"id":"a","label":"Движи камерата само когато движението помага да се разкрие пространство, проследи действие или промени отношенията между хората."},{"id":"b","label":"Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото е: Движи камерата само когато движението помага да се разкрие пространство, проследи действие или промени отношенията между хората. Слабият ход е: Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“. Зрителят няма време да види техниката. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Камерата следва участник от вратата до работното място, за да покаже как той стига до инструктора. Вътре движението спира, преди демонстрацията на ръцете; близък план остава стабилен. Екипът снима и отделен широк установяващ план като монтажна опора.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“."},{"id":"b","label":"Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна. Грешният път — Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“. — оставя риска нерешен. Провери и границата: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Движи камерата само когато движението помага“?","options":[{"id":"a","label":"Не ходи назад с камера без оператор/осигуряване и оглед на пътя."},{"id":"b","label":"Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Движи камерата само когато движението помага да се разкрие пространство, проследи действие или промени отношенията между хората.","Първо: Назови защо камерата трябва да се движи в тази сцена. После: Маркирай старт, край, траектория и фокус.","Следи за грешния ход: Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.","items":[{"id":"s3","text":"Репетирай с актьора/действието и провери препятствията."},{"id":"s4","text":"Запиши статична алтернатива и сравни кой кадър е по-ясен."},{"id":"s1","text":"Назови защо камерата трябва да се движи в тази сцена."},{"id":"s2","text":"Маркирай старт, край, траектория и фокус."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна. Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Камерата следва участник от вратата до работното място, за да покаже как той стига до инструктора.\n\nПроменено условие: Не ходи назад с камера без оператор/осигуряване и оглед на пътя.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора."},{"id":"b","label":"Плъзгаш камерата по целия час, защото „движещ кадър изглежда професионално“."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Включи звукови маркери за старт/стоп и дръж движение с две ръце или подходяща опора. Ако кадърът не разкрива нищо ново, остави камерата неподвижна. Границата тук е: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.\n\nКарта за работа — Движи камерата само когато движението помага\n1. Назови защо камерата трябва да се движи в тази сцена.\n2. Маркирай старт, край, траектория и фокус.\n3. Репетирай с актьора/действието и провери препятствията.\n4. Запиши статична алтернатива и сравни кой кадър е по-ясен.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-18","title":"Използвай рамка в рамката с ясна причина","objective":"да поставиш субекта в естествена рамка, която добавя контекст или фокус","hook":"Арка пред лицето може да изглежда като пречка, ако не добавя нищо към сцената.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поставиш субекта в естествена рамка, която добавя контекст или фокус. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Арка пред лицето може да изглежда като пречка, ако не добавя нищо към сцената.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Използвай естествена рамка в рамката, когато тя добавя място, контекст или визуален фокус, а не закрива главното действие."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Врата, прозорец, арка, инструмент или силует могат да ограничат погледа и да създадат дълбочина. Провери дали рамката е ясна, дали не изглежда като предмет, който стърчи от главата, и дали не прави сцена прекалено наблюдателна. Позицията на камерата определя колко рамката е видима.\n\nГраница на правилото: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Назови какво дава рамката: контекст, дълбочина или внимание.\n2. Избери естествен елемент и провери безопасност/разрешение.\n3. Премести камерата до чисто разделяне на преден и заден план.\n4. Оцени дали рамката отнема площ или затваря погледа.\n\nСтоп-сигнал: Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър. Това е ефект без причина. Ако това се случи, приложи корекцията преди да продължиш: Премести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Снимаш майсторката през отворената врата на ателието. Рамката показва къде се намира и добавя слой, но табелата с чуждо име се маха от фона и вратата не пресича лицето. За близката демонстрация преминаваш отвъд рамката, за да не изглежда, че участникът е наблюдаван скришом.\n\nРешение в този случай:\nПремести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената.\n\nГраница на извода:\nНе снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър. Това е ефект без причина."},"after":{"label":"По-доброто решение","text":"Премести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената.\n\nПреди да продължиш: Оцени дали рамката отнема площ или затваря погледа."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Рамка в рамката може да покаже мястото или да насочи погледа, но не бива да изглежда като предмет, който закрива героя. Провери силуета от четирите края, движението на ръцете и контраста. Сними и вариант без рамката, за да видиш дали тя носи информация.\n\nКритерий за приемане: Оцени дали рамката отнема площ или затваря погледа.\n\nКогато пробата се провали:\nСимптом: Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър.\nКорекция: Премести се, докато рамката не се слива с профила на героя.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Използвай рамка в рамката с ясна причина“?","options":[{"id":"a","label":"Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Използвай естествена рамка в рамката, когато тя добавя място, контекст или визуален фокус, а не закрива главното действие."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Използвай естествена рамка в рамката, когато тя добавя място, контекст или визуален фокус, а не закрива главното действие. Слабият ход е: Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър. Това е ефект без причина. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Снимаш майсторката през отворената врата на ателието. Рамката показва къде се намира и добавя слой, но табелата с чуждо име се маха от фона и вратата не пресича лицето. За близката демонстрация преминаваш отвъд рамката, за да не изглежда, че участникът е наблюдаван скришом.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Премести се, докато рамката не се слива с профила на героя."},{"id":"b","label":"Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Премести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената. Грешният път — Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър. — оставя риска нерешен. Провери и границата: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Използвай рамка в рамката с ясна причина“?","options":[{"id":"a","label":"Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Използвай естествена рамка в рамката, когато тя добавя място, контекст или визуален фокус, а не закрива главното действие.","Първо: Назови какво дава рамката: контекст, дълбочина или внимание. После: Избери естествен елемент и провери безопасност/разрешение.","Следи за грешния ход: Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.","items":[{"id":"s4","text":"Оцени дали рамката отнема площ или затваря погледа."},{"id":"s1","text":"Назови какво дава рамката: контекст, дълбочина или внимание."},{"id":"s2","text":"Избери естествен елемент и провери безопасност/разрешение."},{"id":"s3","text":"Премести камерата до чисто разделяне на преден и заден план."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Премести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената. Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Снимаш майсторката през отворената врата на ателието.\n\nПроменено условие: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Премести се, докато рамката не се слива с профила на героя."},{"id":"a","label":"Оставяш рамка по всички четири краища и потъмняваш ъглите във всеки кадър."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Премести се, докато рамката не се слива с профила на героя. Провери и алтернативен кадър без нея; избери този, който най-добре служи на сцената. Границата тук е: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nКарта за работа — Използвай рамка в рамката с ясна причина\n1. Назови какво дава рамката: контекст, дълбочина или внимание.\n2. Избери естествен елемент и провери безопасност/разрешение.\n3. Премести камерата до чисто разделяне на преден и заден план.\n4. Оцени дали рамката отнема площ или затваря погледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-19","title":"Избери визуален баланс според усещането","objective":"да сравниш симетричен и асиметричен баланс според намерението","hook":"Центрираната симетрия може да звучи официално; асиметрията може да даде движение, но и да разсее.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш симетричен и асиметричен баланс според намерението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Центрираната симетрия може да звучи официално; асиметрията може да даде движение, но и да разсее.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Избирай симетричен или асиметричен баланс според чувството и задачата. Визуалната тежест зависи от размер, яркост, контраст, цвят, позиция и движение."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Симетрия може да създаде ред, централност или церемониалност; асиметрия — напрежение, посока или естественост. Един малък ярък предмет може да натежи колкото голяма тъмна площ. Провери фона, цвета и движението; балансът не е проста сметка ляво/дясно.\n\nГраница на правилото: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Определи основния фокус и желаното усещане.\n2. Огледай големи площи, контрастни точки и движение.\n3. Премести предмети или камера, за да насочиш тежестта.\n4. Сравни кадъра на малък екран и без звук.\n\nСтоп-сигнал: Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус. Ако това се случи, приложи корекцията преди да продължиш: Скрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"За представяне на курс центрираш грънчарското колело и симетрично подреждаш инструментите — спокойно, ясно, почти учебно. За историята на участник оставяш лицето от едната страна и работното колело от другата; погледът свързва двете половини, без да се получи случайна празнина.\n\nРешение в този случай:\nСкрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка.\n\nГраница на извода:\nНе обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."},"after":{"label":"По-доброто решение","text":"Скрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка.\n\nПреди да продължиш: Сравни кадъра на малък екран и без звук."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Визуалната тежест идва от размер, яркост, контраст, цвят и движение. Ако ярък прозорец дърпа погледа от ръцете, промени експозицията или кадрирането, вместо да добавиш още графика. Сравни симетричен и асиметричен вариант на един и същ момент.\n\nКритерий за приемане: Сравни кадъра на малък екран и без звук.\n\nКогато пробата се провали:\nСимптом: Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус.\nКорекция: Скрий временно цвета или намали изображението, за да видиш тоналната тежест.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Избери визуален баланс според усещането“?","options":[{"id":"a","label":"Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."},{"id":"b","label":"Избирай симетричен или асиметричен баланс според чувството и задачата."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Избирай симетричен или асиметричен баланс според чувството и задачата. Визуалната тежест зависи от размер, яркост, контраст, цвят, позиция и движение. Слабият ход е: Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: За представяне на курс центрираш грънчарското колело и симетрично подреждаш инструментите — спокойно, ясно, почти учебно. За историята на участник оставяш лицето от едната страна и работното колело от другата; погледът свързва двете половини, без да се получи случайна празнина.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."},{"id":"b","label":"Скрий временно цвета или намали изображението, за да видиш тоналната тежест."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Скрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка. Грешният път — Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус. — оставя риска нерешен. Провери и границата: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Избери визуален баланс според усещането“?","options":[{"id":"a","label":"Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър."},{"id":"b","label":"Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Избирай симетричен или асиметричен баланс според чувството и задачата. Визуалната тежест зависи от размер, яркост, контраст, цвят, позиция и движение.","Първо: Определи основния фокус и желаното усещане. После: Огледай големи площи, контрастни точки и движение.","Следи за грешния ход: Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.","items":[{"id":"s2","text":"Огледай големи площи, контрастни точки и движение."},{"id":"s1","text":"Определи основния фокус и желаното усещане."},{"id":"s3","text":"Премести предмети или камера, за да насочиш тежестта."},{"id":"s4","text":"Сравни кадъра на малък екран и без звук."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Скрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка. Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: За представяне на курс центрираш грънчарското колело и симетрично подреждаш инструментите — спокойно, ясно, почти учебно.\n\nПроменено условие: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Преместваш героя по третините, но оставяш ярък жълт предмет в противоположния ъгъл, който става главен фокус."},{"id":"b","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"c","label":"Скрий временно цвета или намали изображението, за да видиш тоналната тежест."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Приложи корекцията към новото условие: Скрий временно цвета или намали изображението, за да видиш тоналната тежест. После върни цвят и движение и направи финална проверка. Границата тук е: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.\n\nКарта за работа — Избери визуален баланс според усещането\n1. Определи основния фокус и желаното усещане.\n2. Огледай големи площи, контрастни точки и движение.\n3. Премести предмети или камера, за да насочиш тежестта.\n4. Сравни кадъра на малък екран и без звук.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-20","title":"Прекадрирай композицията за вертикален екран","objective":"да запазиш четимост и визуална йерархия при тесен вертикален кадър","hook":"Хоризонталната линия се прекъсва при изрязване и вече не води погледа.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да запазиш четимост и визуална йерархия при тесен вертикален кадър. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Хоризонталната линия се прекъсва при изрязване и вече не води погледа.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Прекадрирай за вертикален екран с нова визуална йерархия, не като механично изрязване на хоризонталния кадър."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"В тесния кадър лице, ръце и инструмент може да не се поберат заедно. Реши кое е основното и снимай допълнителен детайл, ако е нужно. Остави място за поглед, субтитри и интерфейсни бутони; финалната safe зона проверявай в конкретното приложение и версия.\n\nГраница на правилото: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Избери кое доказателство е най-важно за вертикалната версия.\n2. Премести камерата или направи отделен близък/среден кадър.\n3. Остави чиста зона за субтитри и провери наложения интерфейс.\n4. Гледай експортирания файл в приложението и тествай четливостта.\n\nСтоп-сигнал: Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи. Ако това се случи, приложи корекцията преди да продължиш: Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Широк кадър показва двете ръце и колелото. В 9:16 изрязването маха едната ръка, която показва контрол на формата. Вместо изрязване, снимаш отделен портретен близък план от малко по-висока позиция; субтитърът се мести над областта с ръцете.\n\nРешение в този случай:\nНаправи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда.\n\nГраница на извода:\nБезопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."},"after":{"label":"По-доброто решение","text":"Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда.\n\nПреди да продължиш: Гледай експортирания файл в приложението и тествай четливостта."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Портретното кадриране иска нова йерархия, не само изрязване. Определи кое действие остава в центъра, провери пространство за поглед и надпис и задай безопасна зона спрямо конкретното приложение. Експортирай тест и отвори го в интерфейса, където ще бъде публикуван.\n\nКритерий за приемане: Гледай експортирания файл в приложението и тествай четливостта.\n\nКогато пробата се провали:\nСимптом: Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи.\nКорекция: Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Прекадрирай композицията за вертикален екран“?","options":[{"id":"a","label":"Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."},{"id":"b","label":"Прекадрирай за вертикален екран с нова визуална йерархия, не като механично изрязване на хоризонталния кадър."},{"id":"c","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Правилото е: Прекадрирай за вертикален екран с нова визуална йерархия, не като механично изрязване на хоризонталния кадър. Слабият ход е: Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Широк кадър показва двете ръце и колелото. В 9:16 изрязването маха едната ръка, която показва контрол на формата. Вместо изрязване, снимаш отделен портретен близък план от малко по-висока позиция; субтитърът се мести над областта с ръцете.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."},{"id":"b","label":"Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда. Грешният път — Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи. — оставя риска нерешен. Провери и границата: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Прекадрирай композицията за вертикален екран“?","options":[{"id":"a","label":"Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами."},{"id":"b","label":"Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."},{"id":"c","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Правилото важи при проверените условия: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Прекадрирай за вертикален екран с нова визуална йерархия, не като механично изрязване на хоризонталния кадър.","Първо: Избери кое доказателство е най-важно за вертикалната версия. После: Премести камерата или направи отделен близък/среден кадър.","Следи за грешния ход: Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.","items":[{"id":"s3","text":"Остави чиста зона за субтитри и провери наложения интерфейс."},{"id":"s2","text":"Премести камерата или направи отделен близък/среден кадър."},{"id":"s1","text":"Избери кое доказателство е най-важно за вертикалната версия."},{"id":"s4","text":"Гледай експортирания файл в приложението и тествай четливостта."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда. Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Широк кадър показва двете ръце и колелото.\n\nПроменено условие: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами.\n\nКой ход проверяваш първо?","options":[{"id":"a","label":"Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието."},{"id":"b","label":"Разчиташ на автоматичен автоматично изрязване, който следи лице, но игнорира предмета, върху който се учи."},{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Приложи корекцията към новото условие: Направи проверка за три неща: очи/ръце остават видими; текст не закрива доказателството; интерфейс не скрива условието. Запиши отделна версия при нужда. Границата тук е: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.\n\nКарта за работа — Прекадрирай композицията за вертикален екран\n1. Избери кое доказателство е най-важно за вертикалната версия.\n2. Премести камерата или направи отделен близък/среден кадър.\n3. Остави чиста зона за субтитри и провери наложения интерфейс.\n4. Гледай експортирания файл в приложението и тествай четливостта.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: Instagram Help — Safe zone for partnership ads: https://help.instagram.com/864398265379023 (провери актуалната версия преди публикуване)."},"required":false,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-21","title":"Заснеми последователност, която доказва умението ти","objective":"да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел","hook":"Технически красиви кадри не образуват завършено видео, ако посоката, звукът и смисълът се разминават.","subtitle":"Камера, светлина, звук и композиция","estimated_minutes":30,"change_note":"Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Технически красиви кадри не образуват завършено видео, ако посоката, звукът и смисълът се разминават.\n\nТази проверка е по-евтина преди снимането, отколкото след като материалът вече е записан."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принципът","content":{"body":"Заснеми завършена последователност, която доказва умението от начално състояние до резултат така че зрителят да проследи умението по действието и резултата."},"required":true,"points":2},{"key":"deep_dive","type":"rich_text","title":"Как работи в детайл","content":{"body":"Снимачната последователност включва установяващ кадър, действие, ключов детайл, реакция/резултат и кадър за изход. Всеки план трябва да поддържа ориентация и монтаж; еднаква посока, размери и движение пазят непрекъснатостта. Прослушай звука, провери фокус и цветови съвпадения, после експортирай и отвори файла.\n\nГраница на правилото: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.\n\nВтори контрол: сравни планирания ход с най-вероятния провал — Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки. — и се увери, че корекцията действително премахва тази причина."},"required":true,"points":2},{"key":"method","type":"rich_text","title":"Работен ред","content":{"body":"Работи в този ред. Всеки ход трябва да остави следа, която колега може да провери:\n\n1. Запиши целта, началното състояние и какъв видим резултат ще доказва процеса.\n2. Сними установяващ, среден, детайлен и завършващ план с посока на действие.\n3. Провери звук, експозиция, фокус, баланс, разрешения и резервно копие.\n4. Монтирай, експортирай и направи финална проверка на телефон.\n\nСтоп-сигнал: Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки. Нито процесът, нито звукът, нито техническата версия са проверени. Ако това се случи, приложи корекцията преди да продължиш: Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр."},"required":true,"points":2},{"key":"worked_example","type":"example","title":"Разгледай решен пример","content":{"body":"Финалната задача е 30–45 секунди от подготовка на глина до първата оформена стена: широк кадър установява мястото; средният показва инструктор и участник; близкият доказва центрирането; реакция показва резултат; финалът казва какво следва с точни условия. Във всички планове ръцете се движат в една и съща посока и цветът не скача.\n\nРешение в този случай:\nИзползвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр.\n\nГраница на извода:\nКадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл."},"required":true,"points":2},{"key":"before_after","type":"before_after","title":"Грешен ход и корекция","content":{"before":{"label":"Проблемният избор","text":"Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки. Нито процесът, нито звукът, нито техническата версия са проверени."},"after":{"label":"По-доброто решение","text":"Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр.\n\nПреди да продължиш: Монтирай, експортирай и направи финална проверка на телефон."}},"required":true,"points":2},{"key":"field_diagnostic","type":"rich_text","title":"Провери решението в работни условия","content":{"body":"Заснеми установяващ, среден, детайлен и завършващ кадър така, че монтажът да покаже едно действие от начало до резултат. Запиши преходните моменти и чист звук от помещението; не разчитай, че монтажът ще измисли липсваща стъпка. Направи резервно копие преди форматиране на картата.\n\nКритерий за приемане: Монтирай, експортирай и направи финална проверка на телефон.\n\nКогато пробата се провали:\nСимптом: Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки.\nКорекция: Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери.\nСлед корекцията повтори същата проверка при същите условия, за да видиш дали причината действително е отстранена.\n\nГраница за пренасяне: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.\n\nАртефакт за листа за камера: запиши кадровата честота, затвора, експозицията, баланса, фокуса и името на тестовия файл; не разчитай на паметта. Повтори теста при смяна на стая, светлина, камера или формат; стойността в менюто не предсказва автоматично как ще изглежда финалният файл."},"required":true,"points":2},{"key":"knowledge_check","type":"quiz","title":"Провери основния принцип","content":{"question":"Кое правило най-точно описва умението „Заснеми последователност, която доказва умението ти“?","options":[{"id":"a","label":"Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки."},{"id":"b","label":"Винаги избирай най-високата настройка и разчитай монтажът да поправи останалото."},{"id":"c","label":"Заснеми завършена последователност, която доказва умението от начално състояние до резултат така че зрителят да проследи умението по действието и резултата."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото е: Заснеми завършена последователност, която доказва умението от начално състояние до резултат така че зрителят да проследи умението по действието и резултата. Слабият ход е: Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки. Нито процесът, нито звукът, нито техническата версия са проверени. Прилагай решението само след тази проверка."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"decision_case","type":"scenario","title":"Реши работната ситуация","content":{"prompt":"Ситуация: Финалната задача е 30–45 секунди от подготовка на глина до първата оформена стена: широк кадър установява мястото; средният показва инструктор и участник; близкият доказва центрирането; реакция показва резултат; финалът казва какво следва с точни условия. Във всички планове ръцете се движат в една и съща посока и цветът не скача.\n\nКое е първото решение, което защитава целта и позволява проверка?","options":[{"id":"a","label":"Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се…"},{"id":"b","label":"Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки."},{"id":"c","label":"Запази настройката по подразбиране, дори ако тестовият дубъл показва проблем."}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Избери ход, който можеш да покажеш или провериш: Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр. Грешният път — Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки. — оставя риска нерешен. Провери и границата: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"boundary_check","type":"quiz","title":"Провери границата","content":{"question":"Кое ограничение трябва да остане видимо при „Заснеми последователност, която доказва умението ти“?","options":[{"id":"a","label":"Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки."},{"id":"b","label":"Един и същ подход е правилен при всички хора, места, устройства и условия."},{"id":"c","label":"Кадрите в урока са учебен пример, не доказателство за студентски умения."}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Правилото важи при проверените условия: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл. Не го превръщай в универсален шаблон; ако условията се променят, провери отново."},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["Заснеми завършена последователност, която доказва умението от начално състояние до резултат така че зрителят да проследи умението по действието и резултата.","Първо: Запиши целта, началното състояние и какъв видим резултат ще доказва процеса. После: Сними установяващ, среден, детайлен и завършващ план с посока на действие.","Следи за грешния ход: Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки."],"nextStep":"Към своя проект запиши тест при реалната светлина и звук; провери кадъра, после отвори изнесения файл на целевия екран. Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл."},"required":true,"points":1},{"key":"sequence_practice","type":"sequence_sort","title":"Подреди работния процес","content":{"instruction":"Подреди стъпките по зависимостите в тази ситуация, а не по това, което е най-удобно да направиш първо. Условието трябва да е ясно преди избора; тестът трябва да е направен преди предаването. Граница: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.","items":[{"id":"s3","text":"Провери звук, експозиция, фокус, баланс, разрешения и резервно копие."},{"id":"s4","text":"Монтирай, експортирай и направи финална проверка на телефон."},{"id":"s2","text":"Сними установяващ, среден, детайлен и завършващ план с посока на действие."},{"id":"s1","text":"Запиши целта, началното състояние и какъв видим резултат ще доказва процеса."}]},"evaluation":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Правилният ред пази зависимостите между наблюдението, избора и проверката. Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр. Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл."},"scoring":{"mode":"exact_order"},"required":false,"points":2},{"key":"scenario_transfer","type":"scenario","title":"Реши случая при новото условие","content":{"prompt":"Продължение на случая: Финалната задача е 30–45 секунди от подготовка на глина до първата оформена стена: широк кадър установява мястото; средният показва инструктор и участник; близкият доказва центрирането; реакция показва резултат; финалът казва какво следва с точни условия.\n\nПроменено условие: Кадрите в урока са учебен пример, не доказателство за студентски умения.\n\nКой ход проверяваш първо?","options":[{"id":"c","label":"Промени няколко настройки едновременно и оцени само екрана на камерата, без да прегледаш файла."},{"id":"b","label":"Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери."},{"id":"a","label":"Снимаш един общ кадър, разчиташ на цифрово приближаване за детайл и предаваш без слушалки."}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Приложи корекцията към новото условие: Използвай контролен списък и автоматично оценим преглед: избери правилния ред на кадрите, намери грешката в настройките и посочи кое условие трябва да се провери. Запиши отделно качествени бележки за следваща версия, без да ги превръщаш в задължителен текстов формуляр. Границата тук е: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл. Направи новата проверка в променената ситуация; резултатът от първия случай не доказва, че същият ход ще работи навсякъде."},"scoring":{"mode":"single_choice"},"required":true,"points":3},{"key":"field_note","type":"rich_text","title":"Бележка от практиката","content":{"body":"Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.\n\nЛист за дубъла: файл и времеви код; ориентация/резолюция; кадри за секунда и затвор; ISO/експозиция; фокус; баланс на бялото; микрофон; дубъл; версия за предаване. Сравни настройките, вместо да разчиташ на памет.\n\nКарта за работа — Заснеми последователност, която доказва умението ти\n1. Запиши целта, началното състояние и какъв видим резултат ще доказва процеса.\n2. Сними установяващ, среден, детайлен и завършващ план с посока на действие.\n3. Провери звук, експозиция, фокус, баланс, разрешения и резервно копие.\n4. Монтирай, експортирай и направи финална проверка на телефон.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."},"required":false,"points":1}]}]$pv_v42_payload$::jsonb;
 lesson_spec jsonb;
 block_rec record;
 target public.academy_lessons%ROWTYPE;
 v41_version uuid;
 v42_version uuid;
 v_validation jsonb;
 required_count integer;
 quiz_count integer;
 scenario_count integer;
 sort_count integer;
 unique_count integer;
 visible_chars integer;
 m1_count integer;
 m2_count integer;
 m3_count integer;
 inserted_count integer := 0;
 skipped_count integer := 0;
 block_id uuid;
 source_marker text := 'perfect_video_modules_1_3_curriculum_v4_2_drafts';
 v41_marker text := 'perfect_video_modules_1_3_curriculum_v4_drafts';
BEGIN
 IF jsonb_array_length(specs) <> 65 THEN
  RAISE EXCEPTION 'Expected 65 lesson specs';
 END IF;
 SELECT count(DISTINCT value->>'lesson_id') INTO unique_count
 FROM jsonb_array_elements(specs) AS x(value);
 IF unique_count <> 65 THEN RAISE EXCEPTION 'Lesson IDs are not unique'; END IF;
 SELECT
  count(*) FILTER (WHERE value->>'module_id'='s02-m01'),
  count(*) FILTER (WHERE value->>'module_id'='s02-m02'),
  count(*) FILTER (WHERE value->>'module_id'='s02-m03')
 INTO m1_count,m2_count,m3_count
 FROM jsonb_array_elements(specs) AS x(value);
 IF m1_count <> 24 OR m2_count <> 20 OR m3_count <> 21 THEN
  RAISE EXCEPTION 'Unexpected module counts: %, %, %',m1_count,m2_count,m3_count;
 END IF;

 FOR lesson_spec IN
  SELECT value FROM jsonb_array_elements(specs) AS x(value)
 LOOP
  IF lesson_spec->>'module_id' NOT IN ('s02-m01','s02-m02','s02-m03') THEN
   RAISE EXCEPTION 'Unexpected module ID: %',lesson_spec->>'module_id';
  END IF;
  IF jsonb_array_length(lesson_spec->'blocks') <> 15 THEN
   RAISE EXCEPTION 'Lesson % does not have 15 blocks',lesson_spec->>'lesson_id';
  END IF;

  SELECT
   count(*) FILTER (WHERE value->>'required'='true'),
   count(*) FILTER (WHERE value->>'type'='quiz'),
   count(*) FILTER (WHERE value->>'type'='scenario'),
   count(*) FILTER (WHERE value->>'type'='sequence_sort'),
   coalesce(sum(length((value->'content')::text)+length(value->>'title')),0)
  INTO required_count,quiz_count,scenario_count,sort_count,visible_chars
  FROM jsonb_array_elements(lesson_spec->'blocks') AS x(value);
  IF required_count <> 13 OR quiz_count <> 2 OR scenario_count <> 2 OR sort_count <> 1 THEN
   RAISE EXCEPTION 'Unexpected block structure for %',lesson_spec->>'lesson_id';
  END IF;
  IF visible_chars < 7800 THEN
   RAISE EXCEPTION 'Visible learner content below 7800 characters for %: %',lesson_spec->>'lesson_id',visible_chars;
  END IF;
  IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(lesson_spec->'blocks') AS x(value)
   WHERE value->>'type' IN ('practical_response','reflection','homework','submission','prompt_builder')
  ) THEN
   RAISE EXCEPTION 'Open response block found in %',lesson_spec->>'lesson_id';
  END IF;
  IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(lesson_spec->'blocks') AS x(value)
   WHERE value->>'type' IN ('quiz','scenario','sequence_sort')
     AND NOT (value ? 'evaluation')
  ) THEN
   RAISE EXCEPTION 'Missing evaluation key in %',lesson_spec->>'lesson_id';
  END IF;
  IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(lesson_spec->'blocks') AS x(value)
   WHERE value->>'type' IN ('quiz','scenario')
     AND jsonb_array_length(value->'content'->'options') <> 3
  ) THEN
   RAISE EXCEPTION 'Choice block must have three options in %',lesson_spec->>'lesson_id';
  END IF;

  SELECT * INTO target
  FROM public.academy_lessons
  WHERE module_id=lesson_spec->>'module_id'
    AND lesson_id=lesson_spec->>'lesson_id'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Lesson not found: %',lesson_spec->>'lesson_id'; END IF;
  IF target.status <> 'published' OR target.published_version_id IS NULL THEN
   RAISE EXCEPTION 'Lesson is not published: %',lesson_spec->>'lesson_id';
  END IF;

  SELECT a.version_id INTO v42_version
  FROM public.academy_lesson_audit a
  WHERE a.academy_lesson_id=target.id
    AND a.action='saved'
    AND a.details->>'migration_source'=source_marker
  ORDER BY a.id DESC
  LIMIT 1;
  IF v42_version IS NOT NULL THEN
   skipped_count:=skipped_count+1;
   CONTINUE;
  END IF;

  SELECT a.version_id INTO v41_version
  FROM public.academy_lesson_audit a
  WHERE a.academy_lesson_id=target.id
    AND a.action='saved'
    AND a.details->>'migration_source'=v41_marker
  ORDER BY a.id DESC
  LIMIT 1;
  IF v41_version IS NULL THEN
   RAISE EXCEPTION 'v4.1 draft not found for %',lesson_spec->>'lesson_id';
  END IF;
  IF target.draft_version_id IS DISTINCT FROM v41_version THEN
   RAISE EXCEPTION 'Draft changed since v4.1; will not overwrite administrator work: %',lesson_spec->>'lesson_id';
  END IF;

  INSERT INTO public.academy_lesson_versions(
   academy_lesson_id,version_number,origin_version_id,title,subtitle,duration,
   objective,hook,estimated_minutes,source_kind,validation,change_note,created_by
  )
  VALUES(
   target.id,
   (SELECT coalesce(max(version_number),0)+1 FROM public.academy_lesson_versions WHERE academy_lesson_id=target.id),
   target.draft_version_id,
   lesson_spec->>'title',
   coalesce(lesson_spec->>'subtitle',''),
   (lesson_spec->>'estimated_minutes') || ' минути',
   lesson_spec->>'objective',
   lesson_spec->>'hook',
   (lesson_spec->>'estimated_minutes')::integer,
   'editor',
   '{}'::jsonb,
   lesson_spec->>'change_note',
   NULL
  )
  RETURNING id INTO v42_version;

  FOR block_rec IN
   SELECT value,ordinality
   FROM jsonb_array_elements(lesson_spec->'blocks') WITH ORDINALITY AS x(value,ordinality)
  LOOP
   INSERT INTO public.academy_lesson_blocks(
    version_id,block_key,position,block_type,title,content,required,points
   )
   VALUES(
    v42_version,
    block_rec.value->>'key',
    block_rec.ordinality::integer-1,
    block_rec.value->>'type',
    block_rec.value->>'title',
    block_rec.value->'content',
    coalesce((block_rec.value->>'required')::boolean,false),
    coalesce((block_rec.value->>'points')::integer,0)
   )
   RETURNING id INTO block_id;

   IF block_rec.value ? 'evaluation' THEN
    INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
    VALUES(
     block_id,
     block_rec.value->'evaluation',
     coalesce(block_rec.value->'feedback','{}'::jsonb),
     coalesce(block_rec.value->'scoring','{}'::jsonb)
    );
   END IF;
  END LOOP;

  v_validation:=academy_private.lesson_validation(v42_version);
  IF coalesce(jsonb_array_length(v_validation->'errors'),0) > 0
     OR coalesce(jsonb_array_length(v_validation->'warnings'),0) > 0 THEN
   RAISE EXCEPTION 'Validation failed for %: %',lesson_spec->>'lesson_id',v_validation;
  END IF;
  UPDATE public.academy_lesson_versions
  SET validation=v_validation
  WHERE id=v42_version;
  UPDATE public.academy_lessons
  SET draft_version_id=v42_version,updated_at=clock_timestamp()
  WHERE id=target.id;

  INSERT INTO public.academy_lesson_audit(
   academy_lesson_id,version_id,actor_id,action,details
  )
  VALUES(
   target.id,v42_version,NULL,'saved',
   jsonb_build_object(
    'migration_source',source_marker,
    'requires_admin_review',true,
    'blocks',15,
    'required_blocks',13,
    'optional_blocks',2,
    'auto_graded_scenarios',2,
    'student_facing',false,
    'published_version_unchanged',true,
    'progress_unchanged',true
   )
  );
  inserted_count:=inserted_count+1;
 END LOOP;

 IF inserted_count+skipped_count <> 65 THEN
  RAISE EXCEPTION 'Expected 65 processed lessons, got % inserted and % already seeded',inserted_count,skipped_count;
 END IF;
END
$pv_v42_seed$;
